//  pas = pascal(n)
//  nCk = pas(k)
//  n = 0 に対応していない
object Pascal{
  val MOD = 1e9.toInt + 7

  def pascal(n: Int): Array[List[Int]] = {
    // 次の段を作る
    def makeNext(list: List[Int], res: List[Int]): List[Int] = {
      list match{
        case x :: Nil => (1 :: res).reverse
        case x :: y :: list2 => makeNext(y :: list2, ((x+y)%MOD) :: res)
        case _ => throw new Exception("invalid list")
      }
    }

    // n回再起
    def pascalFunc(list: List[Int], res: List[List[Int]]): Array[List[Int]] = {
      (list.length > n) match{
        case true  => res.reverse.toArray
        case false =>
          val tmp = makeNext(list, List(1))
          pascalFunc(tmp, tmp :: res)
      }
    }

    pascalFunc(List(1), List())
  }
}



