  fact[0]=inv[0]=1;

  for(int i=1;i<=n;i++)
    fact[i]=fact[i-1]*i%MOD;

  inv[n]=beki(fact[n],MOD-2);

  for(int i=n-1;i>=1;i--)
    inv[i]=((i+1)*inv[i+1])%MOD;
}

