const ll md = 1e9 + 7;
ll N[100001] = {1};
ll D[100001] = {1};

ll sq(ll x) { return x * x; }

ll pow_mod(ll x, ll n) {
    ll a = 1ll;
    while (n) {
        if (n % 2) a = 1ll * a * x % md;
        x = x * x % md;
        n /= 2;
    }
    return a;
}

ll rev_mod(ll x) { return pow_mod(x, md - 2ll); }

void calc_fd(ll n) {
    for (int i = 1; i <= n + 1; i++) {
        N[i] = (i * N[i - 1]) % md;
        D[i] = rev_mod(N[i]);
    }
}

int ncr(int n, int r) { return ((N[n] * D[r] % md) * D[n - r]) % md; }

ll calc(int n, int k, int l, int r) {
    return ncr(n + 1, k) - ncr(l + n - r, k - 1);
}

