typedef ll MOD_POW_TYPE;
MOD_POW_TYPE mod_pow(MOD_POW_TYPE x, MOD_POW_TYPE n, MOD_POW_TYPE mod) {
	MOD_POW_TYPE res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % mod; // 最下位ビットが立っているときにx^(2^i)を掛ける
		x = x * x % mod; // xを順次二乗していく
		n >>= 1;
	}
	return res;
}

ll C(ll n,ll k) {
	if(n < 0) {
		return 0;
	}
	if(n == 0) {
		return 1;
	}

	ll shi = 1;
	REP(i,k) {
		shi *= (n - i);
		shi %= p;
	}
	ll bo = 1;
	REP(i,k) {
		bo *= (i + 1);
		bo %= p;
	}

	shi *= mod_pow(bo,p - 2,p);
	shi %= p;
	return shi;
}

