// functions
struct ModCombination {
    const int Size;
    const ll MOD;
    vl fact;
    vl inv_fact;

    ll pow(ll a, ll n) {
        ll res = 1;
        while (n > 0) {
            if (n & 0x01) { 
                res *= a;
                res %= MOD;
            }
            a = a*a;
            a %= MOD;
            n >>= 1;
        }
        return res;
    }

    ll inv(ll num) {
        return pow(num, MOD - 2);
    }

    ModCombination(const int SIZE, const int MOD) 
        : Size(SIZE), MOD(MOD) {
        fact = vl(Size);
        fact[0] = 1;
        FOR (i,1,Size) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        inv_fact = vl(Size);
        inv_fact[0] = 1;
        inv_fact[Size-1] = inv(fact[Size-1]);
        for (int i = Size - 1; i > 0; i--) {
            inv_fact[i - 1] = inv_fact[i] * i % MOD;
        }
    }

    ll C(ll n, ll r) {
        if (n < 0 || r < 0 || n < r) return 0;
        return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD;
    }

    ll P(ll n, ll r) {
        if (n < 0 || r < 0 || n < r) return 0;
        return fact[n] * inv_fact[n - r] % MOD;
    }
};

template<ll MOD>
struct ModLL {
    ll val;
    ModLL() :val(0) {}
    ModLL(ll v) : val(v >= 0 ? v % MOD : (MOD - (-v) % MOD) % MOD) {}

    ModLL operator -() const { return ModLL(-val); }

    ModLL& operator +=(const ModLL& r) {
        val += r.val;
        if (val >= MOD) val -= MOD;
        return (*this);
    }
    ModLL operator +(const ModLL& r) const {
        return ModLL(*this) += r;
    }

    ModLL& operator -=(const ModLL& r) {
        val += MOD - r.val;
        if (val >= MOD) val -= MOD;
        return (*this);
    }
    ModLL operator -(const ModLL& r) const {
        return ModLL(*this) -= r;
    }

    ModLL& operator *=(const ModLL& r) {
        val *= r.val;
        if (val >= MOD) val %= MOD;
        return (*this);
    }
    ModLL operator *(const ModLL& r) const {
        return ModLL(*this) *= r;
    }

    ModLL& operator /=(const ModLL& r) {
        (*this) *= r.inv();
        return (*this);
    }
    ModLL operator /(const ModLL& r) const {
        return ModLL(*this) /= r;
    }

    bool operator ==(const ModLL& r) {
        return val == r.val;
    }
    bool operator !=(const ModLL& r) {
        return val != r.val;
    }

    ModLL pow(ll n) const {
        ll tmp = val;
        ll ret = 1;
        while (n > 0) {
            if (n & 0x01) {
                ret *= tmp;
                ret %= MOD;
            }
            tmp = tmp * tmp;
            tmp %= MOD;
            n >>= 1LL;
        }
        return ModLL(ret);
    }

    ModLL inv() const {
        ll a = val, b = MOD, u = 1, v = 0;
        while (b > 0) {
            ll t = a / b;
            a -= t * b; swap(a, b);
            u -= t * v; swap(u, v);
        }
        return ModLL(u);
    }

    friend istream& operator >>(istream &is, ModLL<MOD> &r) {
        ll t; is >> t;
        r = ModLL<MOD>(t);
        return is;
    }
    friend ostream& operator <<(ostream &os, const ModLL<MOD> &r) {
        return os << r.val;
    }
};
