map<pair<int,int>, int> dp;
int n, aray[100010];
const int M = 1e9+7;

int solve(int i, int len)
{
    if(len == 0) return 1;
    if(i > n || n-i+1 < len) return 0;
    map<pair<int,int>,int>::iterator it;
    it = dp.find(make_pair(i,len));
    if(it != dp.end()) return it->second;

    long long ways = solve(i+1,len) % M;
    ways = (ways + solve(i+1,len-1)) % M;

    dp[make_pair(i,len)] = ways;
    return ways;
}

