const ll factorial_max = 1e5 + 7;
struct factorial {
    vector<mint> fact;
    mint permutation(ll n, ll r)
    {
        if (n < 0 || r < 0) {
            return 0;
        }
        mint value = this->fact[n];
        value /= this->fact[n - r];
        return value;
    }
    mint combination(ll n, ll r)
    {
        if (n < 0 || r < 0) {
            return 0;
        }
        mint value = permutation(n, r);
        value /= this->fact[r];
        return value;
    }

    void init_factorial()
    {
        this->fact = vector<mint>(factorial_max + 1);
        this->fact[0] = 1;
        for (ll i = 1; i <= factorial_max; ++i) {
            this->fact[i] = this->fact[i - 1] * i;
        }
    }
    explicit factorial() { this->init_factorial(); }
};
