//ユークリッドの互除法
long long gcd( long long a, long long b ) {
    ll quotient;//商
    ll remainder;//余り
    while ( b > 0 ) {
        quotient = b / a;
        remainder = b % a;
        b = a;
        if( remainder == 0 )
            break;

        a = remainder;
    }
    return a;
}

//拡張ユークリッドの互除法
void exGcd( ll x, ll y, ll* a, ll* b, ll *c ) {
    ll a0 = 1;
    ll a1 = 0;
    ll a2 = 0;
    ll b0 = 0;
    ll b1 = 1;
    ll b2 = 0;
    ll r0 = x;
    ll r1 = y;
    ll r2 = 1;

    while ( r1 > 0 ) {
        ll q1 = r0 / r1;
        r2 = r0 % r1;
        a2 = ( a0 - q1 * a1 % MOD ) % MOD;
        b2 = ( b0 - q1 * b1 % MOD ) % MOD;
        a0 = a1;
        a1 = a2;
        b0 = b1;
        b1 = b2;
        r0 = r1;
        r1 = r2;
        /* cout << q1 << "," << r2 << endl; */
        /* cout << a2 << "," << b2 << "," << r2 << endl; */
    }
    *a = a0;
    *b = b0;
    *c = r0;
}

ll invMod( long long a, long long m ) {
    ll aa, bb, cc;
    exGcd( m, a, &aa, &bb, &cc );
    return ( bb < 0 ) ? bb + m : bb;
}

