const int mod = 1e9 + 7;
int fact[100000+10];
int a[100000 + 10];

int Pow(int a, int n) {
    if (a == 1)
        return 1;
    int res = 1;
    while (n) {
        if (n&1) {
            res = (1LL * res * a) % mod;
        }
        a = (1LL * a*a) % mod;
        n >>= 1;
    }
    return res;
}

int inverse(int a, int mod) {
    return Pow(a, mod-2);
}

int c_n_k(int n, int k) {
    if (k > n)
        return 0;
    if (n <= 0)
        return 0;
    if (k < 0)
        return 0;
    if (k == 0)
        return 1;
    else
        return ((1LL * ((1LL * fact[n] * inverse(fact[k], mod)) % mod) * inverse(fact[n-k], mod)) % mod) % mod;
}

void solve() {
    int n;
