const ll MOD = 1e9 + 7;

ll modpow(ll r, ll n, ll m = MOD) {
  ll re = 1, d = r % m;
  if (n < 0) (n %= m - 1) += m - 1;
  for (; n; n /= 2) {
    if (n & 1) (re *= d) %= m;
    (d *= d) %= m;
  }
  return re;
}
template <int mod = MOD>
struct modInt {
  int v;
  modInt(int v = 0) : v(v) {}
  modInt operator+(const modInt &n) {
    return v + n.v < mod ? v + n.v : v + n.v - mod;
  }
  modInt operator-(const modInt &n) {
    return v - n.v < 0 ? v - n.v + mod : v - n.v;
  }
  modInt operator*(const modInt &n) { return ll(v) * n.v % mod; }
  modInt operator/(const modInt &n) {
    return ll(v) * modpow(n.v % mod, -1, mod) % mod;
  }
  template <class T>
  modInt operator+(const T &n) {
    return v + n < mod ? v + n : v + n - mod;
  }
  template <class T>
  modInt operator-(const T &n) {
    return v - n < 0 ? v - n + mod : v - n;
  }
  template <class T>
  modInt operator*(const T &n) {
    return ll(v) * (n % mod) % mod;
  }
  template <class T>
  modInt operator/(const T &n) {
    return ll(v) * modpow(n % mod, -1, mod) % mod;
  }
  modInt &operator+=(const modInt &n) {
    v += n.v;
    if (v >= mod) v -= mod;
    return *this;
  }
  modInt &operator-=(const modInt &n) {
    v -= n.v;
    if (v < 0) v += mod;
    return *this;
  }
  modInt &operator*=(const modInt &n) {
    v = ll(v) * n.v % mod;
    return *this;
  }
  modInt &operator/=(const modInt &n) {
    v = ll(v) * modpow(n.v, -1, mod) % mod;
    return *this;
  }
  template <class T>
  modInt &operator+=(const T &n) {
    v += n;
    if (v >= mod) v -= mod;
    return *this;
  }
  template <class T>
  modInt &operator-=(const T &n) {
    v -= n;
    if (v < 0) v += mod;
    return *this;
  }
  template <class T>
  modInt &operator*=(const T &n) {
    v = ll(v) * n % mod;
    return *this;
  }
  template <class T>
  modInt &operator/=(const T &n) {
    v = ll(v) * modpow(n, -1, mod) % mod;
    return *this;
  }
};
template <int mod>
ostream &operator<<(ostream &os, const modInt<mod> &n) {
