#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i, m, n) for(int i = (int)(m); i < (int)(n); ++i)

const int MOD = 1e+9 + 7;

template <typename T>
T pow_mod( T n, T p )  // n^p % m
{
    if( p == 0 ) return 1;
    if( p%2 == 1 ) return pow_mod(n, p-1) * n % MOD;
    else{
        T tmp = pow_mod(n, p/2) % MOD;
        return tmp*tmp % MOD;
    }
}

int main()
{
    int n;
    cin >> n;
    vector<int> a(n+1);
    REP(i, n+1) cin >> a[i];
    cout << 100;

    vector<int> num_appeared(n+1, 0);
    REP(i, n) ++num_appeared[a[i]];

    int num;
    REP(i, n+1){
        if(num_appeared[i] == 2) num = i;
    }
    int l = 1e+9, r = 0; // l, r: 同じ数字が現れる位置 (l < r)
    REP(i, n){
        if(a[i] == num){
            l = max(l, i);
            r = min(r, i);
        }
    }

    int m = l+n-r;
    vector<long long> mCk(m+1);
    mCk[0] = 1;
    FOR(i, 1, m){
        mCk[i] = mCk[i-1] * (m-i+1)*pow_mod<long long>(i, MOD-2) % MOD;
        mCk[i] %= MOD;
    }

    cout << 2;
    long long ans = 1;
    FOR(i, 1, n+2){ // i 枚取るとき
        ans *= (n+1-(i-1)) * pow_mod<long long>(i, MOD-2) % MOD;
