vector<ll> ifac(300001); //k! ^ {M - 2} (mod M)
//a,bの範囲的にこれだけ配列を用意していけば十分

void Factorial(){
	fac[0] = 1;
	for(ll i = 0; i < 300000; i++) fac[i + 1] = fac[i] * (i + 1) % MOD; // n!(mod M)
	return;
}

ll Pow(ll x, ll n){ //x^n(mod M) ←普通にpow(x, n)では溢れてしまうため，随時mod計算
    ll ans = 1;
    while(n != 0){
        if(n & 1) ans = ans * x % MOD;
        x = x * x % MOD;
        n = n >> 1;
    }
    return ans;
}

void Reciprocal(){
	ifac[0] = 1;
	for(ll i = 0; i < 300000; i++) ifac[i + 1] = ifac[i] * Pow(i + 1, MOD - 2) % MOD; // k! ^ {M - 2} (mod M) ←累乗にmpowを採用
	return;
}

ll nCr(ll a, ll b){ //aCbをmod計算
    if(a == 0 && b == 0) return 1;
    if(a < b || a < 0) return 0;
    ll tmp = (ifac[a - b] * ifac[b]) % MOD;
    return (tmp * fac[a]) % MOD;
}

