    rep(i, n) {
        int a; cin >> a;
        if(mp[a] != 0) {
            L = mp[a];
            R = i + 1;
        }
        mp[a] = i + 1;
    }
    combination C(n+1);
    //printf("L:%d R:%d\n", L, R);
    if(n==1) {
        printf("%d\n%d\n", 1, 1);
        return 0;
    }
    for(int k=1;k<=n+1;k++) {
        ll x = C(n+1, k).x;
