constexpr int MX = ten(5) + 10;

constexpr int MOD = ten(9) + 7;

constexpr ll sqr(const ll &n) { return n*n; }

ll modPow(ll n, int p)
{
    if (p <= 0) return 1;
    ll x = sqr(modPow(n, p/2)) % MOD;
    if (p & 1) x = x*n % MOD;

    return x;
}

ll modInv(ll n) { return modPow(n, MOD-2); }

template<int MOD>
class Factorial
{
    vector<ll> f;
public:
    explicit Factorial(int n): f(++n) {
        f[0] = f[1] = 1;
        for(ll i=2; i < n; ++i) f[i] = i*f[i-1] % MOD;
    }
    const ll operator() (int i) const { return f[i]; }
};

template<int MOD>
class Combination
{
    using Fact = Factorial<MOD>;
    const Fact& fact;

public:
    explicit Combination(const Fact &fact): fact(fact) {}

    ll operator() (int n, int r) const {
        if (n < r) return 0;
        return fact(n) * modInv(fact(r)) % MOD * modInv(fact(n-r)) % MOD;
    }

};

