#define MOD (1000000000+7)
#define MAX 100000

long long fac[MAX + 1];
long long ifac[MAX + 1];

long long mpow( long long x, long long n )
{
	long long ans = 1;
	while( n != 0 ) {
		if( n & 1 ) {
			ans = ans * x % MOD;
		}
		x = x * x % MOD;
		n = n >> 1;
	}
	return ans;
}

long long comb( long long a, long long b)
{
	if( a == 0 && b == 0 ) {
		return 1;
	}
    if( a < b || a < 0 ) {
		return 0;
	}
	long long tmp = ifac[a - b] * ifac[b] % MOD;
	return tmp * fac[a] % MOD;
}

