const ll MOD=1e9+7;
ll kai[100002];
ll gyaku[100002];
ll modpow(ll n,ll a)
{
	ll ret=1;
	ll nn=n;
	while(a>0)
	{
		if(a&1)
		{
			ret*=nn;
			ret%=MOD;
		}
		nn=nn*nn;
		nn%=MOD;
		a>>=1;
	}
	return ret;
}

ll combi(int a,int b)
{
	ll ret=kai[a]*gyaku[b];
	ret%=MOD;
	ret*=gyaku[a-b];
	ret%=MOD;
	return ret;
}

