		}
	}
	kai[0]=1;
	gyaku[0]=modpow(kai[0],MOD-2);
	for(ll i=1;i<100002;i++)
	{
		kai[i]=(kai[i-1]*i+MOD)%MOD;
		gyaku[i]=modpow(kai[i],MOD-2);
	}
