ll nCr(ll n, ll r){
  if (n == r || r == 0)
    return 1;
  else
    return nCr(n, r - 1) * (n - r + 1) / r;    
}

ll nCr_(ll n, ll r){
  if (n == r || r == 0)
    return 1;
  else
    return Per[n] * Per_inv[n-r] % mod * Per_inv[r] % mod;  
}

// a^b mod p
ll mod_pow(ll a, ll b){
    if(b==0) return 1;

    // 肩が奇数
    if(b%2==1){
        return a * mod_pow(a, b-1) % mod;
    }
    else{
        return mod_pow(a*a % mod, b/2) % mod;
    }
}

