ll mod_pow(ll x, ll k) {
    ll v = 1;
    for(; k > 0; k >>= 1) {
        if(k & 1) v = v * x % mod;
        x = x * x % mod;
    }
    return v;
}

void init_comb() {
    fact[0] = 1, fact[1] = 1;
    for(int i = 1; i < mxn-1; i++) {
        fact[i+1] = fact[i] * (i+1) % mod;
    }
    for(int i = 0;i < mxn; i++) {
        invfact[i] = mod_pow(fact[i], mod-2);
    }
}

ll comb(int n, int r) {
    if(n < r) return 0;
    ll ret = fact[n];
    ret = ret * invfact[n-r] % mod;
    ret = ret * invfact[r] % mod;
    return ret;
}


