ll select(int n, int k, ll *p){
   if(n == 0 || k > n){
      return 0;
   }else{
      p[k] = p[k-1] * (n - k + 1) % 1000000007;
      factrial_division[k] = factrial_division[k - 1] * modinv(k, 1000000007) % 1000000007;
      return p[k] * factrial_division[k] % 1000000007;
   }
}

