#include <bits/stdc++.h>
using namespace std;

constexpr int64_t MOD = 1000000007;

int64_t Factorial(int64_t x) {
  int64_t acc = 1;
  for (int i = 1; i <= x; ++i) {
    acc = acc * i % MOD;
  }
  return acc;
}

int64_t Power(int64_t base, int64_t exp) {
  if (exp == 0) return 1;
  if (exp % 2) {
    return base * Power(base, exp - 1) % MOD;
  } else {
    int64_t tmp = Power(base, exp / 2);
    return tmp * tmp % MOD;
  }
}

int64_t Combination(int64_t n, int64_t r) {
  if (r < 0 || n < r) return 0;
  // cout << n << ", " << n - r << ", " << r << endl;
  int64_t n_bang = Factorial(n);
  int64_t nr_bang = Factorial(n - r);
  int64_t r_bang = Factorial(r);
  int64_t x = n_bang;
  x = x * Power(nr_bang, MOD - 2) % MOD;
  x = x * Power(r_bang, MOD - 2) % MOD;
  return x;
}

