void init_kai(long long n){
    kai[0]=1;
    for(int i=1;i<=n;i++){
        kai[i]=kai[i-1]*i;
        kai[i]%=1000000007;
    }
    inv_kai[n]=mod_pow(kai[n],1000000007-2,1000000007);
    inv_kai[0]=1;
    for(long long i=n-1;i>0;i--){
        inv_kai[i]=inv_kai[i+1]*(i+1);
        inv_kai[i]%=1000000007;
    }
}

long long f(long long n, long long r) {
    long long bunsi=kai[n];
    long long inv_bunbo=(inv_kai[r]*inv_kai[n-r])%1000000007;
    return bunsi*inv_bunbo%1000000007;
}

