  // Comb() {}
  Comb(int MAX_N):fac(MAX_N,1),finv(MAX_N,1),inv(MAX_N,1),sinv(MAX_N,1) {init(MAX_N);}
  void init(int MAX_N){
    fac.assign(MAX_N,1),finv.assign(MAX_N,1),inv.assign(MAX_N,1),sinv.assign(MAX_N,1);
    sinv[0]=0;
    for(int i=2;i<MAX_N;i++){
      fac[i]=fac[i-1]*i;
      inv[i]=-inv[mod%i]*(mod/i);
      finv[i]=finv[i-1]*inv[i];
      sinv[i]=sinv[i-1]+inv[i];
    }
  }
  T com(int n,int k){ //1≦k≦n≦10^7
    if (n<k) return 0;
    if (n<0||k<0) return 0;
    return fac[n]*finv[k]*finv[n-k];
  }
  T per(int n,int k){ //1≦k≦n≦10^7
    if (n<k) return 0;
    if (n<0||k<0) return 0;
    return fac[n]*finv[n-k];
  }
};
