      l = indice[xs[i]];
      r = i;
    }
  }
  for (int k = 1; k <= n + 1; ++k) {
    int64_t x0, x1, x2;
    x0 = Combination(n + 1, k);
    x1 = Combination((l - 1) + (n + 1 - r), k - 1);
    x2 = (x0 - x1 + MOD) % MOD;
    cout << x2 << endl;
  }
}

