long long fact[100100];
void calcfact() {
    long long i;
    fact[0] = 1;
    fact[1] = 1;
    for (i = 2; i < 100000; i++) {
        fact[i] = fact[i - 1] * i;
        fact[i] %= MOD;
    }
}
long long power(long long a, long long b) {
    long long x = 1, y = a;
    while (b > 0) {
        if (b % 2) {
            x = (x*y) % MOD;
        }
        y = (y*y) % MOD;
        b /= 2;
    }
    return x % MOD;
}
long long inv(long long x) {
    return power(x, MOD - 2);
}
long long nCr(long long n, long long r) {
    return (fact[n] * (inv(fact[r])*inv(fact[n - r]) % MOD)) % MOD;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    calcfact();
    int n, a[100100], check[100100] = {}, one, two;
    cin >> n;
    for (int i = 0; i <= n; i++) {
        cin >> a[i];
        check[a[i]]++;
        if (check[a[i]] == 2)two = i;
    }
    for (int i = 0; i <= n; i++) {
        if (a[i] == a[two]) {
            one = i;
            break;
        }
    }
    for (int i = 1; i <= n + 1; i++) {
        cout << nCr(n + 1, i) - nCr(one+n-two , i - 1) << endl;
    }
    return 0;
}

