long long repeat_pow(long long x, int n){
	long long ans=1;

	while(n>0) {
		if((n&1)==1){
			ans=ans*x;
			if(ans>=MOD) ans%=MOD;
		}
		x=(x*x)%MOD; //一周する度にx, x^2, x^4, x^8となる
		n>>=1; //桁をずらす n = n >> 1
	}
	return ans;
}
