        cin>>A[n];
        if (prev.count(A[n]) > 0) dup = n;
        prev.insert(A[n]);
    }
    int first;
    for (int n = 0; n < dup; n++) {
        if (A[n] == A[dup]) {
            first = n;
            break;
        }
