    for (int k = 1; k <= N+1; k++) {
        ll ans = mt.com(N, k-1) - mt.com(N-dup+first, k-1);
        if (ans < 0) ans += mod;
        ans = (mt.com(N, k) + ans) % mod;
        cout<<ans<<endl;
    }
    return 0;
}

