const LL MAX_VAL=1000000007;
LL Cnm(int n,int m)
{
	int Max=max(m,n-m);
	int Min=min(m,n-m);
	LL n1=1;
	int i;
	int k=1;
	for (i=n;i>Max;i--){
		n1*=i;
		if (k<=Min){
			n1/=k;
			k++;
		}
	}
	n1%=MAX_VAL;
	return n1;
}
