ll modularExponentiation(ll x,ll n,ll MOD)
{
    ll result=1;
    while(n>0)
    {
        if(n % 2 ==1)
            result=(result * x)%MOD;
        x=(x*x)%MOD;
        n=n/2;
    }
    return result;
}

ll modInverse(ll A,ll MOD)
