    if(idx[a[i]] == -1) idx[a[i]] = i+1;
    else {
      l = idx[a[i]];
      r = i+1;
      break;
    }
  }
  for(int k = 1; k <= n+1; ++k) {
    mint ans = C(n+1, k) - C(l-r+n, k-1);
    cout << ans.x << endl;
  }
}

