ll D(int i,ll x){
	if(x==1){
		return (ll)i;
	}else if(x%2==0){
		ll a = D(i,x/2);
		return a*a%MOD;
	}else{
		ll b = D(i,x/2);
		return b*b%MOD*i%MOD;
	}
}

void C(ll ans[],int n){
	ll now=n+1;
	ans[1]=now;
	for(int i=2;i<=n+1;i++){
		now = now*(n+2-i)%MOD*D(i,MOD-2)%MOD;
		ans[i]=now;
	}
}

int main(void){
	int n;
	cin>>n;
	int a[100001];
	int b[100001];
	for(int i=0;i<n+1;i++){
		cin>>a[i];
		b[i]=a[i];
	}
	sort(a,a+n+1);
	int check = 0;
	for(int i=0;i<n;i++){
		if(a[i]==a[i+1]){
			check = a[i];
			break;
		}
	}
	int memo1,memo2;
	for(int i=0;i<n+1;i++){
		if(b[i]==check){
			memo1=i;
			break;
		}
	}

	for(int i=memo1+1;i<n+1;i++){
		if(b[i]==check){
			memo2 = i;
		}
	}

	ll ans[10005];

	C(ans,n);

	ll memo[10005];
	int k=2;
	memo[1]=1;
	ll now = n+1-(memo2-memo1)-1;
	memo[2]=now;
	for(int t=2;t<=n+1-(memo2-memo1)-1;t++){
		now = now*(n-(memo2-memo1)-t+1)%MOD*D(t,(MOD-2))%MOD;
		memo[t+1]=now;
		k = t+1;
	}
	for(int i=k+1;i<=n+1;i++){
		memo[i]=0;
	}

	for(int i=1;i<=n+1;i++){
		cout<<(ans[i]+MOD-memo[i])%MOD<<endl;
	}



	return 0;
}

