constexpr int mod = 1e9+7;

class combinationMod{
private:
    using LLi = long long int;
    static const int mod_number = 1e9+7;

    const int n; // 最大
    std::vector<LLi> Factional, invFactional, inv;

    // ユークリッドの互除法により逆元を求める関数
    LLi inverse_mod_euclid(LLi a, LLi mod_number___ = mod_number){
        LLi b = mod_number___, u = 1, v = 0;
        while (b != 0) { LLi t = a / b; a -= t * b; std::swap(a, b);
            u -= t * v; std::swap(u, v);}
        u %= mod_number___; if (u < 0) u += mod_number___;
        return u;
    }
public:
    // コンストラクタ
    combinationMod(int N): n(N){
        Factional.resize(n+1);
        invFactional.resize(n+1);
        inv.resize(n+1);
    }
    void build(){
        Factional[0] = 1;
        invFactional[0] = 1;
        inv[0] = 1;
        for(int x = 1; x <= n; x++){
            Factional[x] = (x * Factional[x-1]) % mod_number;
            inv[x] = inverse_mod_euclid(x);
            invFactional[x] = (inv[x] * invFactional[x-1]) % mod_number;
        }
    }

    // nCkを求める関数 : n < k の入力に注意せよ
    LLi combination(int N, int K){
        if(N < K) return 0;
        return ((Factional[N] * invFactional[K] % mod_number) * invFactional[N-K]) % mod_number;
    }
};

