ll D(int i,ll x){
	if(x==1){
		return (ll)i;
	}else if(x%2==0){
		ll a = D(i,x/2);
		return a*a%MOD;
	}else{
		ll b = D(i,x/2);
		return b*b%MOD*i%MOD;
	}
}

void C(ll ans[],int n){
	ll now=n+1;
	ans[1]=now;
	for(int i=2;i<=n+1;i++){
		now = now*(n+2-i)%MOD*D(i,MOD-2)%MOD;
		ans[i]=now;
	}
}

