bool pr(int x) {

	if(x < 2) return false;

	for(int i = 2; i <= x && i != x; ++i) {
		if(!(x%i)) {
			return false;
		}
	}
	return true;
}

int c_ex(int n, int c) {
	int result = 0, t = c, k = 0;

	do {
		k = n / t;
		t *= c;
		result += k;
	}while(k);

	return result;
}

long long com(int n, int k) {
	if(k == n) return 1;
	if(k > n) return 0;

	long long res = 1;
	int cn, ck, cnk, l;

	for(int i = 2; i <= n; ++i) {
		if(pr(i)) {
			cn = c_ex(n, i);
			ck = c_ex(k, i);
			cnk = c_ex(n - k, i);
			l = cn - ck - cnk;
			for(int j = 0; j < l; ++j) {
				res *= i;
			}
		}
	}

	return res;
}

