#define LL long long int
struct mint {
  LL x; 
  mint(LL x=0):x((x%mod+mod)%mod){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(LL t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

struct combination {
  vector<mint> fact, ifact;//factに階乗を計算、ifactはその各々に対する逆元
  combination(LL n):fact(n+1),ifact(n+1) {
    assert(n < mod);
    fact[0] = 1;
    for (LL i = 1; i <= n; ++i) fact[i] = fact[i-1]*i;
    ifact[n] = fact[n].inv();
    for (LL i = n; i >= 1; --i) ifact[i-1] = ifact[i]*i;
  }
  mint operator()(LL n,LL k) {
    if (k < 0 || k > n) return 0;
    return fact[n]*ifact[k]*ifact[n-k];
  }
};

LL N;
LL A[100001];

mint ans[100002];

void solve(){
	//ダブりを検出
	vector<LL> num(N+1,0);//数値iの出現回数をnum[i]とする
	LL dup;//重複しているのはどの数かを記録
	for(int i=0;i<=N;i++){
		if(num[A[i]]==1){
			dup = A[i];
			break;
		}
		num[A[i]]++;
	}
	int first_index = -1;//ダブった当の数が最初に出現する箇所
	int second_index = -1;//ダブった当の数が2番目に出現する箇所
	for(int i=0;i<=N;i++){
		if(dup==A[i]){
			if(first_index==-1) first_index = i;
			else second_index = i;
		}
	}

	//長さiの部分文字列の個数を見ていく
	combination c(N+1);
	for(int i=1;i<=N+1;i++){
		LL rang = first_index + (N-second_index);
		ans[i] = c(N+1,i) - c(rang,i-1LL);
	}
}

int main(){
    cin >> N;
    for(int i=0;i<=N;i++) cin >> A[i];

    solve();

    for(int i=1;i<=N+1;i++) cout << ans[i].x << endl;
    return 0;
}

