int64 pw (int64 x, int64 y)
{
	int64 r = 1;
	while (y) {
		if (y & 1) r *= x, r %= md;
		y >>= 1;
		x *= x;
		x %= md;
	}
	return (r + md) % md;
}

int64 inv (int64 x)
{
	return (pw (x, md - 2)) % md;
}

int64 ncr (int64 n, int64 c)
{
	int64 r = (F[n] * inv (F[c])) % md;
	r = r * inv(F[n - c]) % md;
	return r;
} 
