		if (already_exist[a[i] - 1])
		{
			head = location[a[i] - 1];
			foot = n - i;
		}
		location[a[i] - 1] = i;
		already_exist[a[i] - 1] = true;
	}
	combination_mod cm(1000000007, 100001);
