	fact[0] = fact[1] = 1;
	rep(i, 1, COMB_SIZE) fact[i] = fact[i - 1] * i % MOD;
}
ll Combination(ll n, ll r) {
	return ((fact[n] * (POW(fact[r], MOD - 2) % MOD)) % MOD * POW(fact[n - r], MOD - 2)) % MOD;
}
