const int N = 1e5 + 5, mod = 1e9+7;
int n, a[N], pos[N];
using ll = long long;


ll quick_pow(ll a, ll b) {
    ll res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

int fac[N], finv[N];
void init_fac_mod(){
    //only when mod is prime
    fac[0] = finv[0] = 1;
    for(int i = 1; i <= N; ++i)
        fac[i]=(ll)fac[i-1]*i%mod;
    finv[N] = quick_pow(fac[N], mod-2);
    for(int i = N-1; i; --i)
        finv[i] = (ll)finv[i+1]*(i+1)%mod;
}

int c(int n, int m){
    //n!/(m!(n-m)!)
    return (ll)((ll)fac[n] * finv[m] % mod) * finv[n - m] % mod;
}


