ll select(int a, int b){
   if(a == 0 || b > a){
      return 0;
   }else{
      ll s = 1;
      for(int i = 1; i <= b; i++){
         s *= a;
         s /= i;
         a--;
      }
      s %= 1000000007;
      return s;
   }
}

