  if(n == 1) {
    cout << 1 << endk << 1 << endk;
    return 0;
  }
  for(int i=1; i<=n+1; i++) {
    ll ans = 0;
    if(i <= n-1) (ans += comb(n-1, i)) %= mod;
    if(i >= 2) (ans += comb(n-1, i-2)) %= mod;
    if(i <= n) (ans += comb(n-1, i-1) * 2 - comb(p1+n-p2, i-1) + mod) %= mod;
    cout << ans << endk;
  }
  return 0;
}

