    vi fact;
public:
    Combination(int size){
        size++;
        fact.resize(size);
        fact[0]=1;
        FOR(i,1,size){
            fact[i]=(fact[i-1]*i)%MOD;
        }
    }
    int Fact(int n){
        return fact[n];
    }
    int MPow(int x,int y){
        if(y==0)return 1;
        if(y%2){
