// a^b (mod p)
int pow_modulo(int a, int b, int p)
{
    if(b == 0) return 1;

    if(b % 2 == 0) {
        long d = pow_modulo(a, b/2, p);
        return (d*d) % p;
    }
    else {
        long tmp = a;
        tmp *= pow_modulo(a, b-1, p);
        return tmp % p;
    }
}

// lhs/rhs (mod p), p は素数
int div_modulo(int lhs, int rhs, int p)
{
    long rhs_inv = pow_modulo(rhs, p-2, p);
    return (lhs * rhs_inv) % p;
}

int comb_modulo(int n, int k, int p)
{
    long result = 1;

    for(int i = n; i >= n-k+1; --i) {
        result *= i;
        result %= p;
    }

    for(int i = k; i >= 2; --i) {
        result = div_modulo(result, i, p);
    }

    return result;
}

void find_lr(const vector<int>& a, int& l, int& r)
{
    int n = a.size() - 1;
    vector<int> bin(n+1);

    int dup_num = -1;
    for(int e : a) {
        if(++bin[e] == 2) {
            dup_num = e;
            break;
        }
    }

    for(int i = 0; i < n+1; ++i) {
        if(a[i] == dup_num) {
            l = i;
            break;
        }
    }

    for(int i = n; i >= 0; --i) {
        if(a[i] == dup_num) {
            r = i;
            break;
        }
    }
}

