typedef long long ll;

ll Pow(ll n, ll k) {
	ll ans = 1, a = n % MOD;
	while (k > 0) {
		if (k & 1) {
			ans *= a;
			ans %= MOD;
		}
		a *= a;
		a %= MOD;
		k >>= 1;
	}
	return ans;
}

ll Inverse(ll a) {
	return Pow(a, MOD - 2);
}

void Facto_Ini(vector<ll> &k) {
	ll a = 1, i;
	for (i = 1; i < k.size(); i++) {
		a *= i;
		a %= MOD;
		k[i] = a;
	}
	return;
}

ll Combi(int n, int a, vector<ll> &k) {
	a = min(n - a, a);
	if (a < 0)
		return 0ll;
	if (a == 0)
		return 1ll;
	ll ans = k[n] * Inverse(k[a]);
	ans %= MOD;
	ans *= Inverse(k[n - a]);
	ans %= MOD;
	return ans;
}

