template <class T> std::vector<T> combination_table(int n) {
  std::vector<T> vec(n + 1);
  vec[0] = T(1);
  for (int r = 1; r < n + 1; r++) {
    vec[r] = vec[r - 1] * T(n - r + 1) / T(r);
