  else if(y == 1)
    return x % waru;
  else if(y % 2 == 0)
    return (beki(x, y/2) % waru) * (beki(x, y/2) % waru) % waru;
  else
    return (x % waru) * (beki(x, y-1) % waru) % waru;
}

