typedef long long ll;
const ll mod = 1e9 + 7;

ll modpow(ll a, ll b, ll p = 1e9+7){
    if(b == 0)  return 1;
    if(b % 2 == 0){
        ll d = modpow(a, b/2, p);
        return (d*d) % p;
    }else{
        return (a%p * modpow(a, b-1, p)) % p;
    }
}

struct ModComb{
    vector<ll> po, inv;
    ll N;

    ModComb(ll n) : N(n), po(n), inv(n) {
        po[0] = 1;
        for(int i = 1; i < N; i++)  po[i] = (po[i-1] * i) % mod;
        inv[N-1] = modpow(po[N-1], mod-2, mod);
        for(int i = N-2; i >= 0; i--)   inv[i] = (inv[i+1] * (i+1)) % mod;
    }

    ll nCk(ll n, ll k){
        if(n < k)   return 0;
        return (((po[n]*inv[n-k])%mod)*inv[k])%mod;
    }

    ll nPk(ll n, ll k){
        if(n < k)   return 0;
        return (po[n]*inv[n-k])%mod;
    }

    ll nHk(ll n, ll k){
        if(n == 0 && k == 0)    return 1;
        return nCk(n+k-1, k);
    }
};

int main(){
    ModComb mc(100005);
    int n;
    cin >> n;
    vector<int> a(n+1), cnt(n+1, 0);
    int p;
    for(int i = 0; i <= n; i++){
        cin >> a[i];
        cnt[a[i]]++;
        if(cnt[a[i]] == 2)  p = a[i];
    }
    int l = n+1, r = -1;
    for(int i = 0; i <= n; i++){
        if(a[i] == p)   l = min(l, i), r = max(r, i);
    }
    for(int k = 1; k <= n+1; k++){
        ll ans = 0;
        if(n+1-2 >= k)  ans += mc.nCk(n-1, k);
        ans %= mod;
        ans += 2*mc.nCk(n-1, k-1);
        if(n+1-(r-l+1) >= k-1)  ans -= mc.nCk(n+1-(r-l+1), k-1);
        ans %= mod;
        if(k >= 2)  ans += mc.nCk(n+1-2, k-2);
        ans %= mod;
        cout << ans << endl;
    }
    return 0;
}

