long mpow(long a, long n) {
    if (n == 0) return 1;
    if (n % 2 == 0) {
        long d = mpow(a, n / 2);
        return d * d % MOD;
    }
    return a * mpow(a, n - 1) % MOD;
}

void make() {
    fact[0] = 1;
    REPI(i,1,100001) {
        fact[i] = fact[i-1] * i % MOD;
    }
    REP(i,100001) {
        factinv[i] = mpow(fact[i], MOD - 2);
    }
}

void check() {
    REP(i,100001) {
        if (fact[i] * factinv[i] % MOD != 1) {
            cout << "ERROR" << endl;
            exit(1);
        }
    }
}

long comb(long n, long k) {
    if (n < 0) {
        n *= -1;
        if (k < 0 || k > n) return 0;
        return mpow(-1, k) * fact[n + k - 1] * factinv[n - 1] % MOD * factinv[k] % MOD;
    }
    if (k < 0 || k > n) return 0;
    return fact[n] * factinv[k] % MOD * factinv[n - k] % MOD;
}

int main() {
    make();
    int n;
