        v.push_back(a);
        sum += a;
    }
    long dbl = sum - n * (n + 1) / 2;
    int l = -1, r, i = 0;
    while (i < n + 1) {
        if (v[i] == dbl && l == -1) l = i;
        else if (v[i] == dbl) {
            r = i;
            break;
        }
        i++;
    }
    REP(i,n+1) {
        cout << (comb(n+1,i+1) - comb(l+n-r,i) + MOD) % MOD << endl;
    }
}

