using namespace std;



#define SIZE 1000005


ll fact[SIZE],inv_fact[SIZE];
ll A[100005],table[100005];


ll mod_pow(ll x,ll count, ll mod){

	if(count == 0)return 1;
	ll ret = mod_pow((x*x)%mod,count/2,mod);
	if(count%2 == 1){

		ret = (ret*x)%mod;
	}
	return ret;
}

ll extgcd(ll a,ll b,ll &x,ll &y){
	ll d = a;
	if(b != 0){
		d = extgcd(b,a%b,y,x);
		y -= (a/b)*x;
	}else{
		x = 1;
		y = 0;
	}
	return d;
}

ll mod_inverse(ll a,ll m){
    ll x,y;
    extgcd(a,m,x,y);
    return (m+x%m)%m;
}

ll nCk(ll n,ll k){

	if(k > n)return 0;

	ll ret = fact[n]*inv_fact[k];
	ret %= MOD;
	ret *= inv_fact[n-k];

	return ret%MOD;
}



int main(){

	fact[0] = 1;
	for(ll i = 1; i < SIZE; i++){
		fact[i] = i*fact[i-1];
		fact[i] %= MOD;
	}
	inv_fact[SIZE-1] = mod_inverse(fact[SIZE-1],MOD);
	for(ll i = SIZE-1; i >= 1; i--){

		inv_fact[i-1] = inv_fact[i]*i;
		inv_fact[i-1] %= MOD;
	}

	ll N;
	scanf("%lld",&N);

	for(ll i = 1; i <= N; i++){

		table[i] = 0;
	}

	int base = -1;

	for(ll i = 0; i < N; i++){

		scanf("%d",&A[i]);
		table[A[i]]++;
		if(table[A[i]] == 2){

			base = A[i];
		}
	}

	ll L = -1, R = -1;

	for(ll i = 0; i < N; i++){
		if(A[i] != base)continue;

		if(L == -1){

			L = i;
		}else{

			R = i;
		}
	}

	ll pre = L;
	ll mid = R-(L+1); //LとRの間にある数
	ll tail = N-(R+1)+1;

	//printf("pre:%lld mid:%lld tail:%lld\n",pre,mid,tail);


	//printf("%lld\n",N); //1
	for(ll num = 2; num <= N; num++){

		//printf("\n\nnum:%lld\n",num);

		//baseを含まない
		ll tmp = nCk(N-1,num);
		//printf("tmp:%lld\n",tmp);

		//baseを1つ含む
		//区間midにデータなし(L,Rが区別されない)
		ll no_mid = nCk(pre+tail,num-1);
		//printf("no_mid:%lld\n",no_mid);

		//区間midにデータあり(L,Rが区別される)
		//printf("nCk(N-1,num-1):%lld -nCk(pre+tail,num-1):%lld\n",nCk(N-1,num-1),nCk(pre+tail,num-1));

	 	ll yes_mid = 2*(nCk(N-1,num-1)-nCk(pre+tail,num-1));
		//printf("yes_mid:%lld\n",yes_mid);

		tmp += (no_mid+yes_mid)%MOD;
		tmp %= MOD;

		//baseを2つ含む
		ll num_two = nCk(N-1,num-2);
		//printf("num_two:%lld\n",num_two);

		tmp += num_two;
		tmp %= MOD;

		printf("%lld\n",tmp);
	}
	printf("1\n");

	return 0;
}

