#include <bits/stdc++.h>
using namespace std;

constexpr int64_t MOD = 1000000007;

int64_t Power(int64_t base, int64_t exp) {
  int64_t x = 1;
  while (exp) {
    if (exp % 2) {
      x = x * base % MOD;
    }
    base = base * base % MOD;
    exp /= 2;
  }
  return x;
}

int64_t inv(int64_t i){
  return Power(i,MOD-2);
}
int64_t fact[100002],factinv[100002];
int64_t C(int64_t n,int64_t r){
  return fact[n]*factinv[r]%MOD*factinv[n-r]%MOD;
}

int main(){
  int64_t n,a;
