ll pw(ll x, ll y, ll mod) {
    if (y == 0) return 1;
    else if (y == 1) return x % mod;
    else if (y % 2 == 0) {
        ll p = pw(x, y / 2, mod);
        return p * p % mod;
    }
    else {
        ll p = pw(x, y / 2, mod);
        return p * p % mod * x % mod;
    }
}

ll dv(ll x, ll y, ll mod) {
    x %= mod;
    y %= mod;
    return x * pw(y, mod - 2, mod) % mod;
}

ll comb(ll n, ll r, ll mod) {
    ll v = 1;
    if (n < r || n < 0 || r < 0) return 0;
    for (int i = 1; i <= r; i++) {
        v = v * dv(n - i + 1, i, mod) % mod;
    }
    return v;
}

ll val(ll a, ll b, ll c, ll k, ll mod) {
    ll v = 0;
    v += comb(a+b+c, k, mod);
    v += 2*comb(a+b+c, k-1, mod) - comb(a+c, k-1, mod);
    v += comb(a+b+c, k-2, mod);
    return (v + mod * mod) % mod;
}

