const int maxn = 1e5 + 10;

ll fact[maxn], fact_inv[maxn];

ll power(ll a, ll b) {
	ll result = 1;
	while(b) {
		if(b % 2) result = (result * a) % P;
		a = (a * a) % P;
		b /= 2;
	}

	return result;
}

ll divide(ll a, ll b) {
	return a * power(b, P - 2) % P;
}

ll C(ll n, ll k) {
	if(n < k) return 0;
	return ((fact[n] * fact_inv[k]) % P * fact_inv[n - k] % P);
}

void init() {
	fact[0] = 1;
	for(int i = 1; i < maxn; i++) fact[i] = (fact[i - 1] * i) % P;

	fact_inv[maxn - 1] = divide(1, fact[maxn - 1]);
	for(int i = maxn - 2; i >= 0; i--) fact_inv[i] = (fact_inv[i + 1] * (i + 1)) % P;
}

void solve() {
	int n;
	cin >> n;

	vi a(n + 1);
	for(int i = 0; i < n + 1; i++) cin >> a[i];

	int cnt;
	vi seen(n + 1, -1);
	for(int i = 0; i < n + 1; i++) {
		if(seen[a[i]] != -1) {
			cnt = seen[a[i]] + n - i;
			break;
		} else seen[a[i]] = i;
	} 

	cout << n << endl;
	for(int k = 2; k <= n + 1; k++) {
		ll ans = 0;
		ans += C(n - 1, k);
		ans %= P;
		ans += C(n - 1, k - 2);
		ans %= P;
		ans += (2 * C(n - 1, k - 1)) % P;
		ans %= P;
		ans = (ans - C(cnt, k - 1) + P) % P;

		cout << ans << endl;
	}
}

