  cin >> n;

  for(ll i=0; i<=n+1; i++){
    kaijo_tbl[i] = kaijo(i);
    kaijo_watta[i] = beki(kaijo(i), waru-2) % waru;
  }

  map<ll,vector<ll>> mp;
