void solve(){
  cin >> n;
  for(int i = 0; i < n+1; i++) a[i] = -1;
  int tmp;
  for(int i = 0; i < n+1; i++){
    cin >> tmp;
    if(a[tmp] == -1) a[tmp] = i;
    else {
      p = a[tmp];
      q = n-i;
    }
  }
  nC[0] = pC[0] = qC[0] = 1;
  nC[1] = n+1; pC[1] = p; qC[1] = q;
  for(int i = 2; i <= n; i++)
    nC[i] = nC[i-1]*(n+2-i)/i;
  for(int i = 2; i <= n-1; i++){
    if(p>=i) pC[i] = pC[i-1]*(p+1-i)/i;
    if(q>=i) qC[i] = qC[i-1]*(q+1-i)/i;
  }
  for(int i = 0; i <= n; i++) nC[i]%=PRIME;
  for(int i = 0; i <= n-1; i++){
