const ll mod = 1000000007LL;

ll mfactorials[200000+1];

ll powmod(ll x, ll n) {
    if (n == 0LL) return 1LL;
    x %= mod;
    if (n % 2LL == 0) {
        return powmod((x * x) % mod, n / 2LL);
    }
    else {
        return (x * powmod((x * x) % mod, n / 2LL)) % mod;
    }
}

ll comb(ll n, ll k) {
    if (n == 0 || k > n) return 0;
    return (mfactorials[n] * powmod((mfactorials[k] * mfactorials[n - k]) % mod, mod - 2LL)) % mod;
}

ll submod(ll a, ll b) {
    return a > b ? (a - b) % mod : (a - b + mod);
}

int main() {
    mfactorials[0] = mfactorials[1] = 1LL;
