public:
  modint_t operator+(const modint_t& a) const {
    return (x + a.x) % MOD;
  };

  modint_t operator-(const modint_t& a) const {
    return (x - a.x) % MOD;
  };

  modint_t operator*(const modint_t& a) const {
    return x * a.x % MOD;
  };

  modint_t operator/(const modint_t& a) const {
    return (*this) * a.inversed();
  };

  // Note that operator^'s priority is quite low in C++...
  modint_t operator^(long long i) const {
    return modpow(x, i);
  };

public:
  modint_t& operator+=(const modint_t& a) {
    (x += a.x) %= MOD;

    return *this;
  };

  modint_t& operator-=(const modint_t& a) {
    (x -= a.x) %= MOD;

    return *this;
  };

  modint_t& operator*=(const modint_t& a) {
    (x *= a.x) %= MOD;

    return *this;
  };

  modint_t& operator/=(const modint_t& a) {	// Not tested
    (x *= a.inversed().x) %= MOD;

    return *this;
  };

public:
  modint_t inversed() const {
    assert(x % MOD);

    return modpow(x, MOD - 2);
  };

  void inverse() {
    assert(x % MOD);

    x = modpow(x, MOD - 2).x;
  };

private:
  void normalize() {
    while (! (0 <= x && x < MOD))
      x = (x + MOD) % MOD;
  };

private:
  long long x;
};

modint_t operator+(long long a, const modint_t& b)
{
  return modint_t(a) + b;
}

modint_t operator-(long long a, const modint_t& b)
{
  return modint_t(a) - b;
}

modint_t operator*(long long a, const modint_t& b)
{
  return modint_t(a) * b;
}

modint_t operator/(long long a, const modint_t& b)
{
  return modint_t(a) / b;
}

std::ostream& operator<<(std::ostream& ofs, modint_t a)
{
  a.normalize();

  ofs << a.x;

  return ofs;
}

modint_t modpow(modint_t x, long long y)
{
  modint_t xx = x, p = 1;

  for ( ; y; xx *= xx, y >>= 1)
    if (y & 1)
      p *= xx;

  return p;
}

modint_t modncr(int n, int r)
{
  assert(n >= 0);
  assert(r >= 0);

  if (n == 0)
    return r == 0 ? 1 : 0;

  if (r > n)
    return 0;

  modint_t num = 1, denom = 1;

  int dm = std::min(r, n - r);
  int dp = std::max(r, n - r);

  for (int i = dp + 1; i <= n; i ++)
    num *= i;

  for (int i = 2; i <= dm; i ++)
    denom *= i;

  return modpow(denom, MOD - 2) * num;
}

template<size_t T>
class modinv_t {
public:
  modinv_t() {
    modint_t x = a_[0] = 1;

    for (int i = 1; i < T; i ++)
      a_[i] = (x *= i).get();

    modint_t inv = modpow(a_[T - 1], MOD - 2);

    for (int i = T - 1; i > 0; inv *= i, i --)
      a_[i] = (a_[i - 1] * inv).get();

#if 0
    for (int i = 1; i < T; i ++)
      assert(i * a_[i] % MOD == 1);
#endif
  };

public:
  modint_t operator[](size_t i) const {
    assert(i < T);

    return a_[i];
  };

private:
  long long a_[T];
};

