using namespace std;

vector<vector<long>> memo;

long comb(int a, int b) {
    if (b > a) {
        return 0;
    } else if (memo[a][b] != -1) {
        return memo[a][b];
    } else if (memo[a][a - b] != -1) {
        return memo[a][a - b];
    }

    if (b == 0) {
        return 1;
    }

    memo[a][b] = comb(a - 1, b - 1) * a / b;
    return memo[a][b];
}

int main() {
    int n;
    cin >> n;
    memo = vector<vector<long>>(n + 2, vector<long>(n + 2, -1));
    int left, right;
    vector<long> vec(n + 1);
    for (int i = 0; i < n + 1; i++) {
        scanf("%ld", &vec[i]);
        for (int k = 0; k < i; k++) {
            if (vec[k] == vec[i]) {
                left = k;
                right = n - i;
            }
        }
    }

    long div = 1;
    for (int i = 0; i < 9; i++) div *= 10;
    div += 7;

    for (int i = 1; i <= n + 1; i++) {
        long res = comb(n + 1, i);
        long dif = 0;
        for (int k = 0; k < i; k++) {
            dif += comb(right, k) * comb(left, i - 1 - k);
        }
        cout << (res - dif) % div << endl;
    }
}

