ll F[100010];

ll square(ll x){
    return x*x % MOD;
}

ll mul(ll a, ll b){
    return ((a % MOD) * (b % MOD)) % MOD;
}

ll power(ll x, ll y){
    if( y == 0) return 1;
    else if( y == 1 ) return x % MOD;
    else if( y % 2 == 0) return square(power(x, y/2)) % MOD;
    else return mul(square(power(x, y/2)), x) % MOD;
}

ll Div(ll x, ll y){
    return mul(x, power(y, MOD-2));
}

