ll quick_pow(ll a, ll b) {
    ll res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

int fac[N], finv[N];
void init_fac_mod(){
    //only when mod is prime
    fac[0] = finv[0] = 1;
