ll modulo (ll a, ll b){
  ll x = 1 , y = a;
  while(b>0){
    if(b%2 == 1)x=(x*y)%MOD;
    y = (y*y)%MOD;
    b /= 2;
  }
  if(x<0) return (MOD+x) % MOD;
  return x % MOD ;
}


// in range 0 <= x <= N
// 1. x!
// 2. (x!)^{-1}
//   2-1. (N!)^{-1}
