template<class T>struct nCk{
	vector<T> kai,gya,nck;
	nCk(int n){
		kai.resize(n+1);
		gya.resize(n+1);
		nck.resize(n+1);
	}
	T pow(T x,T n,T mod=1e9+7LL){
		T ret=1;
		if(n>0){
			ret=pow(x,n/2,mod);
			if(n%2==0){
				(ret=(ret*ret))%=mod;
			}else{
				(ret=((ret*ret)%mod)*x)%=mod;
			}
		}
		return ret;
	}
	T inv(T n,T mod=1e9+7LL){
		return pow(n,mod-2,mod);
	}
	vector<T> cul(T n,T mod=1e9+7LL){
		kai[n]=n;
		for(int i=n-1;i>0;i--){
			(kai[i]=kai[i+1]*i)%=mod;
		}
		gya[1]=inv(1,mod);
		for(int i=2;i<=n;i++){
			(gya[i]=gya[i-1]*inv(i,mod))%=mod;
		}
		for(int i=1;i<=n;i++){
			(nck[i]=kai[n+1-i]*gya[i])%=mod;
		}
		nck[0]=1;
		nck[n]=1;
		return nck;
	}
};
