}

ll factrial(ll x){
    if(x == 0) return 1;
    //if(fact[x] != 0) return fact[x];
    else return fact[x] = x * factrial(x - 1) % mod;
}

ll rfactrial(ll x){
    //if(rfact[x] != 0) return rfact[x];
    return rfact[x] = quick_power(factrial(x), mod - 2);
}

ll combi(ll n, ll k){
    // n >= 0，k >= 0，n - k >= 0を保証する必要がある．
    // 逆に，上記を満たさない場合の処理をifで定める．
    if(n < k) return 0;
    if(k == 0) return 1;
    return (factrial(n) * rfactrial(n - k) % mod) * rfactrial(k) % mod;
}


