i64 mod_pow(i64 x, i64 n = MOD - 2, i64 mod = MOD) {
	i64 ret = 1;

	while(n) {
		if(n & 1) (ret *= x) %= mod;
		(x *= x) %= mod;
		n >>= 1;
	}

	return ret;
}

