ll dfs(int x, int y)
{
    if(y == 0) return 1;
    if(y == 1) return x;
    if(y % 2 == 0){
        ll temp = dfs(x,y/2);
        return (temp * temp) % MOD;
    }else{
        ll temp = dfs(x,y/2);
        return (((temp * temp) % MOD)*x) % MOD;
    }
}

