    if( k == 1 ) return 0;
    if( k == 2 ) return 1;
    ll i = 2;
    ll a = 0 , b = 1;
    while( i < k ){
      ll t = ( i * ( ( a + b ) % m ) ) % m;
      a = b; b = t; i++;
    }
    return b;
  }
};

