class Combination {
private:
	long long mod;
	vector<long long> table;
	vector<long long> invTable;

	long long mpow(long long a, long long n) {
		long long x = 1LL;
		for (; n > 0; n >>= 1, a = (a * a) % mod)
			x = (n & 1) ? (x * a) % mod : x;
		return x;
	}

	void compute(int n) {
		table = vector<long long>(n + 1, 1);
		invTable = vector<long long>(n + 1, 1);
		for (int i = 1; i < n + 1; i++) {
			table[i] = table[i - 1] * i % mod;
			invTable[i] = mpow(table[i], mod - 2);
		}
	}

public:
	Combination(int n, long long mod = (long long)1e9 + 7) : mod(mod) { compute(n); }
	long long get(int n, int r) { return n < r ? 0 : (((invTable[n - r] * invTable[r]) % mod) * table[n]) % mod; }
};


