    for(int i = 0; i < n + 1; i++){
        cin >> a[i];
        if(b[a[i]] != -1){
            l = b[a[i]];
            r = i;
        }
        else b[a[i]] = i;
    }
    Combination com(n + 1);
    for(int i = 1; i <= n + 1; i++){
        cout <<
            (com.com(n, i) + com.com(n - 1, i - 1) - com.com(n - (r - l), i - 1) + com.com(n - 1, i - 2) + MOD) % MOD <<
            endl;
    }
}

