int cmb(ll n, ll k) {
	if (n == 0 || k == 0) {
		return 0;
	}
	else if (n < k) {
		return 0;
	}
	else {
		ll ue=1;
		ll sita=1;
		int i;
		if (n - k <= k) {
			for (i = 1;i <= n - k;i++) {
				ue *= (n + 1 - i);
				sita *= i;
			}
		}
		else {
			for (i = 1;i <=k;i++) {
				ue *= (n + 1 - i);
				sita *= i;
			}
		}
		return (ue / sita) % 1000000007;
	}
}

