// a^n mod を計算する
ll modpow(ll a, ll n, ll mod) {
    ll ans = 1;
    while (n > 0) {
        if (n & 1) ans = ans * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return ans;
}

// a^{-1} mod を計算する
ll modinv(ll a, ll mod) {
   return modpow(a, mod - 2, mod);
}

//n個からk個を選ぶ場合の数
ll select(int n, int k, ll *p){
   if(n == 0 || k > n){
      return 0;
   }else{
      p[k] = p[k-1] * (n - k + 1) % MAX;
      factrial_division[k] = factrial_division[k - 1] * modinv(k, MAX) % MAX;
      return p[k] * factrial_division[k] % MAX;
   }
}

