class Combination {
  public:
    Combination(ll max) {
        max += 100; // for safety
        m_fac.resize(max + 1);
        m_finv.resize(max + 1);
        m_inv.resize(max + 1);
        m_fac[0] = m_fac[1] = 1;
        m_finv[0] = m_finv[1] = 1;
        m_inv[1] = 1;
        for (int i = 2; i <= max; ++i) {
            m_fac[i] = m_fac[i - 1] * i % MOD;
            m_inv[i] = MOD - m_inv[MOD % i] * (MOD / i) % MOD;
            m_finv[i] = m_finv[i - 1] * m_inv[i] % MOD;
        }
    }
    ll operator()(ll n, ll k) {
        if (n < k)
            return 0;
        if (n < 0 || k < 0)
            return 0;
        return m_fac[n] * (m_finv[k] * m_finv[n - k] % MOD) % MOD;
    }

  private:
    vl m_fac;
    vl m_finv;
    vl m_inv;
};

