using int64 = long long;
constexpr int64 kMod = 1000000007;

int64 PowMod(int64 a, int64 e) {
  int64 r = 1;
  for (; e; e >>= 1) {
    if (e & 1)
      r = r * a % kMod;
    a = a * a % kMod;
  }
  return r;
}

int64 Comb(int64 n, int64 r) {
  if (n / 2 < r)
    return Comb(n, n - r);

  int64 ret = 1;
  for (int64 i = 0; i < r; ++i) {
    ret = ret * (n - i) % kMod;
    ret = ret * PowMod(i + 1, kMod - 2) % kMod;
  }
  return ret;
}

int64 Patterns(const int64 n, const int64 l, const int64 r, const int64 k) {
  if (k == 1)
    return n - 1;

  int64 all = Comb(n, k);
  for (int64 i = max(0LL, k - n + r); i <= min(k, l); ++i) {
    all -= Comb(l, i) * Comb(n - r - 1, k - i - 1) % kMod;
    if (all < 0)
      all += kMod;
  }
  return all;
}

