typedef long long ll;

vector<ll> nx(100010, 0);
vector<ll> abx(100010, 0);

ll kurikaeshi(ll a,ll b) {
	ll ans = 1;
	while (b) {
		if (b % 2) {
			ans *= a;
		}
		a *= a;
		b /= 2;
		a %= 1000000007;
		ans %= 1000000007;
	}
	return ans;
}

ll warizan(ll a,ll b) {
	// a÷bを行います
	ll ans = a;
	ans *= kurikaeshi(b, 1000000005);
	ans %= 1000000007;
	return ans;
}

void abSetting(int ab) {
	ll ans = 1;
	for (int i = 0;i <= ab;i++) {
		abx[i] = ans;
		ans *= warizan(ab - i, i + 1);
		ans %= 1000000007;
	}
	abx[ab] = 1;
	return;
}

void nxSetting(int n) {
	ll ans = 1;
	for (int i = 0;i <= n + 1;i++) {
		nx[i] = ans;
		ans *= warizan(n + 1 - i, i + 1);
		ans %= 1000000007;
	}
	return;
}

