ll euclidean(ll a, ll b) {
	vll r = { a,b };
	vll s = { 1,0 };
	while (true) {
		int i = sz(r) - 1;
		r.push_back(r[i - 1] % r[i]);
		ll q = r[i - 1] / r[i];
		s.push_back(s[i - 1] - s[i] * q);
		if (!r.back())break;
	}
	int i=sz(r)-2;
	if (s[i]<0)s[i] += b;
	if (s[i] >= b)s[i] -= b;
	return s[i];
}
