LL per(int n, int r) {
  LL ret = 1;
  REP(i, r) {
    ret *= (n - i);
  }
  return ret;
}

LL fac(int n) {
  return per(n, n);
}

LL con(int n, int r) {
  LL ret = per(n, r);
  ret /= fac(r);
  return ret;
}

LL rem(LL n) {
  return n % 1000000007;
}

int main(){
