ll fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

ll COM(int n, int k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll powMod(ll x, ll k) {
  if (k == 0) return 1;
  if (k % 2 == 0)
    return powMod(x * x % MOD, k / 2);
  else
    return x * powMod(x, k - 1) % MOD;
}

int main() {
  COMinit();
  int n;
  cin >> n;
  vector<int> a(n + 1), b(n);
  rep(i, n + 1) cin >> a[i];
  int left, right;
  rep(i, n + 1) {
    if (b[a[i] - 1] == 0) {
      b[a[i] - 1] = 1;
    } else {
      right = i;
      rep(j, i) {
        if (a[i] == a[j]) left = j;
      }
    }
  }

  vector<ll> ans(n + 1);
  for (int i = 1; i <= n + 1; i++) {
    ans[i - 1] = COM(n + 1, i);
    ans[i - 1] %= MOD;
  }

  for (int i = 0; i <= n - right; i++) {
    ans[i] += MOD - COM(n - right, i);
    ans[i] %= MOD;
  }

  for (int i = 1; i <= left; i++) {
    ans[i] += MOD - COM(left, i);
    ans[i] %= MOD;
  }

  rep(i, n + 1) cout << ans[i] << endl;
}

