// return a^b in O(log b)
ll mypow(ll a, ll b){
    if (b == 0)
        return 1;
    ll tmp = mypow(a, b / 2);
    if (b % 2)
        return (((tmp * tmp) % MOD) * a) % MOD;
    else
        return (tmp * tmp) % MOD;
}

long long comb2(int n, int k){
	static bool init = false;
	static vector<ll> frc(200001, 1), inv(200001, 1);
	if(!init){
		init = true;
		REP(i, 200000){
			frc[i + 1] = (frc[i] * (i + 1)) % MOD;
			inv[i + 1] = mypow(frc[i + 1], static_cast<long long>(MOD - 2));
		}
	}
	if (k < 0 || n < k) return 0;
	long long res = (((frc[n] * inv[k]) % MOD) * inv[n - k]) % MOD;
    return res;
}

