    // a = [...x.....x...]
    int num1 = id1;
    // xの右側にある数字の個数
    int num2 = n - id2;

    // 重複している数字：x
    for(int i = 1; i <= n+1; ++i){        // 数字をi個取る
        ll res = combination(n + 1, i) - combination(num1 + num2, i - 1) + 2 * (ll)mod % mod;

