            cout << 1 << endl;
        } else {
            ll ans = fm.CombiMod(N + 1, i) -
                     fm.CombiMod(p[0] + 1 + N - 1 - p[1], i - 1);
            ans = (ans + MOD) % MOD;
            cout << ans << endl;
        }
    }

    return 0;
}

