    for(; k > 0; k>>=1) {
        if(k&1) ret = ret * x % mod;
        x = x * x % mod;
    }
    return ret;
}

void init_comb() {
    fact[0] = 1, fact[1] = 1;
    for(int i = 1; i < mxn-1; i++) {
        fact[i+1] = fact[i] * (i+1) % mod;
