long long fac[MAX], finv[MAX], inv[MAX];

void COMBinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % P;
        inv[i] = P - inv[P%i] * (P / i) % P;
        finv[i] = finv[i - 1] * inv[i] % P;
    }
}

long long COMB(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % P) % P;
}

LL N;
vector<LL> A;
map<LL, int> M;
int al, ar;
LL a;

LL f(LL k){
	LL ret = 0;
	if(k == 1){
		ret = N;
		return (ret%P);
	}
	if(k == N+1){
		return 1LL;
	}
	if(k == N){
		ret = N + 1 -2;
		if(ar - al == 1){
			ret += 1;
		}
		else if(ar - al > 1){
			ret += 2;
		}
		return (ret%P);
	}

	ret = COMB(N-1, k);

	if(k > 2){
		ret += COMB(N-1, k-2);
	}
	else{
		ret++;
	}
	ret %= P;

	if(ar - al == 1){
		ret += COMB(N-1, k-1);
		ret %= P;
	}
	else{
		LL s = COMB((N+1-ar) + al - 1, k-1);
		LL t = COMB(N-1, k-1) - s;
		t %= P;
		if(t < 0){
			t += P;
		}
		ret += (s + 2*t);
	}
	return (ret%P);
}

