long comb(int a, int b) {
    if (b > a) {
        return 0;
    } else if (memo[a][b] != -1) {
        return memo[a][b];
    }

    long res = 1;
    int start = a - b;
    for (int i = 1; i <= b; i++) {
        res *= start + i;
        res /= i;
    }

    memo[a][b] = res;
    return res;
}

