	REP(i, N + 1) scanf("%d", &A[i]);

	vector<vector<int>> pos(N + 1);
	REP(i, N + 1) pos[A[i]].push_back(i);

	int l, m, r;
	REP(i, N) if (pos[i + 1].size() == 2) {
		int mn = min(pos[i + 1][0], pos[i + 1][1]);
		int mx = max(pos[i + 1][0], pos[i + 1][1]);
		l = mn;
		m = mx - mn - 1;
		r = N + 1 - mx - 1;
		break;
	}
	for (int k = 1; k <= N + 1; ++k) {
		mint ans;
		ans += comb(l + m + r, k);
		ans += comb(l + m + r, k - 1) * 2;
		ans -= comb(l + r, k - 1);

		if (k >= 2) ans += comb(l + m + r, k - 2);
		cout << ans << '\n';
	}

	return 0;
}

