ll mod(ll a, ll mod){
  ll res = a%mod;
  if(res<0)res=res + mod;
  return res;
}

ll modpow(ll a, ll n, ll mod){
  ll res=1;
  while(n>0){
    if(n&1) res=res*a%mod;
    a=a*a%mod;
    n>>=1;
  }
  return res;
}

ll modinv(ll a, ll mod){
  return modpow(a, mod-2, mod);
}

ll gcd(ll a, ll b){
  ll r = a%b;
  if(r==0) return b;
  else return gcd(b, a%b);
}

bool is_prime(ll n){
  ll i = 2;
  if(n==1)return false;
  if(n==2)return true;
  bool res = true;
  while(i*i <n){
    if(n%i==0){
      res = false;
    }
    i = i+1;
  }

  //if(i==1)res = false;
  if(n%i==0)res=false;
  return res;
}

ll fact[100100];
ll ifact[100100];

void genfact(ll n){
  fact[0]=1;
  ifact[0]=1;
  FOR(i, 1, n+1){
    fact[i] = mod(fact[i-1]*i, MOD);
    ifact[i] = modinv(fact[i], MOD);
  }
}

ll comb(ll n, ll k){
  if(k<0)return 0;
  if(n<0)return 0;
  if(k>n){
    return 0;
  }else{
    ll ans = fact[n];
    ans = mod(ans*ifact[k], MOD);
    ans = mod(ans*ifact[n-k], MOD);
    return ans;
  }
}
