constexpr long long MOD = 1000000000 + 7;

long long get_degree(long long a, long long k) { //a^k O(logN)
	long long res = 1;
	long long cur = a;
	while(k) {
		if (k % 2) res = (res * cur) % MOD;
		k /= 2;
		cur = (cur * cur) % MOD;
	}
	return res;
}
long long denom_table[100010];
long long numer_table[100010];
void set_denom_table(long long n) {
	for (long long i = 0; i < n; i++) {
		if (i == 0) denom_table[i] = 1;
		else {
			denom_table[i] = (denom_table[i-1] * get_degree(i, MOD-2)) % MOD;
		}
	}
}
void set_numer_table(long long n) {
	for (long long i = 0; i < n; i++) {
		if (i == 0) numer_table[i] = 1;
		else {
			numer_table[i] = (numer_table[i-1] * i) % MOD;
		}
	}
}
long long combination(long long n, long long k) {
	if (n <= 0 || k < 0 || n < k) return 0;
	if (k > n - k) k = n - k;
	if (k == 0) return 1;
	if (k == 1) return n;
	return (((numer_table[n] * denom_table[n-k]) % MOD) * denom_table[k]) % MOD;
}

