ll calc_pow(ll x, ll pow) {
    if (pow == 0) return 1;
    ll a = calc_pow(x, pow / 2);
    a = a * a % mod;
    if (pow % 2 == 1) a *= x;
    return a % mod;
}

ll calc_div(ll a, ll b) {
    return a * calc_pow(b, mod - 2) % mod;
}

ll calc_comb(ll n, ll r) {
    if (n < r || n < 0 || r < 0)return 0;
    return calc_div(fact[n], fact[r] * fact[n - r] % mod);
}

