    for (ll i = 2; i < 100010; i++) {
        fact[i] = (fact[i-1]*i)%m;
        rfact[i] = minverse(fact[i], m);
    }
}

ll c3(ll n, ll k, ll m) {
    if (n<k)
        return 0;
    else if (n == k || k == 0)
        return 1;
    else
        return (((fact[n] * rfact[k])%m) * rfact[n-k])%m;
}


