    ll li,ri;
    map<ll,ll>mp,num;
    rep(i,N+1) {
        ll a = A[i];
        mp[a]++;
        if(mp[a]==2){
            li=num[a];
            ri=i;
            break;
        }
        num[a]=i;
    }

    init_nCk(N+1);

    rep1(k,N+1){
        mint res = (nCk(N+1, k) - nCk(N+li-ri, k-1) + mod)%mod;

        cout << res.n << endl;
    }
}

