VI nCr_all(long n){
    VI comb(2,0);
    if (n == 0) return comb;
    long long up = n;
    long long down = 1;
    short flg = 0;
    comb[0] = 1;
    comb[1] = up;
    if (n == 1) return comb;
    FOR(i,2,(n/2)+1){
    	if (flg > 0){
    		flg = ((comb[i-1]+mod*flg) * (up - i + 1) / (down + i - 1)) / mod;
    		comb.push_back(((comb[i-1]+mod*flg) * (up - i + 1) / (down + i - 1)) % mod);
    	}
    	else {
    		if ((comb[i-1] * (up - i + 1) / (down + i - 1)) >= mod){
    			flg = (comb[i-1] * (up - i + 1) / (down + i - 1)) / mod;
    			comb.push_back((comb[i-1] * (up - i + 1) / (down + i - 1)) % mod);
    		}
    		else {
    			comb.push_back((comb[i-1] * (up - i + 1) / (down + i - 1)));
    		}
    	}
    }

    VI comb_rev;
    RREP(i,comb.size()-1) comb_rev.push_back(comb[i]);

    if (n % 2) {
    	REP(i,comb_rev.size()) comb.push_back(comb_rev[i]);
    } 
    else {
    	FOR(i,1,comb_rev.size()) comb.push_back(comb_rev[i]);
    }
    return comb;
}

