            val=it->first;
        }
    }
    int ind1,ind2;
    int cnt=0;
    for(int i=0;i<=n;i++){
        if(a[i]==val&&cnt==0){
            ind1=i;
            cnt++;
        }else if(a[i]==val&&cnt==1){
            ind2=n-i+1;
        }
    }
    com_init();
    for(int i=1;i<=n+1;i++){
        ll ans=0;
        ans+=comb(n+1,i)%MOD;
        ans-=(comb(ind1+ind2,i-1)+MOD)%MOD;
        cout << ans << endl;
    }
}

