/*組み合わせ関数*/
long funcC(long n, long m){
long c;
long ns,ms;
if(m==0) return 1;
if(n==0) return 1;
if(n==m) return 1;
if( n-m<m ) m = n-m;
c=1;
for(ns=n-m+1, ms=1; ms<=m; ns++,ms++){
c *= ns;
c /= ms;
}
return c;
}

