ll mod(ll n, ll p, ll r)
{
    if(p == 0)
    {
        return 1;
    }
    else if (p%2 == 0)
    {
        ll y = mod(n, p/2, r);
        return (y*y)%r;
    }
    else
    {
        return (mod(n, p-1, r)*n%r)%r;
    }
}

void init(ll n)
{
    fact[0] = 1;
    fact[1] = 1;

    for(int i = 2; i <= n+1; ++i)
    {
        fact[i] = (fact[i-1]*i)%1000000007;
    }

    inv[n+1] = mod(fact[n+1], 1000000005, 1000000007);

    for(ll i = n; i >= 0; --i)
    {
        inv[i] = ((i+1)*inv[i+1])%1000000007;
    }

}

ll ncr(ll n, ll r)
{
    ll ret = 1;
    ret *= fact[n];
    ret = (inv[n-r] * ret)%1000000007;
    ret = (inv[r] * ret)%1000000007;

    return ret;
}


