    fact[0] = 1;
    factinv[0] = modinv(0);
    for (long long i = 1; i < 100001; i++)
    {
        now *= i;
        now %= modd;
        fact[i] = now;
        factinv[i] = modinv(now);
    }
}
long long COM(long long n, long long r)
{
    if (n < r)
        return 0;
    if (n < 0 || r < 0)
        return 0;
    if (n == r)
        return 1;
    if (r == 0)
        return 1;
    long long ans = fact[n];
    ans *= factinv[r];
    ans %= modd;
    ans *= factinv[n - r];
    ans %= modd;
    return ans;
}
