ll inv(ll x) {
	ll res = 1;
	ll k = N - 2;
	ll y = x;
	while (k) {
		if (k & 1)res = (res*y) % N;
		y = (y%N*y%N) % N;
		k /= 2;
	}
	return res;
}

ll Comb(ll n, ll k) {
	ll b = a[n];
	ll c = a[n - k];
	ll d = a[k];
	ll cd = (c*d) % N;
	return ((b%N)*(inv(cd)) % N) % N;
}
