    ll MOD = 1e9 + 7;
    rep(i, n + 1) f[i + 1] = (f[i] * (i + 1)) % MOD;
    vector<int> a(n + 1), c(n, 0);
    rep(i, n + 1) {
        cin >> a[i];
        c[a[i] - 1]++;
