int64 modpow(int64 a, int64 r){
    if(r == 0)return 1;
    if(r & 1){
        return modpow(a, r - 1) * a % MOD;
    }else{
        int64 x = modpow(a, r / 2);
        return x * x % MOD;
    }
}

map<pll,int64> combMemo;

int64 comb(int64 n, int64 r){
    r = min(r, n-r);
    if(combMemo.count(pll(n,r)))return combMemo[pll(n,r)];
    int64 retval = 1;
    REP(i,r){
        retval *= (n - i);
        retval %= MOD;
        retval *= modpow(i + 1, MOD-2);
        retval %= MOD;
    }
    return combMemo[pll(n,r)] = retval;
}

