        }
    }
    for(int i=1;i<=n+1;i++)
    {
        ll inc=nCrModPFermat(n+1,i,M);
        ll exc=nCrModPFermat(st+last,i-1,M);
        ll ans=inc-exc;
        if(ans<0)ans+=M;
