mint fact[N],ifact[N];
int used[N];
void init( int n ) {
    fact[0]=1;
    REP(i,n) fact[i+1]=fact[i]*(i+1);
    ifact[n]=fact[n].inv();
    for ( int i=n; i>0; i-- ) ifact[i-1]=ifact[i]*i;
}

mint C( int n, int r ) {
    if ( n<0||r>n ) return 0;
    return fact[n]*ifact[r]*ifact[n-r];
}

int main() {
