//a^bを計算
ll Pow(ll a,ll b){
    ll res = 1;
    while(b){
        if(b % 2) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

//1!~N!の逆数の計算
vector<ll> Reciprocal(){
    ll inv = Pow(fact[N + 1], MOD - 2);
    vector<ll> v(N + 2, 1);
    v[N + 1] = inv;
    for(ll i = N + 1; i > 1; --i){
        inv *= i;
        inv %= MOD;
        v[i - 1] = inv;
    }
    return v;
}

//組合せの計算
ll nCr(ll n, ll r){
    if(r > n) return 0;
    return (fact[n] * invs[r] % MOD) * invs[n - r] % MOD;
}

