int powMOD(int A, int M) {
	if (M == 0) return 1;
	int T = powMOD(A, M/2);
	T = ((long long)T*T)%MOD;
	if (M&1) T = ((long long)T*A)%MOD;
	return T;
}

void precalculate(int N, int comb[]) {
	fact[0] = 1;
	for (int i = 1; i <= N; ++i)
		fact[i] = ((long long)fact[i-1]*i)%MOD;
	product[N+1] = 1;
	for (int i = N; i >= 1; --i)
		product[i] = ((long long)product[i+1]*i)%MOD;
	for (int i = 1; i <= N; ++i)
		comb[i] = ((long long)product[N-i+1]*powMOD(fact[i], MOD-2))%MOD;
	comb[0] = comb[N];
}

int Comb_N(int K) { 	// N = n+1
	if (K < 0 || K > n+1) return 0;
	return comb_N[K]; 
}

int Comb_M(int K) { 	// M = m
	if (K < 0 || K > m) return 0;
	return comb_M[K]; 
}

