            x=n-i;
        }
        used[a]=1;
    }
    for(int i=1;i<=n+1;i++){
        ll res=COM(n+1,i);
        if(x>=i-1) res-=COM(x,i-1);
        res=(res+MOD)%MOD;
        cout << res << endl;
    }
}

