const long long mod = 1000000007;

long long mul(long long a,long long b) {
  return ((a % mod) * (b % mod)) % mod;
}

long long power(long long x,long long y) {
  if (y == 0) {
    return 1;
  } else if (y == 1) {
    return x % mod;
  } else if (y % 2 == 0) {
    long long a = power(x, y/2);
    return a*a % mod;
  } else {
    long long a = power(x, y/2);
    return a*a * x % mod;
  }
}

long long mdiv(long long a,long long b) {
  return mul(a, power(b, mod-2));
}

int main()
{
  int N;
  vector<int> a,tmp_a;
  cin >> N;
  a.reserve(N + 1);

  for (int i = 0; i < N + 1; i++) {
    int c;
    cin >> c;
    a.push_back(c);
  }

  tmp_a = a;
  sort(tmp_a.begin(), tmp_a.end());
  int dup;
  int l = tmp_a[0];
  for (auto it = tmp_a.begin() + 1; it != tmp_a.end(); it++) {
    if (l == *it) {
      dup = *it;
      break;
    }
    l = *it;
  }

  auto fr = find(a.begin(), a.end(), dup);
  auto ba = find(fr + 1, a.end(), dup);
  const auto frnum = fr - a.begin();
  const auto banum = N - (ba - a.begin());

  for (int i = 1; i <= N + 1; i++) {
    long long p = 1;
    for (int j = N + 1; j > N + 1 - i; j--)
      p = mul(p,j);
    for (int j = i; j > 0; j--)
      p = mdiv(p, j);
    p %= 1000000007;
    if ( i > 1) {
      long long q = frnum;
      for (int j = frnum - 1; j > frnum - i + 1; j--)
        q = mul(q,j);
      for (int j = i - 1; j > 0; j--)
        q = mdiv(q, j);
      q %= 1000000007;
      long long r = banum;
      for (int j = banum - 1; j > banum - i + 1; j--)
        r = mul(r,j);
      for (int j = i - 1; j > 0; j--)
        r = mdiv(r, j);
      r %= 1000000007;
      cout << p - q - r << endl;
    } else {
      cout << p - 1 << endl;
    }
  }
  return 0;
}

