	//cout << l << " " << r << endl;

	for (int k = 1; k <= n + 1;k++) {
		ll ans = com.nCr(n+1, k);
		if (l + n - r >= k - 1) {
			ans -= com.nCr(l + n - r, k - 1);
			ans += MOD;
			ans %= MOD;
