	ll same = 0;
	for(P i : ump){
		if(i.sc == 2) same = i.fs;
	}

	init();

	ll t = 0;
	rep(i, n+1){
		if(a[i] == same){
			t += i;
			break;
		}
	}
	repr(i, n+1){
		if(a[i] == same){
			t += n-i;
			break;
		}
	}

	ll ans = 0;
	repn(i, n+1){
		if(i == 1){
			co(n);
