int modpow(int a, int p) {
	if (p == 0) return 1;
	if (p % 2 == 0) {
		int halfP = p / 2;
		int half = modpow(a, halfP);
		return half * half % mod;
	}
	else {

		return a * modpow(a, p - 1) % mod;
	}
}

int comb(int a, int b) {
	if (b > a)return 0;

	if (b > a - b) return comb(a, a - b);


	int ansMul = 1;
	int ansDiv = 1;
	for (int i = 0; i < b; i++)
	{
		ansMul *= (a - i);
		ansDiv *= (i + 1);
		ansMul %= mod;
		ansDiv %= mod;
	}

	int ans = ansMul * modpow(ansDiv, mod - 2) % mod;

	return ans;
}


