        inverse[i] = power(factrial[i], MOD - 2) % MOD;
    }
}

ll nCk(ll n, ll k) {
    if (n<0 || k<0 || n-k<0)return 0;
    return factrial[n] * inverse[k] % MOD * inverse[n - k] % MOD;
}

