template <typename T>
T calc(T a, T b, T p) {
    if (b == 0) return 1;

    if (b % 2 == 0) {
		T d = calc(a, b / 2, p);
		return (d * d) % p;
    } else {
		return (a * calc(a, b - 1, p)) % p;
    }

    return 0;
}

template <typename T>
void ModConb(T& v, T& vi, ll mod) {
	v[0] = 1;
	vi[0] = 1;
	for (int i = 1; i < v.size(); i++) {
		v[i] = v[i - 1] * i;
		v[i] %= mod;

		vi[i] = calc(v[i], mod - 2, mod);
		vi[i] %= mod;
	}
}

int main() {
	const ll MOD = 1e9 + 7;
	ll N;
