__int128 factorial(int n) {
	if (memoFact[n] != 0) return memoFact[n];
	else {
		memoFact[n] = factorial(n - 1) * n;
		return memoFact[n];
	}
}

__int128 conbination(int n, int k) {
	if (n < k) return 0;
	else return factorial(n) / factorial(k) / factorial(n - k);
}

