    map<ll, ll> mp;
    ll d;
    REP(i, n + 1){
        cin >> a[i];
        mp[a[i]]++;
        if(mp[a[i]] == 2) d = a[i];
    }
    ll edge = 0, c = 0;
    REP(i, n + 1){
        if(a[i] == d){
            c++;
            continue;
        }
        if(c == 0 || c == 2) edge++;
    }

    for(int k = 1; k <= n + 1; k++){
        ll res = comb2(n + 1, k) - comb2(edge, k - 1) + MOD;
        res %= MOD;
        cout << res << endl;
    }
    return 0;
}

