vll fact;//階乗
vll revFact;//階乗の逆元
void setFact(int N) {
	fact = vll(N);
	revFact = vll(N);
	fact[0] = 1;
	FOR(i, 1, N) {
		fact[i] = fact[i - 1] * i;
		fact[i] %= MOD;
	}
	revFact[N - 1] = powmod(fact[N - 1], MOD - 2);
	REPR(i, N - 1) {
		revFact[i] = revFact[i + 1] * (i + 1);
		revFact[i] %= MOD;
	}
}


