/*使い方
Factorial a;//Factorialクラスのaを作成　

（※デフォルトで110000が入っているが、もっと大きいnで計算したい場合
Factorial a(1000000);
などと置く必要がある）

Int b = a.Pmod(5, 2);//nPkを計算 → 20を出力
Int c = a.Cmod(5, 2);//nCkを計算 → 10を出力
Int d = a.Pmod(5, 5);//n!を計算 → 120を出力

*/
class Factorial {
private:
	vector<Int> fac, inv, finv;

	void build(Int N) {
		fac[0] = fac[1] = 1; inv[1] = 1; finv[0] = finv[1] = 1;

		for (Int i = 2; i < N; i++) {
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}

public:
	Factorial(Int N = 110000) : fac(N + 1), inv(N + 1), finv(N + 1) { build(N + 1); }

	//nCkの計算
	Int Cmod(Int n, Int k) {
		if (n < k || k < 0) return 0LL;
		return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
	}

	//nPkの計算
	Int Pmod(Int n, Int k) {
		if (n < k || k < 0) return 0LL;
		return fac[n] * finv[n - k] % MOD;
	}
};

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	Int n;
	cin >> n;

	vector<Int> a(n + 1);
	vector<Int> cnt(n + 1);//どの数が2回出てくるか調査
	for (Int i = 0; i < n+1; i++) {
		cin >> a[i];
		cnt[a[i]]++;
	}

	Int res;//2回出てくる数字
	for (Int i = 1; i <= n; i++) {
		if (cnt[i]==2) {
			res = i;
			break;
		}
	}

	Int flag = 0;//走査、resが出てきているか
	Int cnt0, cnt1, cnt2;
	Int temp = 0;
	for (Int i = 0; i < n+1; i++) {
		if (a[i]==res) {
			if (flag==0) {
				cnt0 = temp;
				temp = 0;
				flag = 1;
			}
			else if (flag=1) {
				cnt1 = temp;
				temp = 0;
				flag = 2;
			}
		}
		else {
			temp++;
		}
	}
	cnt2 = temp;

	DMP(cnt0, cnt1, cnt2);

	Factorial b;//nCk計算用
	Int temp1, temp2, temp3, temp4, temp5, temp6,temp7;
	for (Int k = 1; k < n+2; k++) {//長さkの部分列
		temp = 0;
		temp1 = temp2 = temp3 = temp4 = temp5 = temp6 = temp7 = 0;

		if (k==1) {
			cout << n << "\n";
		}

		else {
			//resの数字を一つも使わない場合
			if ((n + 1) - 2 >= 0 && (n + 1) - 2 >= k) {
				temp += b.Cmod((n + 1) - 2, k);
			}

			//resの数字を二つとも使う場合
			if ((n + 1) - 2 >= 0 && k - 2 >= 0 && (n + 1) - 2 >= k - 2) {
				temp += b.Cmod((n + 1) - 2, k - 2);
			}

			//resの数字を1つのみ使う場合
			if (cnt0 >= 0 && cnt0 >= k - 1) {
				temp1 = b.Cmod(cnt0, k - 1);
			}
			if (cnt1 >= 0 && cnt1 >= k - 1) {
				temp2 = b.Cmod(cnt1, k - 1);
			}
			if (cnt2 >= 0 && cnt2 >= k - 1) {
				temp3 = b.Cmod(cnt2, k - 1);
			}

			if (cnt0 + cnt1 >= 0 && cnt0 + cnt1 >= k - 1) {
				temp4 = b.Cmod(cnt0 + cnt1, k - 1);
				temp4 -= temp1 + temp2;
			}
			if (cnt0 + cnt2 >= 0 && cnt0 + cnt2 >= k - 1) {
				temp5 = b.Cmod(cnt0 + cnt2, k - 1);
				temp5 -= temp1 + temp3;
			}
			if (cnt1 + cnt2 >= 0 && cnt1 + cnt2 >= k - 1) {
				temp6 = b.Cmod(cnt1 + cnt2, k - 1);
				temp6 -= temp2 + temp3;
			}

			if (cnt0 + cnt1 + cnt2 >= 0 && cnt0 + cnt1 + cnt2 >= k - 1) {
				temp7 = b.Cmod(cnt0 + cnt1 + cnt2, k - 1);
				temp7 -= temp1 + temp2 + temp3 + temp4 + temp5 + temp6;
			}
			temp += temp1 + temp3 + 2 * (temp2 + temp4 + temp5 + temp6 + temp7);
			cout << temp << "\n";
		}
	}

}

