ll pow(ll a, int n) {
  ll res = 1;
  while (n) {
    if (n & 1) res = res * a % MOD;
    a = a * a % MOD;
    n >>= 1;
  }
  return res;
}

ll fact(int n) {
  ll res = 1;
  for (int i = 2; i <= n; i++)
    res = res * i % MOD;
  return res;
}

int comb(int n, int r) {
  if (n < r) return 0;
  ll tmp = pow(fact(n-r), MOD-2) * pow(fact(r), MOD-2) % MOD;
  return tmp * fact(n) % MOD;
}

