const long long MOD = 1e9 + 7;

vector<long long> fact, inv_fact;

long long POW(long long a, long long b) {
    long long result = 1;
    while (b) {
        if (b & 1) {
            result *= a;
            result %= MOD;
        }

        a *= a;
        a %= MOD;
        b /= 2;
    }

    return result;
}

long long combination(long long n, long long m) {
    if (n < m) {
        return 0;
    }
    return fact[n] * inv_fact[m] % MOD * inv_fact[n - m] % MOD;
}

