    else if (ans1[i - 2] > 0) {
      ll z = ans1[i - 2] * (n + 2 - (y - x + i)) % p;
      z *= modinv(i, p);
      ans1.push_back(z % p);
    }
    else ans1.push_back(ncr(n + 1 - (y - x), i, p));
  }

  vll ans2(0);
  for (ll i = 1; i <= n + 1; i++) {
    if (i == 1) ans2.push_back(ncr(n - (y - x), i - 2, p));
    else if (ans2[i - 2] > 0) {
      ll z = ans2[i - 2] * (n - (y - x + i - 3)) % p;
      z *= modinv(i - 2, p);
      ans2.push_back(z % p);
    }
    else ans2.push_back(ncr(n - (y - x), i - 2, p));
  }

  for (ll i = 1; i <= n + 1; i++) {
    vector<vll> sub(min(i, y - x - 1), vll(2));
    for (ll j = 1; j <= min(i, y - x - 1); j++) {
