    for (ll j = 1; j <= min(i, y - x - 1); j++) {
      ans3 += sub[j - 1][0] * sub[j - 1][1] % p;
      ans3 %= p;
    }
    ll ans = ans1[i - 1];
    ans += ans2[i - 1];
    ans %= p;
    ans += ans3;
    cout << ans % p << endl;
  }
}

