const ll mod = 1e9 + 7;
struct mint {
    ll x;  // typedef long long ll;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}
    mint& operator+=(const mint a)
    {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a)
    {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a)
    {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const
    {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const
    {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const
    {
        mint res(*this);
        return res *= a;
    }
    mint pow(ll t) const
    {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const { return pow(mod - 2); }
    mint& operator/=(const mint a) { return (*this) *= a.inv(); }
    mint operator/(const mint a) const
    {
        mint res(*this);
        return res /= a;
    }
    friend ostream& operator<<(ostream& os, const mint& v)
    {
        os << v.x;
        return os;
    }
};
//---------------------------------------------------------
struct factorial {
    ll factorial_max;
    vector<ll> fact;
    vector<ll> factinv;
    mint permutation(ll n, ll r)
    {
        if (n < 0 || r < 0) {
            return 0;
        }
        if (n < r) {
            return 0;
        }
        mint value = this->fact[n];

        if (this->factinv[n - r] == 0) {
            mint m = this->fact[n - r];
            this->factinv[n - r] = m.inv().x;
        }
        // value /= this->fact[n - r];
        value *= this->factinv[n - r];
        return value;
    }
    mint combination(ll n, ll r)
    {
        if (n < 0 || r < 0) {
            return 0;
        }
        if (n < r) {
            return 0;
        }
        mint value = permutation(n, r);

        if (this->factinv[r] == 0) {
            mint m = this->fact[r];
            this->factinv[r] = m.inv().x;
        }
        // value /= this->fact[r];
        value *= this->factinv[r];
        return value;
    }

    void init_factorial(ll factorial_max = 1e5 + 7)
    {
        this->factorial_max = factorial_max;
        this->fact = vector<ll>(this->factorial_max + 1);
        this->factinv = vector<ll>(this->factorial_max + 1);
        this->fact[0] = 1;
        for (ll i = 1; i <= this->factorial_max; ++i) {
            this->fact[i] = this->fact[i - 1] * i % MOD;
        }
    }
    explicit factorial() { this->init_factorial(); }
};
