struct binomial_coefficient{
    vector<int> facts;
    vector<int> invs;

    int mod_pow(int x, int n, int m){
        if(n== 0) return 1;
        int res = mod_pow(x*x%m,n/2,m);
        if(n&1) res = res*x%m;
        return res;
    }

    int factorial(int x){
        int res = 1;
        rep(i,2,x+1){
            res *= i;res %= mod;
        }
        return res;
    }

    int inv(int n){
        return mod_pow(n,mod-2,mod);
    }

    void init(){
        facts.push_back(1); invs.push_back(1);
        for(int i = 1; i < 300005; i++){
            facts.push_back(facts[i-1]*i%mod);
            invs.push_back(inv(facts[i]));
        }

    }

    int nPr(int n, int r){
        if(r > n) return 0;
        return (facts[n]%mod * invs[n-r]% mod)%mod;
    }

    int nCr(int n, int r){

        if(r > n) return 0;

        if(r < 0) return 0;

        int ans = facts[n]%mod * invs[n-r]%mod * invs[r] % mod;


        return ans;
    }

    int nHr(int n, int r){
        if(n==0 && r==0) return 1;
        return nCr(n+r-1, r);
    }

};

