// x^n in mod
ll modpow(ll a,ll n,ll p){
    ll x = a;
    ll res = 1;
    while(n)
    {
        if(n & 1)
        {
            res = ((ll)res * (ll)x) % p;
        }
        n >>= 1;
        x = ((ll)x*(ll)x) % p;
    }
    return res;
}

// n! in mod
ll fac(ll n, ll mod){
  return facs[n];
}

// nCr in mod
ll comb(ll n, ll r, ll mod){
  if(combs.count(make_pair(n,r))==1)return combs[make_pair(n,r)];

  if(n<0 || n<r || r<0)return 0;
  ll fn = fac(n, mod);
  ll fr = fac(r, mod);
  ll fn_r = fac(n-r, mod);

  ll d = (modpow(fr, mod-2, mod) * modpow(fn_r, mod-2, mod)) % mod;
  ll u = fn%mod;

  ll result = u * d % mod;
  combs[make_pair(n,r)] = result;

  return result;
}

