constexpr ll sqr(const ll &n) { return n*n; }

inline int modPow(ll n, int p)
{
    if (p <= 0) return 1;
    ll x = sqr(modPow(n, p/2)) % MOD;
    if (p & 1) x = x*n % MOD;

    return x;
}

int f[MX], finv[MX];

void init()
{
    f[0] = finv[0] = 1;
    for (ll i = 1; i < MX; ++i) {
        f[i] = i * f[i-1] % MOD;
        finv[i] = modPow(f[i], MOD-2);
    }
    return;
}

int combi(int n, int k)
{
    if (n < k) return 0;
    return 1LL * f[n] * finv[k] % MOD * finv[n-k] % MOD;

}

