ll pow(int a, int b) {
	if (!b) {
		return 1;
	}
	else if (b % 2 == 0) {
		ll d = pow(a, b/2);
		return (d * d)%MOD;
	}
	else {
		return (a*pow(a, b-1))%MOD;
	}
}

ll inv(int a){
    return pow(a, int(MOD-2));
}

ll comb(int a, int b){
    if(a < b) return 0;
    ll ret = 1;
    REP(i, a) ret = ret * (i+1) % MOD;
    REP(i, b) ret = ret * inv(i+1) % MOD;
    REP(i, a-b) ret = ret * inv(i+1) % MOD;
    return ret;
}

