    if(cnt[i] == 2){
      num = i + 1;
      break;
    }
  }

  vector<int> pos;
  for(int i = 0; i < N + 1; i++){
    if(a[i] == num) pos.push_back(i);
  }

  int c = pos[0] + (N - pos[1]);

  Combination cm = Combination(N + 5, MOD);

  for(int k = 1; k <= N + 1; k++){
    ll ans = cm.get(N + 1, k);
    ans -= cm.get(c, k - 1);
    if(ans < 0) ans += MOD;

    cout << ans << endl;
  }

  return 0;
}

