// x^n in mod
ll modpow(ll x, ll n, ll mod){
  if(n==0) return 1;

  if(n%2==0){
    return modpow(x*x%mod, n/2, mod) % mod;
  }else{
    return x * modpow(x, (n-1), mod) % mod;
  }
}

// n! in mod
ll fac(ll n, ll mod){
  ll res = 1;
  rep(i, n){
    res *= (i+1);
    res %= mod;
  }
  return res;
}

// nCr in mod
ll comb(ll n, ll r, ll mod){
  if(n<0 || n<r || r<0)return 0;
  ll fn = fac(n, mod);
  ll fr = fac(r, mod);
  ll fn_r = fac(n-r, mod);

  ll d = (modpow(fr, mod-2, mod) * modpow(fn_r, mod-2, mod)) % mod;
  ll u = fn%mod;

  return u * d % mod;
}

