const long long MOD = 1000000007;

template <long long MOD> class modint {
  long long x;
  long long norm(long long v) {
    v %= MOD;
    return (v+MOD)%MOD;
  }
public:
  modint(long long v = 0) : x(norm(v)) {
  }

  modint operator+(modint other) {
    return norm(x+other.x);
  }

  modint& operator+=(modint other) {
    x = (*this + other).x;
    return *this;
  }

  modint operator-(modint other) {
    return norm(x-other.x);
  }

  modint& operator-=(modint other) {
    x = (*this - other).x;
    return *this;
  }

  modint operator*(modint other) {
    return norm(x*other.x);
  }

  modint operator*=(modint other) {
    x = (*this - other).x;
    return *this;
  }

  /*
    modint operator/(modint other) {
    return x*mod_pow(other.x, MOD-2)%MOD;
    }

    moding operator/=(modint other) {
    x = (*this / other).x;
    return *this;
    }
  */

  modint operator^(long long b) {
    if (b == 0) return 1;
    modint ret = *this ^ (b/2);
    ret = ret * ret;
    if (b % 2 == 1) ret = *this * ret;
    return ret;
  }

  long long value() {
    return x;
  }

  friend istream& operator>>(istream& in, modint& a) {
    long long x; in >> x;
    a = modint(x);
    return in;
  }

  friend ostream& operator<<(ostream& out, modint a) {
    out << a.x;
    return out;
  }
};


template<long long MOD> struct comb {
  vector<modint<MOD>> fact, inv;
  int n;

  comb(int n):n(n),fact(n+1,0),inv(n+1,0) {
    assert(n < MOD);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1]*i;
    inv[n] = fact[n] ^ (MOD-2);
    for (int i = n; i >= 1; i--) inv[i-1] = inv[i]*i;
  }

  modint<MOD> operator()(int m, int k) {
    if (m > n || m < k || k < 0) return 0;
    else return (fact[m]*inv[m-k]*inv[k]).value();
  }
};

