            perm[i] = 1;
        }
        else
        {
            perm[i] = perm[i - 1] * i % R;
        }
    }
    //cout << "twin: " << twin1 << ", " << twin2 << endl;

    for (uint64_t k = 1; k <= (uint64_t)n + 1; k++)
    {
        uint64_t res = n + 1 - (twin2 - twin1 + 1);
        uint64_t result = (R + comb(n + 1, k) - (res < k - 1 ? 0 : comb(res, k - 1))) % R;
        cout << result << endl;
    }

    return 0;
}

