ll PowMod(ll a, ll b)
{
  ll ans = 1, x = a % MOD;
  REP(i, DigN2(b))
  {
    if (Dig2(b, i) == 1)
    {
      ans = (ans * x) % MOD;
    }
    if (i != (DigN2(b) - 1))
    {
      x = (x * x) % MOD;
    }
  }
  return ans;
}

