            continue;
        p = std::min(i, p);
        s = std::min(N - i, s);
    }

    REP(i, N + 1) {
        ll n = i + 1;
        ll ans = cmb.get(N + 1, n);
        ans -= cmb.get(p + s, n - 1);
        cout << (ans + MOD) % MOD << endl;
    }
    return 0;
}

