using Map = std::unordered_map<std::pair<int, int>, int>;

int combination(int n, int r, Map* m) {
  if (r > n)
    return 0;
  r = (r <= n / 2) ? r : n - r;
  if (r == 0)
    return 1;
  if (r == 1)
    return n;
  if ((*m)[{n, r}] > 0)
    return (*m)[{n, r}];
  (*m)[{n, r}] =  combination(n-1, r-1, m) + combination(n-1, r, m);
  return (*m)[{n, r}];
}

Double doubleValueIndex(std::vector<int> as) {
