ll f[2010101], rf[2010101];

ll inv(ll x) {
	ll res = 1;
	ll k = mod - 2;
	ll y = x;
	while (k) {
		if (k & 1) res = (res * y) % mod;
		y = (y * y) % mod;
		k /= 2;
	}
	return res;
}
void init() {
	f[0] = 1;
	rep(i, 1, 2010101) f[i] = (f[i - 1] * i) % mod;
	rf[2010101 - 1] = inv(f[2010101 - 1]);
	rrep(i, 2010101 - 2, 0) rf[i] = (rf[i + 1] * (i + 1)) % mod;
}
