ll C(int n, int k) {
	if (k < 0 || n < k) return 0;

	ll a1 = f[n]; // = n!
	ll b = rf[n - k]; // = (n-k)!
	ll c = rf[k]; // = k!

	ll bc = (b * c) % mod;

	return (a1 * bc) % mod;
}


