    fac[0] = fac[1] = finv[0] = finv[1] = 1;
    for(int i = 2; i < fac_pre_num; i++) fac[i] = i*fac[i-1] % mod;
    finv[fac_pre_num-1] = mod_inv(fac[fac_pre_num-1]);
    for(int i = fac_pre_num-1; i > 2; i--) finv[i-1] = i*finv[i] % mod;
  }
};
constexpr fac_pre_struct fac_pre;

std::tuple<lli, lli, lli> fac_3_mod(lli a, lli b, lli c){
  lli t = 1;
  lli tb=1, tc=1;
  for(int i = 1; i <= a; i++){
    t = (t*i)%mod;
    if(i == b) tb = t;
    if(i == c) tc = t;
  }
  return std::make_tuple(t, tb, tc);
}

class mod_comb_mul{
  std::vector<lli> fac, finv;
  public:
  mod_comb_mul() :
    fac(&fac_pre.fac[0], &fac_pre.fac[fac_pre_num]),
    finv(&fac_pre.finv[0], &fac_pre.finv[fac_pre_num]){}
  lli comb(lli n, lli k){
    if(n < k || k < 0 || n < 0) return 0;
    int pre_size = fac.size();
    if(n >= pre_size){
      fac.resize(n+1);
      finv.resize(n+1);
      for(int i = pre_size; i <= n; i++) fac[i] = i*fac[i-1] % mod;
      finv[n] = mod_inv(fac[n]);
      for(int i = n; i > pre_size; i--) finv[i-1] = i*finv[i] % mod;
    }
    return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
  }
} mcm;

