	while (k > 0) {
		if (k & 1) {
			ans *= a;
			ans %= MOD;
		}
		a *= a;
		a %= MOD;
		k >>= 1;
	}
	return ans;
}

ll Inverse(ll a) {
	return Pow(a, MOD - 2);
}

void Facto_Ini(vector<ll> &k) {
	ll a = 1, i;
	for (i = 1; i < k.size(); i++) {
		a *= i;
		a %= MOD;
		k[i] = a;
	}
