	a = min(n - a, a);
	if (a < 0)
		return 0ll;
	if (a == 0)
		return 1ll;
	ll ans = k[n] * Inverse(k[a]);
	ans %= MOD;
	ans *= Inverse(k[n - a]);
	ans %= MOD;
	return ans;
}

