        if (n % 2) a = a * x % md;
        x = x * x % md;
        n /= 2;
    }
    return a;
}

ll rev_mod(ll x) { return pow_mod(x, md - 2) % md; }

void calc_fd(ll n) {
    for (int i = 1; i <= n + 1; i++) {
        N[i] = (i * N[i - 1]) % md;
