inline li gcd(li a, li b) {
    return b != 0 ? gcd(b, a % b) : a;
}
// a x + b y = gcd(a, b)
inline li extgcd(li a, li b, li &x, li &y) {
    li g = a; x = 1; y = 0;
    if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
    return g;
}

inline li invMod(li a) {
    li x, y;
    if (extgcd(a, MOD, x, y) == 1) return (x + MOD) % MOD;
    else                         return 0; // unsolvable
}

inline li combi(li n, li k) {
    if (n < k) {
        return 0;
    }
    return (((fact_mod[n] * invMod(fact_mod[k])) % MOD) * invMod(fact_mod[n - k])) % MOD;
}

inline li calc(li x) {
    if (x == n + 1) {
        return 1;
    }
    if (x == 1) {
        return n;
    }
    li res = 0;
    if (x < n) {
        // 重複0個
        res += combi(n - 1, x);
    }
    // 重複2個
    res += combi(n - 1, x - 2);

    // 重複1個
    // 2*(n-1Cx-1) - (n-1Cx-1のうち、２つのdの間にないもの)
    li base = 2 * combi(n - 1, x - 1);
    li diff = combi(n - 1 - (d.S - d.F - 1), x - 1);
    //p3(x, base, diff);
    res = (res + base - diff + MOD) % MOD;
    return res;
}

