ll modPow(ll x, ll n)
{
    ll res = 1;
    while (n > 0) {
        if (n & 1) {
            res = res * x % MOD;
        }
        x = x * x % MOD;
        n >>= 1;
    }
    return res;
}

// n!を求める
ll modfactor(ll n)
{
    modfac[0] = 1;
    ll p = 1;
    while (p <= n) {
        //cout << p << "\n";
        modfac[p] = (p * modfac[p - 1]) % MOD;
        p++;
    }
    modfacinv[n] = modPow(modfac[n], MOD - 2);
    modfactorInv(n);
    return modfac[n];
}

// (n!)^-1を求める
void modfactorInv(ll n)
{
    ll p = n - 1;
    while (p >= 0) {
        modfacinv[p] = ((p + 1) * modfacinv[p + 1]) % MOD;
        p--;
    }
}

