VLL fact_inv, fact;

ll pow(int a, ll b, ll m){
    if(!b) return 1;
    if(!(b % 2)){
        ll d = pow(a, b/2, m);
        return (d * d) % m;
    }
    else return (a * pow(a, b-1, m)) % m;
}

ll pow(int a, ll b) {
    return pow(a, b, MOD);
}

ll inv(int a, ll m){ // GCD(a, m) = 1
    return pow(a, m-2);
}

ll inv(int a){
    return inv(a, MOD);
}

ll comb(int a, int b, ll m){
    if(a < b) return 0;
    if(a < 0 || b < 0) return 0;
    ll ret = fact[a];
    ret = ret * fact_inv[b] % m;
    ret = ret * fact_inv[a-b] % m;
    return ret;
}

ll comb(int a, int b){
    return comb(a, b, MOD);
}

void precom(int n, ll m){
    fact.resize(n);
    fact_inv.resize(n);
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    for(int i = 2; i < n; ++i) fact[i] = fact[i-1] * i % m;
    for(int i = 2; i < n; ++i) fact_inv[i] = inv(fact[i]);
    return;
}

void precom(int n){
    precom(n, MOD);
    return;
}


