ll mpow(ll x, ll n) {
    ll res = 1;
    while (n != 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n = n >> 1;
    }
    return res;
}
ll fac(ll i) {
    static ll fatorial[MAX + 1] = {0};

    if (fatorial[i])
        return fatorial[i];
    else if (i == 0)
        return fatorial[0] = 1;
    else
        return fatorial[i] = fac(i - 1) * i % mod;
}
ll ifac(ll i) {
    static ll ifactorial[MAX + 1] = {0};

    if (ifactorial[i])
        return ifactorial[i];
    else if (i == 0)
        return ifactorial[0] = 1;
    else
        return ifactorial[i] = ifac(i - 1) * mpow(i, mod - 2) % mod;
}
ll comb(ll a, ll b) {
    if (a == 0 && b == 0) return 1;
    if (a < b || a < 0) return 0;
    ll tmp = ifac(a - b) * ifac(b) % mod;
    return tmp * fac(a) % mod;
}

