	ll shi = 1;
	REP(i,k) {
		shi *= (n - i);
		shi %= p;
	}
	ll bo = 1;
	REP(i,k) {
		bo *= (i + 1);
		bo %= p;
	}

	shi *= mod_pow(bo,p - 2,p);
	shi %= p;
	return shi;
}

