class Combination {
private:
	long long int *triangle;
	long long int N;
public:
	Combination(long long int max_n);
	~Combination() { free(triangle); };
	long long int calc(long long int n, long long int k);
};

Combination::Combination(long long int max_n) {
	N = max_n + 1;
	triangle = (long long int*) malloc (sizeof(long long int) * N * (N + 1) / 2);
	for (long long int i = 0; i < N; i++) {
		for (long long int j = 0; j <= i; j++) {
			long long int index = i * (i + 1) / 2 + j;
			if (j == 0 || j == i) triangle[index] = 1;
			else {
				long long int left, right;
				left = (i - 1) * i / 2 + j - 1;
				right = (i - 1) * i / 2 + j;
				triangle[index] = (triangle[left] + triangle[right]) % MOD;
			}
		}
	}
}

long long int Combination::calc(long long int n, long long int k) {
	long long int index = n * (n + 1) / 2 + k;
	if (n < k) return 0;
	else return triangle[index];
}


