void pre_computation() {
	fact[0] = 1;
	for (int i = 1; i <= 100001; i++) fact[i] = (i * fact[i - 1]) % MOD;
	// x^(p-1) mod p = 1 mod p --> x^(p-2) mod p = x^(-1) mod p
	inv[0] = 1;
	for (int i = 1; i <= 100001; i++) {
		int pow = MOD - 2;
		long long x = fact[i];
		inv[i] = 1;
		while (pow > 0) {
			if (pow % 2 == 0) {
				x = (x * x) % MOD;
				pow /= 2;
			} else {
				inv[i] = (inv[i] * x) % MOD;
				pow --;
			}
		}
	}
}

long long C(long long n, long long k) {
	if (n < k) return 0;
	return (((fact[n] * inv[n-k]) % MOD) * inv[k]) % MOD;
}

