const int MAX = 510000;
const int mod = 1000000007;

struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%mod+mod)%mod){}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}

// 二項係数計算
mint COM(int n, int k){
    mint a = 1;
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    a *= fac[n] * (finv[k] * finv[n - k] % mod) % mod;
    return a;
}


int main(void){
  int n; cin >> n;
  int a[n];
  set<int> s;
  int dup;
  FOR(i,0,n) {
    cin >> a[i];
    if(s.count(a[i])>0) dup = a[i];
    s.insert(a[i]);
  }
  vector<int> indexdup;
  FOR(i,0,n-1){
    if(a[i]==dup) indexdup.PB(i);
  }

  int outrange = (n+1) - (indexdup[1]-indexdup[0]+1);

  COMinit();
  FOR(i,1,n+1){
    mint ans = 0;
    if(i==1) {
      cout << n << endl;
      continue;
    } else if (i==n+1) {
      cout << 1 << endl;
      continue;
    }

    ans += COM(n+1,i);
    if(i-1<=outrange){
      ans -= COM(outrange,i-1);
    }
    if(a[0]==1 && a[1]==1 && n==1) ans += 1;
    cout << ans.x << endl;
  }
}

