ll inv_fact[MAX_N+2];

ll power(const int b, ll p) {
  ll res = b;
  ll ans = 1;
  while (p > 0) {
    if (p % 2 == 1) {
      ans = res * ans % MAX;
    }
    p = p >> 1;
    res = res * res % MAX;
  }
  return ans;
}

void make_fact_table(int n) {
  fact[0] = 1;
  inv_fact[0] = 1;
  ll f = 1;
  for (int i = 1; i <= n; i++) {
    f = f * i % MAX;
    fact[i] = f;
    inv_fact[i] = power(f, MAX - 2);
    // cout << i << " "  << fact[i] << " " << inv_fact[i] << endl;
  }
}

ll combination(ll n, ll k) {
  if (n < k) return 0;
  int x = fact[n] * inv_fact[k] % MAX;
  return x * inv_fact[n-k] % MAX;
}

ll solve(int k, int n, int p) {
  ll ans;
  ans = combination(n, k) - combination(p, k-1);
  // cout << ans << " " << k << endl;
  return ans;
}

