	cin.rdbuf(ifs.rdbuf());
#endif
	ll N; cin >> N; vector<ll> A(N); FOR(i, N) cin >> A[i]; Factorial FAC(N+1);
	set<ll> cnt; ll double_val = -1;
	for (auto av : A) {
		if (cnt.find( av) != cnt.end()) { double_val = av; break; }
		else {
			cnt.insert(av);
		}
	} ll a=-1, b;
	FOR(i, N) {
		auto av = A[i]; if (av == double_val) {
			if (a == -1) a = i;
			else { b = i; break; } }	}


	FOR(_i, N) {
		auto i = _i + 1;
		if (i == 1) {
			cout << N << endl;
		}
		else {
			if (i == 2) {
				ll ans = FAC.getComb(N + 1, 2) % MOD; 
				ans -= (N - b); ans -= a;
				while (ans < 0) ans += MOD;
				cout << ans << endl;
			}
			else {
				ll ans = FAC.getComb(N+1, i) % MOD;

				// 真ん中以外のみから選択する場合。片側だけ入った場合から、区別できないケースを引く。
				ans -= (N + 1 - 2 - (b - a - 1) >= i - 1) ? FAC.getComb(N + 1 - 2 - (b - a - 1), i - 1) : 0 ; 
				cout << ( ans ) % MOD << endl;
			}
		}
	}
	cout << 1 << endl;

	return 0;
}

