  int first, second = 0;
  std::vector<int> b(n, -1);
  rep(i,n+1) {
    if ( b[ a[i]-1 ] == -1 ) b[ a[i]-1 ] = i;
    else {
      first  = b[ a[i]-1 ];
      second = i; 
    }
  }

  // index i & j
  // n+1Ck ;  m==0~k iCm x n-jCk-m
  for(int k=1; k<=n+1; k++) {
    mint all = nCk(n+1, k);
    mint d = nCk(n+1-(second-first+1), k-1);
    all -= d;
    std::cout << all.x << std::endl;
  }

  return 0;
}

