using namespace std;

long long int power(long long int n, long long int p){
	if (p == 0)
		return 1;


	if (p % 2 == 0)
		return power(n, p/2) * power(n, p/2) % mod;
	else
		return n * power(n, p-1) % mod;
}
long long int inverse(long long int n){
	return power(n, mod-2) % mod;
}


int main(void){
	long long int n;

	cin >> n;

	vector<int> a(n), b(n+1, 0);

	for (int i = 0; i < n; i++){
		cin >> a[i];
		b[a[i]]++;
	}

	int twice = 0;

	for (int i = 1; i < n+1; i++){
		if (b[i] == 2)
			twice = i;
	}

	long long int left = -1, right;

	for (int i = 0; i < n; i++){
		if (left == -1 && a[i] == twice)
			left = i;
		else if (a[i] == twice)
			right = i;
	}

	long long int mid = right - left - 1;


	long long int c1, c2, c3, c4;
	for (long long int k = 1; k <= n; k++){
		if (k == 0){
			c1 = 1;
			c2 = 0;
			c3 = 0;
			c4 = 0;
		}
