			c2 *= (n-k) % mod * inverse(k) % mod;
			c3 *= (n-k+1) % mod * inverse(k-1) % mod;
			c4 = 0;
		}
		else if (k > n - mid - 1){
			c1 = (n-k-1) % mod * inverse(k+1) % mod;
			c2 *= (n-k) % mod * inverse(k) % mod;
			c3 *= (n-k+1) % mod * inverse(k-1) % mod;
			c4 = 0;
		}
