#include<stdio.h>
long divmod=1000000007;
long memofuncC[1000000];

/*組み合わせ関数*/
long funcC(long n, long m){
if(m==0) return 1;
if(n==0) return 1;
if(n==m) return 1;
if(memofuncC[(n)*(n+1)/2+m]>=0) return memofuncC[(n)*(n+1)/2+m];
memofuncC[(n)*(n+1)/2+m] = (funcC(n-1,m-1)+funcC(n-1,m) ) % divmod;
return memofuncC[(n)*(n+1)/2+m];
}

int main(){
long n,t;
long a[100000],done[100001];
long var,first,second;
long i,k,m;
long left,middle,right;
long num;

/*メモの初期化*/
for(i=0;i<100000;i++){
memofuncC[i] = -1;
}

/*読み込んだかどうかの初期化*/
scanf("%ld",&n);
for(i=1;i<=n;i++){
done[i]=0;
}

/*読み込みと同時に２個ある変数の値と後ろの位置を記憶*/
for(i=0;i<n+1;i++){
scanf("%ld",&a[i]);
if(done[ a[i] ]==1){
var = a[i];
second = i;
}else{
done[ a[i] ]=1;
}
}

/*前の位置を調べる*/
for(i=0;i<n;i++){
if(a[i] == var){
first = i;
break;
}
}

/*左中右の個数を調べる。*/
left = first;
middle = second - first - 1;
right = n - second -1 ;

for(k=1;k<=n+1;k++){
if(k==1){printf("%ld\n",n);}
if(k==n+1){printf("%d\n",1);}
if(k>1 && k<n+1){
num = 0;
if(n+1-2>=k) num += funcC(n+1-2,k);  /*含まない*/
if(n+1-2>=k-2) num += funcC(n+1-2,k-2); /*両方含む*/
if(n+1-middle-2>=k-1) num += funcC(n+1-middle-2,k-1); /*片方とミドルなし*/
for(m=1;m<k;m++){
if(middle>=m && n+1-middle-2>=k-m-1) num += funcC(middle,m)*funcC(n+1-middle-2,k-m-1)*2 ; /*ミドルにm個でどちらか片方を選ぶ*/
}
printf("%ld\n",num%divmod);
}
}

return 0;
}

