		temp7 = 0;

		if (k==1) {
			cout << n << "\n";
		}

		else {
			//resの数字を一つも使わない場合
			if ((n + 1) - 2 >= 0 && (n + 1) - 2 >= k) {
				ans += b.Cmod((n + 1) - 2, k);
			}

			//resの数字を二つとも使う場合
			if ((n + 1) - 2 >= 0 && k - 2 >= 0 && (n + 1) - 2 >= k - 2) {
				ans += b.Cmod((n + 1) - 2, k - 2);
			}

			//resの数字を1つのみ使う場合
			if (cnt0 >= 0 && cnt0 >= k - 1) {
				temp1 = b.Cmod(cnt0, k - 1);
			}
			if (cnt1 >= 0 && cnt1 >= k - 1) {
				temp2 = b.Cmod(cnt1, k - 1);
			}
			if (cnt2 >= 0 && cnt2 >= k - 1) {
				temp3 = b.Cmod(cnt2, k - 1);
			}

			if (cnt0 + cnt1 >= 0 && cnt0 + cnt1 >= k - 1) {
				temp4 = b.Cmod(cnt0 + cnt1, k - 1);
				temp4 -= temp1 + temp2;
			}
