class Combination {
private:
	long long mod;
	vector<long long> table;
	vector<long long> invTable;

	long long mpow(long long a, long long n) {
		long long x = 1LL;
		for (; n > 0; n >>= 1, a = (a * a) % mod)
			x = (n & 1) ? (x * a) % mod : x;
		return x;
	}

	void compute(long long n) {
		table = vector<long long>(n + 1, 1);
		invTable = vector<long long>(n + 1, 1);
		for (long long i = 1LL; i < n + 1; i++) {
			table[i] = table[i - 1] * i % mod;
			invTable[i] = mpow(table[i], mod - 2);
		}
	}

public:
	Combination(long long n, long long mod = (long long)1e9 + 7) : mod(mod) { compute(n); }
	long long get(long long n, long long r) {
		if (n < r || n < 0) return 0;
		if (n == 0 && r == 0) return 1;
		return (((invTable[n - r] * invTable[r]) % mod) * table[n]) % mod; 
	}
};


