ll calc_pow(ll n, ll k) {
  if (k == 1) {
    return n;
  }

  if (k % 2 > 0) {
    return calc_pow(n, k - 1) * n % MOD;
  } else {
    ll sub = calc_pow(n, k / 2);
    return sub * sub % MOD;
  }
}

