ll quick_pow(ll a, ll b) {
	ll res = 1;
	a %= mod;
	while (b) {
		if (b & 1) res = res * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return res;
}

#define N 100010
int fac[N], finv[N];
void factorization() {
	//only when mod is prime
	fac[0] = finv[0] = 1;
	for (int i = 1; i <= N - 1; ++i)
		fac[i] = (ll)fac[i - 1] * i % mod;
	finv[N - 1] = quick_pow(fac[N - 1], mod - 2);
	for (int i = N - 2; i; --i)
		finv[i] = (ll)finv[i + 1] * (i + 1LL) % mod;
}

int nCr(int n, int m) {
	//n!/(m!(n-m)!)
	return (ll)((ll)fac[n] * finv[m] % mod)* finv[n - m] % mod;
}

