}

ll mul(ll a, ll b){
    return ((a % MOD) * (b % MOD)) % MOD;
}

ll power(ll x, ll y){
    if( y == 0) return 1;
    else if( y == 1 ) return x % MOD;
    else if( y % 2 == 0) return square(power(x, y/2)) % MOD;
    else return mul(square(power(x, y/2)), x) % MOD;
}

ll Div(ll x, ll y){
    return mul(x, power(y, MOD-2));
}

void fact(void){
    F[0] = 1;
    F[1] = 1;
    for( ll i = 2; i < 100010; i++){
        F[i] = mul(F[i-1],i);
    }
}

ll Combi(ll x, ll y){
    if( x < y ) return 0;
    return Div(F[x], F[x-y]*F[y] % MOD);
}

