ll mod_pow(ll x, ll p, ll m) {
	ll a = 1;
	while (p) {
		if (p % 2)
			a = a * x % m;
		x = x * x % m;
		p /= 2;
	}
	return a;
}

ll mod_inv(ll a, ll m) {
	return mod_pow(a, m - 2, m);
}

ll nCr(int n, int r) {
	return F[n] * invF[r] % MOD * invF[n - r] % MOD;
}

