typedef long long LL;

class Combination
{
public:
	Combination(LL sz, LL m) :
		size(sz+1),
		mod(m),
		param(size, 1)
	{
		for(LL i=2; i<size; i++)
		{
			param[i] = param[i-1] * i;
			param[i] %= mod;
		}
	}

	LL nCr(LL n, LL c)
	{
		LL ret = param[n];
		ret *= inverse(c);
		ret %= mod;
		ret *= inverse(n-c);
		ret %= mod;

		return ret;
	}

private:
	LL inverse(LL n)
	{
		LL ret = 1;
		LL a = param[n];
		for(LL i=mod-2; i>0; i/=2)
		{
			if(i&1)
			{
				ret *= a;
				ret %= mod;
			}
			a *= a;
			a %= mod;
		}
		return ret % mod;
	}

	const LL size;
	const LL mod;
	vector<LL> param;
};

