		table[a[i]]++;
	}

	int left, right;
	for(auto it=table.begin(); it!=table.end(); it++)
	{
		if(it->second == 2)
		{
			left = find(a.begin(), a.end(), it->first) - a.begin();
			right = find(a.begin()+left+1, a.end(), it->first) - a.begin();

			break;
		}
	}

	Combination comb(n+1, 1E9+7);
	for(int i=1; i<=n+1; i++)
	{
		long long ret = comb.nCr(n+1, i);
		if(left+n-right >= i-1)
			ret -= comb.nCr(left+n-right, i-1);

		cout << ret << endl;
	}

	return 0;
}

