inline long long int mod_sub(long long int x, long long int y) {
	return (x + MOD - y) % MOD;
}

inline long long int mod_mul(long long int x, long long int y) {
	return ((x % MOD) * (y % MOD)) % MOD;
}

inline long long int mod_power(long long int x, long long int y) {
	if (y == 0) {
		return 1;
	} else if (y == 1) {
		return x % MOD;
	} else if (y % 2 == 0) {
		long long int t = mod_power(x, y / 2);
		return mod_mul(t, t) % MOD;
	} else {
		long long int t = mod_power(x, y / 2);
		return mod_mul(mod_mul(t, t), x) % MOD;
	}
}

inline long long int mod_div(long long int x, long long int y) {
	return mod_mul(x, mod_power(y, MOD - 2));
}

inline int calc_combination(int n, int c) {
	int ans = 1;
	int count = min(c, n - c);
	for (int j = 0; j < count; j++) {
		ans = mod_mul(ans, n - j);
	}
	for (int j = 1; j < count; j++) {
		ans = mod_div(ans, j + 1);
	}
	return ans;
}

