            // if(x < j)break;
            // if(n - y < k - j - 1)continue;
            cnt += comb(x, j) * comb(n - y, k - j - 1) % MOD;
            cnt %= MOD;
        }
        cout << (comb(n+1, k) - cnt + MOD) % MOD << endl;
    }
    return 0;
}

