vec matmul(vec& dp,mat& mt){
    vec ret(m,0);
    for(int i=0;i<m;i++){
        for(int j=0;j<m;j++)
            ret[i]+=(mt[i][j]*dp[j])%p;
    }
    return ret;
}

//遷移行列の更新
mat update(mat& mt){
    mat ret(m,vec(m,0));
    for(int i=0;i<m;i++){
        for(int j=0;j<m;j++){
            for(int k=0;k<m;k++)
                ret[i][j]+=(mt[i][k]*mt[k][j])%p;
        }
    }
    return ret;
}

