int comb(int n, int k){

  if(c[n][k] > 0){
    return c[n][k];
  }else{
    int d;
    if(n < k){
      d = 0;
    }else if(k == 0 || k == n){
      d = 1;
    }else if(k > n / 2){
      d = comb(n, n-k);
    }else{
      d = (comb(n-1, k) + comb(n-1, k-1)) % 1000000007;
    }
    c[n][k] = d;
    return d;
  }
}


