vector< int > MfactTable(int n, int m) {
	vector< int > ret(n + 1);
	int tmp = 1;
	ret[0] = 1;
	for (int i = 1; i <= n; i++) {
		tmp *= i;
		tmp %= m;
		ret[i] = tmp;
	}
	return ret;
}
