int powr(int a,int b)
{
	long long y=a,x=1;
	while(b>0)
	{
		if(b&1)
		x=(x*y)%M;
		y=(y*y)%M;
		b=b/2;
	}
	return x%M;
}
int mod_inv(int n)
{
	return powr(n,M-2);
}
int c(int n,int r)
{
