namespace mod {
	// a ** n % M
	template<ll M> ll pow(ll a, ll n) {
		ll ret = 1 % M;
		while (n > 0) {
			if (n & 1) ret = ret * a % M;
			a = a * a % M;
			n /= 2;
		}
		return ret;
	}

	template<ll M> ll inv_fermat(ll a) {
		return pow<M>(a, M - 2);
	}

	// inverse using ext-gcd (initially copied from iwi-san)
	template<ll M> inline ll inv(ll a) {
		ll b = M, u = 1, v = 0;
		while (b) {
			ll t = a / b;
			swap(a -= t * b, b);
			swap(u -= t * v, v);
		}
		return (u % M + M) % M;
	}

	// [inv(i) for i in range(n + 1)]
	template<ll M> vll invs(int n) {
		assert(n >= 1);
		vll ret(n + 1);
		ret[1] = 1;
		for (int i = 2; i <= n; i++) {
			ret[i] = M - ret[M % i] * (M / i) % M;
		}
		return move(ret);
	}

	// [pow(a, n) for a in range(n + 1)]
	template<ll M> vll powers(ll a, int n) {
		assert(n >= 0);
		vll ret(n + 1);
		ret[0] = 1 % M;
		for (int i = 1; i <= n; i++) {
			ret[i] = ret[i - 1] * a % M;
		}
		return move(ret);
	}

	// [i! for i in range(n + 1)]
	template<ll M> vll facts(int n) {
		assert(n >= 0);
		vll ret(n + 1);
		ret[0] = 1 % M;
		for (int i = 1; i <= n; i++) {
			ret[i] = ret[i - 1] * i % M;
		}
		return move(ret);
	}

	// [nCr for r in range(n + 1)]
	template<ll M> vll combs(int n) {
		assert(n >= 0);
		vll ret(n + 1);
		ret[0] = 1 % M;
		for (int i = 1; i <= n; i++) {
			ret[i] = ret[i - 1] * (n + 1 - i) % M * inv<M>(i) % M;
		}
		return move(ret);
	}
}

