template<class T> void gc(T &x)
{
    char c;
    int s = 0;
    x = 0;

    c = getchar_unlocked();

    if (c == '-') s = 1;
    else if ('0' <= c && c <= '9')  x = c - '0';

    while (true)
    {
        c = getchar_unlocked();

        if (c < '0' || c > '9') break;
        x = x * 10 + (c - '0');
    }

    if (s) x = -x;
}

int modmulti(int a, int b)
{
    int res = 0;
    int mod = a % INF;
    while (b > 0)
    {
        if ((b & 1) == 1)
        {
            res += mod;
            if (res > INF)
            {
                res -= INF;
            }
        }
        mod <<= 1;
        if (mod > INF)
        {
            mod -= INF;
        }
        b >>= 1;
    }
    return res;
}

int modcalc(int a, int b)
{
    // O(log b)
    int d = 0;
    if (b == 0)
    {
        return 1;
    }
    else if ((b & 1) == 0)
    {
        // 偶数 bを半分にできる
        d = modcalc(a, b / 2);
        return modmulti(d, d);
    }
    else
    {
        // 奇数 -1乗から1乗をかける
        return modmulti(a, modcalc(a, b - 1));
    }
}

int combination(int a, int b)
{
    // tmp = a! / b!
    int tmp = modmulti(FCT[a], INV[b]);
    // tmp / (a - b)!
    return modmulti(tmp, INV[a - b]);
}

void factorial(int x)
{
    //FCT = new int[x + 1];
    FCT[0] = 1;
    FCT[1] = 1;
    for (int i = 2; i <= x; i++)
    {
        FCT[i] = modmulti(FCT[i - 1], i);
    }
}

void inverse(int x)
{
    //INV = new int[x + 1];
    INV[0] = 1;
    INV[1] = 1;
    INV[x] = modcalc(FCT[x], INF - 2);
    for (int i = x - 1; 2 <= i; i--)
    {
        INV[i] = modmulti(INV[i + 1], i + 1);
    }
}

int modadd(int a, int b)
{
    return (a + b) % INF;
}

int main()
{
    int n;

    gc(n);

    int tmp;

    map<int, int> cnt;
    map<int, int> idx;

    int first;
    int second;

    int dbl;

    for (int i = 0; i < n; i++)
    {
        gc(tmp);

        cnt[tmp]++;

        if (cnt[tmp] == 2)
        {
            first = idx[tmp];
            second = i;
            dbl = tmp;
            break;
        }
        else
        {
            idx[tmp] = i;
        }
    }

    printf("%d\n", n);

    // 階乗テーブル作成
    factorial(100001);

    // 逆元テーブル作成
    inverse(100001);

    for (int i = 2; i < n + 1; i++)
    {
        // n+1Ci - n-(second-first)Ci-1
        int ans = combination(n + 1, i);

        if (i - 1 <= n - second + first)
        {
            ans -= combination(n - second + first, i - 1);
        }

        ans = modadd(ans, INF);

        printf("%d\n", ans);
    }

    printf("%d\n", 1);
    return 0;
}

