template<int mod> class mint {
 private:
  int _num;
  mint set(int num){ 
  	_num = num;
  	if(_num>=0) _num%=mod;
  	else while(_num<0) _num+=mod; return *this; }
 public:
  mint(){ _num = 0; }
  mint(int num){_num=num; if(_num>=0)_num %= mod; else while(_num<0) _num+=mod;}
  mint(const mint &cp){_num=cp._num;}
  mint operator= (int x){ return set(x % mod); }
  mint operator+ (int x){ return mint<mod>(_num + (x % mod)); }
  mint operator- (int x){return mint<mod>(_num - (x % mod)); }
  mint operator* (int x){ return mint<mod>(_num * (x % mod)); }
  mint operator/ (int x){ return mint<mod>(_num * m_inv(x));}
  mint operator+=(int x){ return set(_num + (x % mod)); }
  mint operator-=(int x){ return set(_num - (x % mod));}
  mint operator*=(int x){ return set(_num * (x % mod)); }
  mint operator/=(int x){ return set(_num * m_inv(x));}
  mint operator+ (mint x){ return mint<mod>(_num + x._num ); }
  mint operator- (mint x){ return mint<mod>(_num - x._num);}
  mint operator* (mint x){ return mint<mod>(_num * x._num); }
  mint operator/ (mint x){ return mint<mod>(_num * inv_mod(x._num));}
  mint operator+=(mint x){ return set(_num + x._num); }
  mint operator-=(mint x){ return set(_num - x._num); }
  mint operator*=(mint x){ return set(_num * x._num); }
  mint operator/=(mint x){ return set(_num * m_inv(x._num));}

  friend mint operator+(int x,mint m){return mint<mod>(m._num + (x % mod));}
  friend mint operator-(int x,mint m){return mint<mod>(m._num - (x % mod));}
  friend mint operator*(int x,mint m){return mint<mod>(m._num * (x % mod));}
  friend mint operator/(int x,mint m){return mint<mod>(m_inv(m._num) * x);}

  explicit operator int() { return _num; }

  friend ostream& operator<<(ostream &os, const mint<mod> &x){ os << x._num; return os; }
  friend istream& operator>>(istream &is, mint<mod> &x){int val; is>>val; x.set(val); return is;}
};
class Factorial{//階乗とその逆元を求めて計算に利用するクラス
 private:
    vector<int> fac;
    vector<int> ifac;
 public:
    Factorial(int N){
        fac.push_back(1);
        rep(i,N) fac.push_back(fac[i]*(i+1)%mod);
        ifac.resize(N+1);
        ifac[N]=m_inv(fac[N]);
        rep(i,N) ifac[N-1-i]=(ifac[N-i]*(N-i))%mod;
    }
    int fact(int a){return fac[a];}
    int ifact(int a){return ifac[a];}
    int cmb(int a,int b){
    	if(a==0&&b==0) return 1;
        if(a<b||a<0||b<0) return 0;
        int tmp =ifact(a-b)*ifact(b)%mod;
        return tmp*fac[a]%mod;
    }
    int per(int a,int b){
    	if(a==0&&b==0) return 1;
        if(a<b||a<0||b<0) return 0;
        return fac[a]*ifac[a-b]%mod;
    }
};
struct UnionFind {
    vector<int> par; // 親ノード
    UnionFind(int n = 1) { init(n);}
    void init(int n = 1) {
        par.resize(n);
        rep(i,n) par[i] = -1;
    }
    int root(int x) {
        if (par[x] <0) return x;
        else return par[x] = root(par[x]);      
    }
    int size(int x){ return -par[root(x)];}
    bool issame(int x, int y) {return root(x)==root(y);}
    bool connect(int x,int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (size(x) < size(y)) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
	}
};
