int quickPow(const int& x, const int& d) {
  int n = d;
  long long ret = 1, temp = x;
  while (n) {
    if (n & 1)
      ret = ret * temp % mod;
    temp = temp * temp % mod;
    n >>= 1;
  }
  return ret % mod;
}

void init(const int& n) {
  mul[0] = 1;
  for (int i = 1; i <= n; ++i)
    mul[i] = (long long)mul[i - 1] * i % mod;
}

int c(const int& n, const int& m) {
  if (m > n)
    return 0;
  return (long long) mul[n] * quickPow(mul[n - m], mod - 2) % mod * quickPow(mul[m], mod - 2) % mod;
}

