//modulus of nCk - combination mod 
ll nCk(ll n, ll k, ll quotient) {
	//vector<ll> f = factorial(n, quotient);//erase this line when you use!
	ll nCk = (f[n] % quotient);
	nCk *= rsm(f[k], quotient - 2, quotient);
	nCk %= quotient;
	nCk *= rsm(f[n - k], quotient - 2, quotient);
	return (nCk % quotient);
}

