typedef long long ll;

constexpr long long MOD = 1000000000 + 7;

long long get_degree(long long a, long long k) { //a^k O(logN)
	long long res = 1;
	long long cur = a;
	while(k) {
		if (k % 2) res = (res * cur) % MOD;
		k /= 2;
		cur = (cur * cur) % MOD;
	}
	return res;
}
long long denom_table[100000];
void set_denom_table(long long n) {
	for (long long i = 0; i < n; i++) {
		if (i == 0) denom_table[i] = 1;
		else {
			denom_table[i] = (denom_table[i-1] * get_degree(i, MOD-2)) % MOD;
		}
	}
}
long long combination(long long n, long long k) {
	if (n <= 0 || k < 0 || n < k) return 0;
	if (k > n - k) k = n - k;
	if (k == 0) return 1;
	if (k == 1) return n;
	long long numerator = 1, denominator = 1; // 分子 分母
	for (long long i = n; i > n - k; i--) {
		numerator = (numerator * i) % MOD;
	}
	return (numerator * denom_table[k]) % MOD;
}

