int arithmeticSequence(int firstTerm, int lastTerm, int terms, int idx, int overlapIdx) {

    if (firstTerm == 1) {
        return 1;
    }

    int sum = ((firstTerm + lastTerm) * terms) / 2;
    int now = idx != overlapIdx? sum : 0;
    int next = arithmeticSequence(firstTerm - 1, lastTerm, terms - 1, idx + 1, overlapIdx);

    return now + next;

}

int solve(int N, int k, int idx, int overlapIdx) {

    if (k == 1) {
        return N;
    }

    if (k == 2) {
        return ((N + 1) * N) / 2 - (N + 1 - overlapIdx);
    }

    return arithmeticSequence(N - (k - 2), 1, N - (k - 2), idx, overlapIdx);

}

