VL fact(100010), inv(100010);

ll calc_pow(ll n, ll k) {
  if (k == 1) {
    return n;
  }

  if (k % 2 > 0) {
    return calc_pow(n, k - 1) * n % MOD;
  } else {
    ll sub = calc_pow(n, k / 2);
    return sub * sub % MOD;
  }
}

void precalc() {
  inv[0] = fact[0] = 1;
  NREP(i, 100000) {
    fact[i] = fact[i - 1] * i % MOD;
    inv[i] = calc_pow(fact[i], MOD - 2);
  }
  return;
}

ll comb(ll a, ll b) {
  if (a == 0) {
    if (b == 0) {
      return 1;
    } else {
      return 0;
    }
  }

  return fact[a] * inv[a - b] % MOD * inv[b] % MOD;
}


