int kaijou(int n) {
	if (n == 0) {
		return 1;
	}
	else {
		int i = 1;
		int cnt = 1;
		for (i;i <n + 1;i++) {
			cnt *= i/1000000007;
		}
		return cnt;
	}
}

int cmb(int n, int k) {
	if (n == 0 || k == 0) {
		return 0;
	}
	else if (n < k) {
		return 0;
	}
	else {
		int cnt = kaijou(n) / (kaijou(k)*kaijou(n - k));
		return cnt;
	}
}

