long long cmb(int x,int r){
    if(r > x / 2) r = x - r; // because C(n, r) == C(n, n - r)
    long long an = 1;


    for(int i = 1; i <= r; i++) {
        an *= x - r + i;
        an /= i;
    }

    return an;
}

long long ans(int k){
    long long rt=cmb(n+1,k);
    if(d1+1>=k){
        rt-=cmb(d1,k-1);
    }
    if(n-d2+1>=k){
        rt-=cmb(n-d2,k-1);
    }

    return rt%=1000000007;
}


