typedef long long ll;

ll ex[100002];
ll ex_rev[100002];

ll my_pow(ll a, ll b) {
	if(b==1) return a;
	ll h = my_pow(a,b/2);
	h = (h*h)%MOD;
	if(b%2==1) h = (h*a)%MOD;
	return h;
}

ll combination(int n, int m) {
	ll num;
	num = ex[n];
	num = (num*ex_rev[m])%MOD;
	num = (num*ex_rev[n-m])%MOD;
	return num;
}

void init_ex(int n) {
	ex[0] = 1;
	ex_rev[0] = 1;
	for(int i = 1; i <= n; i++) {
		ex[i] = (ex[i-1]*i)%MOD;
		ex_rev[i] = my_pow(ex[i],MOD-2LL);
	}
}

int main() {
	int n;
	cin >> n;
	init_ex(n+1);
	vector<int> hist(n+1);
	vector<int> input(n+1);
	for(int i = 0; i < n+1; i++) {
		cin >> input[i];
		hist[input[i]]++;
	}
	int t;
	for(int i = 1; i <= n; i++) {
		if(hist[i]>1) {
			t = i;
			break;
		}
	}
	int a=-1,b;
	for(int i = 0; i < n+1; i++) {
		if(input[i]==t) {
			if(a==-1) a=i;
			else {
				b=i;
				break;
			}
		}
	}
	vector<ll> ans(n+2);
	for(int i = 1; i <= n+1; i++) {
		ans[i] = combination(n+1,i);
	}
	int l = a+(n-b)+1;
	for(int i = 0; i < l; i++) {
		ans[i+1] -= combination(l-1,i);
		ans[i+1] += MOD;
		ans[i+1] %= MOD;
	}
	for(int i = 1; i <= n+1; i++) {
		cout << ans[i] << endl;
	}
	return 0;
}

