	}
	x = *find(data.begin(), data.end(), a[N - y]) - 1;
	for(lint k = 1; k <= N + 1; k++){
		lint ans = COM(N + 1, k) - COM(x + y, k - 1) + MOD;
        cout << ans%MOD << endl;
	}
}

