    for (auto p : mp)
    {
        if (p.second > 1)
        {
            num = p.first;
        }
    }
    for (ll i = n; i >= 0; i--)
    {
        if (a[i] == num)
        {
            idx[1] = i;
            break;
        }
    }
    for (ll i = 0; i < n; i++)
    {
        if (a[i] == num)
        {
            idx[0] = i;
            break;
        }
    }

    for (ll i = 0; i < n + 1; i++)
    {
        ll k = i + 1;
        ll ans = COM(n + 1, k);
        ll yobun = COM(idx[0] + (n - idx[1]), k - 1);
        cout << (ans - yobun + MOD) % MOD << endl;
    }
}

