ll powmod(ll x, ll n) {
    ll ans = 1;
    while(n) {
        if(n & 1) {
            ans = ans * x % MOD;
        }
        x = x * x % MOD;
        n >>= 1;
    }
    return ans;
}

ll fact(ll x) {
    ll ans = 1;
    for(; x; x--) ans = ans * x % MOD;
    return ans;
}

ll invmod(ll x) {
    return powmod(x, MOD - 2);
}

ll ncr(ll k, ll n) {
    if(k < 0 || k > n) return 0;
    ll a = fact(n);
    ll b = fact(k) * fact(n - k) % MOD;
    return a * invmod(b) % MOD;
}

