    kaijo_tbl[i] = (kaijo_tbl[i-1] * (i % waru)) % waru;
    kaijo_watta[i] = (kaijo_watta[i-1] * beki(i, waru-2)) % waru;
  }

  map<ll,vector<ll>> mp;

