// gcd(a,b) および ax+by=gcd(a,b) となる x, y の導出
ll Extgcd(ll a, ll b, ll& x, ll& y)
{ 
    ll g = a;
    if (b != 0) {
        Extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1, y = 0;
    }
    return g;
}

// ax = gcd(a, m)となるxの導出
// a,m が互いにその時、x は mod m での a のモジュラ逆数となる
ll ModInverse(ll a, ll m)
{
    ll x, y;
    Extgcd(a, m, x, y);
    return (x % m + m) % m;
}

