	mint& operator+=(mint a) {
		n += a.n;
		n %= mod;
		return *this;
	}
	mint& operator-=(mint a) {
		n += mod;
		n -= a.n;
		n %= mod;
		return *this;
	}
	mint& operator*=(mint a) {
		n *= a.n;
		n %= mod;
		return *this;
	}
	mint& operator%=(mint a) {
		n %= a.n;
		return *this;
	}
	mint& operator++() {
		n++;
		n %= mod;
		return *this;
	}
	mint& operator--() {
		n += mod;
		n--;
		n %= mod;
		return *this;
	}
};

