  if(b & 1) return (powmod(a, b - 1) % M) * a % M;
  else{
    long long d = powmod(a, b / 2);
    return d * d % M;
  }
}

long c(long a, long b){
  if(b > a) return 0;
  return fact(a) * (powmod((fact(b) * fact(a - b) %M), M - 2) % M) % M;
}

