ll Pow(ll A, ll N){
  if (N == 0) return 1;
  else if (N % 2 == 0) return Pow(A*A%MOD, N/2);
  else return A * Pow(A*A%MOD, N/2)%MOD;
}

int N, a[int(1e5+5)];
int mark = 0, cnt = 0;
bool visited[int(1e5+5)];
ll A, B, C;
ll abc[int(1e5+5)], ac[int(1e5+5)], bc[int(1e5+5)], cc[int(1e5+5)];

int main(){
  cin >> N;
  for (int i = 0; i <= N; i++){
    cin >> a[i];
    if (visited[a[i]]) mark = a[i];
    visited[a[i]] = true;
  }

  for (int i = 0; i <= N; i++){
    if (a[i] == mark){
      cnt++; continue;
    }
    if (cnt == 0) A++;
    if (cnt == 1) B++;
    if (cnt == 2) C++;
  }

  abc[0] = 1; 
  for (ll i = 1; i <= A+B+C; i++){
    abc[i] = abc[i-1] * (A+B+C+1-i) % MOD;
    abc[i] *= Pow(i, MOD-2); abc[i] %= MOD;
  }

  ac[0] = 1;
  for (ll i = 1; i <= A; i++){
    ac[i] = ac[i-1] * (A+1-i) % MOD;
    ac[i] *= Pow(i, MOD-2); ac[i] %= MOD;
  }

  bc[0] = 1;
  for (ll i = 1; i <= A + C; i++){
    bc[i] = bc[i-1] * (A+C+1-i) % MOD;
    bc[i] *= Pow(i, MOD-2); bc[i] %= MOD;
  }

  cc[0] = 1;
  for (ll i = 1; i <= C; i++){
    cc[i] = cc[i-1] * (C+1-i) % MOD;
    cc[i] *= Pow(i, MOD-2); cc[i] %= MOD;
  }

  for (int i = 1; i <= N + 1; i++){
    ll ans = abc[i];
    ans += 2 * abc[i-1] - bc[i-1];
    if (i > 1) ans += abc[i-2];
    cout << ans % MOD << endl;
  }

  return 0;
}

