using namespace std;

ll am[100002];
ll bm[100002];
ll factrial_division[100002] = {};

// a^n mod を計算する
ll modpow(ll a, ll n, ll mod) {
    ll ans = 1;
    while (n > 0) {
        if (n & 1) ans = ans * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return ans;
}

// a^{-1} mod を計算する
ll modinv(ll a, ll mod) {
   return modpow(a, mod - 2, mod);
}

//n個からk個を選ぶ場合の数
ll select(int n, int k, ll *p){
   if(n == 0 || k > n){
      return 0;
   }else if(n == k){
      return 1;
   }else{
      p[k] = p[k-1] * (n - k + 1) % MAX;
      if(factrial_division[k] == 0) factrial_division[k] = factrial_division[k - 1] * modinv(k, MAX) % MAX;
      return p[k] * factrial_division[k] % MAX;
   }
}

int main(){
   int n, a, flag = 0, mid;

   cin >> n;
   vector<int> memo(n + 1, -1);
   for(int i = 0; i < n + 1; i++){
      cin >> a;
      if(flag == 0){
         if(memo[a] == -1){
            memo[a] = i;
         }else{
            mid = i - memo[a] + 1;
            flag = 1;
         }
      }
   }

   //初期化
   am[1] = n + 1;
   bm[0] = 1;
   factrial_division[0] = 1;
   factrial_division[1] = 1;

   cout << n << endl;
   for(int i = 2; i <= n + 1; i++){
      cout << select(n + 1, i, am) - select(n + 1 - mid, i - 1, bm) << endl;
   }
}

