using namespace std;

const uint64_t R = 1'000'000'007L;

int a[100'001];
int occurence[100'000];

uint64_t perm[100'001];

uint64_t dpow(const uint64_t x, const uint64_t y)
{
    if (y == 0)
    {
        return 1;
    }
    else if (y % 2 == 0)
    {
        return dpow(x * x % R, y / 2);
    }
    else
    {
        return x * dpow(x, y - 1) % R;
    }
}

uint64_t inv(const uint64_t x)
{
    return dpow(x, R - 2);
}
uint64_t comb(const uint64_t n, const uint64_t k)
{
    return perm[n] * inv(perm[n - k]) % R * inv(perm[k]) % R;
}

int main()
{
    int n;
    cin >> n;

    int twin1, twin2;
    for (int i = 0; i < n; i++)
    {
        occurence[i] = -1;
    }
    for (int i = 0; i < n + 1; i++)
    {
        cin >> a[i];
        a[i]--;
        if (occurence[a[i]] == -1)
        {
            occurence[a[i]] = i;
        }
        else
        {
            twin1 = occurence[a[i]];
            twin2 = i;
        }
    }
    for (int i = 0; i <= n + 1; i++)
    {
        if (i == 0)
        {
            perm[i] = 1;
        }
        else
        {
            perm[i] = perm[i - 1] * i % R;
        }
    }
    cout << "twin: " << twin1 << ", " << twin2 << endl;

    for (uint64_t k = 1; k <= (uint64_t)n + 1; k++)
    {
        uint64_t res = n + 1 - (twin2 - twin1 + 1);
        uint64_t result = (R + comb(n + 1, k) - (res < k - 1 ? 0 : comb(res, k - 1))) % R;
        cout << result << endl;
    }

    return 0;
}

