ll quick_pow(ll a,ll n,ll p)
{
    ll x = a;
    ll res = 1;
    while(n)
    {
        if(n & 1)
        {
            res = ((ll)res * (ll)x) % p;
        }
        n >>= 1;
        x = ((ll)x*(ll)x) % p;
    }
    return res;
}

ll C(ll n,ll m,ll p)
{
    ll a = 1,b = 1;
    if(m > n) return 0;
    while(m)
    {
        a = (a * n) % p;
        b = (b * m) % p;
        m--;
        n--;
    }
    return ((ll)a * (ll)quick_pow(b,p-2,p))%p;
}

ll Lucas(ll n,ll m,ll p)
{
    if(m==0)
        return 1;
    return((ll)C(n%p,m%p,p)*(ll)Lucas(n/p,m/p,p))%p;
}

