long long add_mod (long long x, long long y) {
	if (x + y < mod)
		return x + y;
	return x + y - mod;
}

long long sub_mod (long long x, long long y) {
	if (x >= y)
		return x - y;
	return x + mod - y;
}

long long mul_mod (long long x, long long y) {
	return (x * y) % mod;
}

long long pow_mod (long long x, long long y) {
	long long res = 1, t = x;
	while (y) {
		if (y & 1)
			res = mul_mod(res, t);
		t = mul_mod(t, t);
		y >>= 1;
	}
	return res;
}

long long div_mod (long long x, long long y) {
	return mul_mod(x, pow_mod(y, mod - 2));
}

long long ncr_mod (long long x, long long y) {
	if (x < y || y < 0)
		return 0LL;
	return div_mod(fact[x], mul_mod(fact[y], fact[x - y]));
}

void precalc () {
	fact[1] = fact[0] = 1LL;
	for (long long i = 2; i < maxn; ++i) 
		fact[i] = mul_mod(i, fact[i - 1]);
}

