const long long int formod = 1000000007;

unsigned long long int modfordivide(unsigned long long int x, unsigned long long int prime){
    unsigned long long int xpowerprime_2=1;
    bitset <64> prime2_bit;
    prime2_bit = static_cast<bitset<64> > (prime-2);
    if(prime2_bit[0]==1) xpowerprime_2 *= x;
    for(int i=1;i<64;i++){
        x = ((x%prime) * (x%prime))%prime;
        if(prime2_bit[i]==1){
            xpowerprime_2 = ((xpowerprime_2%prime) * (x%prime))%prime;
        }
    }
    return xpowerprime_2;
}

