vector<vector<long>> memo;

long comb(int a, int b) {
    if (b > a) {
        return 0;
    } else if (memo[a][b] != -1) {
        return memo[a][b];
    } else if (memo[a][a - b] != -1) {
        return memo[a][a - b];
    }

    if (b == 0) {
        return 1;
    }

    memo[a][b] = comb(a - 1, b - 1) * a / b;
    return memo[a][b];
}

