#include <bits/stdc++.h>

constexpr int64_t M = 1000000007;

int64_t mpow(int64_t x, int64_t n) {
  int64_t ans = 1;
  while (n != 0) {
    if (n & 1) {
      ans = ans * x % M;
    }
    x = x * x % M;
    n = n >> 1;
  }
  return ans;
}


int main() {
  int64_t n;
  std::cin >> n;
  std::vector<int64_t> a(n, -1);

  int64_t first, second;
  for (int64_t i = 0; i <= n; i++) {
