    if (a[t - 1] == -1) {
      a[t - 1] = i;
    } else {
      first = a[t - 1];
      second = i;
    }
  }
  int64_t l = first + n - second;

  int64_t v1 = 1, v2 = 1;
  for (int64_t i = 0; i <= n; i++) {
    v1 *= n + 1 - i;
    v1 %= M;
    v1 *= mpow(i + 1, M - 2);
    v1 %= M;
    if (i == 0) {
      v2 = 1;
    } else if (i <= l) {
      v2 *= l - (i - 1);
      v2 %= M;
      v2 *= mpow(i, M - 2);
      v2 %= M;
    } else {
      v2 = 0;
    }
    std::cout << v1 - v2 << std::endl;
  }
