  int64 l = find(as.begin(), as.end(), x) - as.begin();
  int64 r = find(as.begin() + l + 1, as.end(), x) - as.begin();

  int64 all = 1;
  int64 dup = 1;
  int64 m = n - r + l;
  for (int64 k = 1; k <= n + 1; ++k) {
