    if (k - 1 > m)
      dup = 0;
    else if (k > 1) {
      dup = dup * (m - k + 2) % kMod;
      dup = dup * PowMod(k - 1, kMod - 2) % kMod;
    }
    int64 ret = all - dup;
    if (ret < 0)
      ret += kMod;
    cout << ret << "\n";
  }

  return 0;
}

