        if(a[i] == a[id2]){
            id1 = i;
            break;
        }
    }

    table(n+2);

    // 重複している数字をxとして、xの左にある数字の個数
    // a = [...x.....x...]
    int num1 = id1;
    // xの右側にある数字の個数
    int num2 = n - id2;

    cout << n << "\n";
    // 重複している数字：x
    for(int i = 2; i <= n; ++i){        // 数字をi([2,n])個取る
        ll res = combination(n + 1, i) - combination(num1 + num2, i - 1);
        res %= mod;

        cout << res << "\n";
    }
    cout << 1 << "\n";
}

