struct factorial {
    ll factorial_max;
    vector<mint> fact;
    mint permutation(ll n, ll r)
    {
        if (n < 0 || r < 0) {
            return 0;
        }
        if (n < r) {
            return 0;
        }
        mint value = this->fact[n];
        value /= this->fact[n - r];
        return value;
