        }
        mint value = permutation(n, r);
        value /= this->fact[r];
        return value;
    }

    void init_factorial(ll factorial_max = 1e5 + 7)
    {
        this->factorial_max = factorial_max;
        this->fact = vector<mint>(this->factorial_max + 1);
        this->fact[0] = 1;
        for (ll i = 1; i <= this->factorial_max; ++i) {
            this->fact[i] = this->fact[i - 1] * i;
        }
    }
    explicit factorial() { this->init_factorial(); }
};
//---------------------------------------------------------

void solve()
{
    ll N;
    in(N);
    vll A(N + 1);
    vin(A, N + 1);
    vll pos(N + 2, -1);
    factorial fact;
    ll dup_start = -1;
    ll dup_end = -1;
    for1 (i, N + 1) {
        if (pos[A[i]] == -1) {
            pos[A[i]] = i;
        }
        else {
            dup_start = pos[A[i]];
            dup_end = i;
        }
    }
    ll dup_len = dup_end - dup_start - 1;
    // dump(dup_len, dup_end, dup_start);
    for2 (len, 1, N + 2) {
        if (len == 1) {
            print(N);
            continue;
        }
        mint ans = 0;
        // does not use dup
        ans += fact.combination(N + 1 - 2, len);
        // use 1 dup
        ans += fact.combination(N + 1 - 2 - dup_len, len - 1);
        for2 (i, 1, min(len + 1, dup_len + 1)) {
            mint ans1 = fact.combination(dup_len, i) *
                        fact.combination(N + 1 - 2 - dup_len, len - 1 - i) * 2;
            // dump(ans1);
            ans += ans1;
        }
        // use 2 dup
        for1 (i, min(len + 1, dup_len + 1)) {
            mint ans2 = fact.combination(dup_len, i) *
                        fact.combination(N + 1 - 2 - dup_len, len - 2 - i);
            // dump(ans2);
            ans += ans2;
        }
        print(ans);
    }
}

