const int N=1e5+5;
mint fact[N],ifact[N];
int used[N];
void init( int n ) {
    fact[0]=1;
    REP(i,n) fact[i+1]=fact[i]*(i+1);
    ifact[n]=fact[n].inv();
    for ( int i=n; i>0; i-- ) ifact[i-1]=ifact[i]*i;
}

mint C( int n, int r ) {
    if ( n<0||r>n ) return 0;
    return fact[n]*ifact[r]*ifact[n-r];
}

int main() {
    int n;
    cin >> n;
    init(n+2);
    VI a(n+1);
    REP(i,n+1) cin >> a[i];
    memset(used,-1,sizeof(used));
    int r=0;
    REP(i,n+1) { if ( used[a[i]]!=-1 ) {
        r=i;
    } else {
        used[a[i]]=i;
    } }
    cout << n << '\n';
    REP1(i,2,n+1) {
        mint tot=C(n+1,i);
        mint x=C(n+1-r,i);
        // cout << tot << ' ' << x << '\n';
        cout << tot-x << '\n';   
    }
    return 0;
}

