ll binpow(ll a, ll b)
{
  if (b == 0)
    return 1;
  else if (b % 2 == 1)
    return a * binpow(a, b - 1) % m;
  else {
    ll tmp = binpow(a, b / 2);
    return tmp * tmp % m;
  }
}


void init_table(ll n)
{
  ll x = 1;
  comb[0] = 1;
  comb_inv[0] = 1;

  for (ll i = 1; i <= n + 1; i++) {
    x = x * i % m;
    comb[i] = x;
    comb_inv[i] = binpow(comb[i], m - 2);
  }
}

ll combination(ll n, ll r)
{
  if (n < r)
    return 0;

  if (r == 0 || n == r)
    return 1;

  return (((comb[n] * comb_inv[r]) % m) * comb_inv[n - r]) % m;
}

