ll mod_pow(ll x, ll n){
    ll ans = 1;
    while(n != 0){
        if(n & 1)ans = ans * x % MOD;
        x = x * x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll comb(ll n, ll k){
    if(n == 0 && k == 0)return 1;
    if(n < k || n < 0)return 0;

    ll tmp = fac_inv[n - k] * fac_inv[k] % MOD;
    return tmp * fac[n] % MOD;
}

