lli comb(lli n, lli k)
{

  if( n < k )
    {
      return 0LL;
    }

  lli ans = fac[n];
  ans *= invfac[n-k];
  ans %= MOD;
  ans *= invfac[k];
  ans %= MOD;
  return ans;
}




