long C(long n, long r){
    if(n < r) return 0;
    long p[n+1][n+1];
    p[0][0] = 1;
    for(int i = 1; i <= n; i++){
        p[i][0] = 1;
        p[i][i] = 1;
        for(int j = 1; j <= i-1; j++){
            p[i][j] = p[i-1][j] + p[i-1][j-1];
        }
    }
    return p[n][r];
}

void solve()
{
    int n;
    long mod = (long)pow(10, 9) + 7;
    cin >> n;
    int a[n+2], indexOf[n+1];

    long long p[n+2][n+2];
    p[0][0] = 1LL;
    for(int i = 1; i <= n+1; i++){
        p[i][0] = 1LL;
        p[i][i] = 1LL;
        for(int j = 1; j <= i-1; j++){
            p[i][j] = (p[i-1][j] + p[i-1][j-1]) % mod;
        }
    }

    bool f[n+1];
    for(int i = 1; i <= n; i++) f[i] = false;
    int r=1, l=n, x;
    for(int i = 1; i <= n+1; i++) {
        cin >> a[i];
        if(!f[a[i]]) {
            f[a[i]] = true;
        }
        else{
            x = a[i];
        }
    }
    for(int i = 1; i <= n+1; i++){
        if(a[i] == x){
            l = i;
            break;
        }
    }
    for(int i = n+1; i >= 1; i--){
        if(a[i] == x){
            r = i;
            break;
        }
    }

    for(int k = 1; k <= n+1; k++){
        long long ans = p[n+1][k];
        if(l + n - r >= k - 1) ans -= p[min(l-r+n, n+1)][k-1];
        ans %= mod;
        cout << ans << endl;
    }
    return;
}

