ll comb(int n, int r, vector<vector<ll> >& memo) {

    if ( r - n > 0 ) return 0;

    if (memo[n][r] > 0) return memo[n][r];
    else return memo[n][r] = (comb(n-1, r-1, memo) + comb(n-1, r, memo)) % MOD;
}

