int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n; cin>>n;
    Combination bn(n+1);
    map<int,int> M;
    int left, right;
    rep(i,n+1){
        ll a; cin>>a;
        if (M.count(a)){
            left = M[a];
            right = i;
            break;
        }
        M[a] = i;
    }
    int extra = left+(n-right);
    FOR(k,1,n+1){
        cout<<bn.comb(n+1,k)-bn.comb(extra,k-1)<<"\n";
    }
    return 0;
}

