using namespace std;
const long long Mod=1e9+7;
long long inv[100005],finv[100005],fac[100005];
void make(){
	fac[0]=fac[1]=1;
	finv[0]=finv[1]=1;
	inv[1]=1;
	for (int i=2;i<=1e5;i++){
		fac[i]=fac[i-1]*(long long)i%Mod;
		inv[i]=(Mod-inv[Mod%i]*(Mod/i)%Mod)%Mod;
		finv[i]=finv[i-1]*inv[i]%Mod;
	}
}
long long C(int a,int b){
	if (a<b){
		return 0;
	}
	return fac[a]*(finv[b]*finv[a-b]%Mod)%Mod;
}
int id[100005];
int n;
int main(){
	make();
	scanf("%d",&n);
	memset(id,-1,sizeof(id));
	int s,t;
	for (int i=0;i<=n;i++){
		int a;
		scanf("%d",&a);
