		}
		else{
			s=id[a];
			t=i;
		}
	}
	for (int i=1;i<=n+1;i++){
		long long ans=C(n+1,i);
		ans-=C(s+n-t,i-1);
		if (ans<0){
			ans+=Mod;
		}
		printf("%lld\n",ans);
	}
	return 0;
}

