ll INF = 1LL << 60;

const long long MOD = 1000000007;

ll extgcd(ll a, ll b, ll &x, ll &y){
    if(b == 0){
        x = 1; y = 0;
        return a;
    }
    ll d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
    return d;
}

//* calculate a^-1 mod m
ll mod_inverse(ll a, ll m){
    ll x, y;
    extgcd(a, m, x, y);
    return(m + x%m) % m;
}

//* calculate C(n, 0), C(n, 1), ... C(n, n) mod p in O(n) 
vll mod_comb_list(ll n, ll p){
    vll res(n+1, 1);
    for(ll k=1; k <= n; k++){
        res[k] = (res[k-1] * (n - k + 1)) % p;
        res[k] = (res[k] * mod_inverse(k, p)) % p;
    }
    return res;
}

void solve(long long n, std::vector<long long> a){
    //* decide replicate position
    map<ll, vll> rec_a;
    REP(i, n+1) {
        if(!rec_a.count(a[i])){
            rec_a[a[i]] = vll(1, i);
        }
        else{
            rec_a[a[i]].push_back(i);
        }
    }
    ll L, R;
    for(auto x: rec_a){
        if(x.second.size()>1){
            L = x.second[0]; R=x.second[1]; break;
        }
    }
    if(L > R) swap(L, R);
    ll m = n - (R - L);
    vll ctotal= mod_comb_list(n+1, MOD), csub = mod_comb_list(m, MOD);
    for(ll k = 1; k <= n+1; k++){
        ll res = ctotal[k];
        if(k-1 <= m) res = (res - csub[k-1]) % MOD;
        if(res < 0) res += MOD;
        cout<< res<<endl;
    }
}

