vector<ll> fact_inv, fact;

ll pow(int a, int b) {
	if (!b) {
		return 1;
	}
	else if (b % 2 == 0) {
		ll d = pow(a, b/2);
		return (d * d) % MOD;
	}
	else {
		return (a*pow(a, b-1)) % MOD;
	}
}


ll inv(int a){
    return pow(a, int(MOD-2));
}

ll comb(int a, int b){
    if(a < b) return 0;
    if(a < 0 || b < 0) return 0;
    ll ret = fact[a];
    ret = ret * fact_inv[b] % MOD;
    ret = ret * fact_inv[a-b] % MOD;
    return ret;
}

void precom(int n){
    fact.resize(n);
    fact_inv.resize(n);
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    for(int i = 2; i < n; ++i) fact[i] = fact[i-1] * i % MOD;
    for(int i = 2; i < n; ++i) fact_inv[i] = inv(fact[i]);
    return;
}

