long long pow(long long int a, long long b, long long mod) {
	if (b == 0) return 1;
	else if (b % 2 == 1) {
		return a * pow(a, b - 1, mod) % mod;
	} else {
		long long t = pow(a, b / 2, mod);
		return t * t % mod;
	}
}

void init(int n) {
	fact[0] = 1;
	inv[0] = 1;
	long long now = 1;
	for (int i = 1; i <= n; i++) {
		now = now * i % mod;
		fact[i]	= now;
		inv[i] = pow(fact[i], mod - 2, mod);
	}
}


int comb(int n, int k) {
	if (n < k) return 0;
	if (k <= 0) return 1;
	return ((fact[n] * inv[k]) % mod * inv[n - k]) % mod;
}

