struct mint{
    static const long long MOD = 1000000007;

    long long v;

    mint() : v(0) {}
    mint(long long x){
        x = x % MOD;
        if(x < 0){ x += MOD; }
        v = x;
    }
    mint& operator+=(mint a){
        v += a.v;
        if(v >= MOD){ v -= MOD; }
        return *this;
    }
    mint& operator*=(mint a){
        v *= a.v;
        v %= MOD;
        return *this;
    }
    mint& operator-=(mint a){
        v -= a.v;
        if(v < 0){ v += MOD; }
        return *this;
    }
    mint& operator/=(mint a){
        return (*this) *= a.inv();
    }

    mint operator*(mint a) const{
        return mint(v) *= a;
    }

    mint operator+(mint a) const {
        return mint(v) += a;
    }

    mint operator-(mint a) const {
        return mint(v) -= a;
    }

    mint operator/(mint a) const {
        return mint(v) /= a;
    }

    mint pow(long long k) const {
        mint res(1),tmp(v);
        while(k){
            if(k&1) res *= tmp;
            tmp *= tmp;
            k >>= 1;
        }
        return res;
    }
    mint inv(){return pow(MOD - 2); }

    static mint comb(long long n, int k){
        mint res(1);
        for(int i = 0; i < k; ++i){
            res *= mint(n - i);
            res /= mint(i + 1);
        }
        return res;
    }

    static mint factorial(long long n){
        mint res(1);
        for(int i = n; i > 1; --i){
            res *= mint(i);
        }
        return res;
    }

    bool operator<(const mint &a) const {
        return v < a.v;
    };
};

mint operator*(long long l, mint r){ return r * l; }

vector<mint> factorial;

void calc_factorials(ll n){
    factorial.resize(n + 1, 0);
    factorial.at(0) = 1;
    for(ll i = 1; i <= n; ++i){
        factorial.at(i) = factorial.at(i - 1) * i;
    }
}

mint comb(ll n, ll k){
    if(n < k){
        return 0;
    }else{
        return factorial.at(n) / factorial.at(k) / factorial.at(n - k);
    }
}

int main(){
    ll n;
    cin >> n;
    vector<ll> a(n + 1);
    vector<ll> count(n, 0);
    ll dup_num;
    for(int i = 0; i < n + 1; ++i){
        cin >> a.at(i);
        a.at(i)--;
        count.at(a.at(i))++;
        if(count.at(a.at(i)) == 2){
            dup_num = a.at(i);
        }
    }

    vector<ll> len(3, 0);
    int i = 0;
    for(int j = 0; j < n + 1; ++j){
        if(a.at(j) == dup_num){
            i++;
        }else{
            len.at(i)++;
        }
    }

    calc_factorials(n);

    for(ll k = 1; k <= n + 1; ++k){
        mint tmp = 0;
        tmp += comb(len.at(0) + len.at(1) + len.at(2), k);
        if(k >= 2){
            tmp += comb(len.at(0) + len.at(1) + len.at(2), k - 2);
        }
        if(k >= 1){
            tmp += 2 * (
                comb(len.at(0) + len.at(1) + len.at(2), k - 1)
                - comb(len.at(0) + len.at(2), k - 1)
            );
            tmp += comb(len.at(0) + len.at(2), k - 1);
        }
        cout << tmp.v << endl;
    }
    return 0;
}

