        return mpow(-1, k) * fact[n + k - 1] * factinv[n - 1] % MOD * factinv[k] % MOD;
    }
    if (k < 0 || k > n) return 0;
    return fact[n] * factinv[k] % MOD * factinv[n - k] % MOD;
}

