typedef long long ll;

ll AN(ll A, ll N){
  if (N == 0){
    return 1;
  }else{
    if (N % 2 == 0){
      return AN(A * A % nmax, N / 2) % nmax;
    }else{
      return A * AN(A * A % nmax, N / 2) % nmax;
    }
  }
}

ll nCk(ll n, ll k){
  ll ans = 1;
  for (ll i = 0; i < k; i++){
    ans = ans * (n - i); ans %= nmax;
    ans = ans * AN(i + 1, nmax - 2); ans %= nmax;
  }
  return ans;
}


