// gcd(a,b) および ax+by=gcd(a,b) となる x, y の導出
ll Extgcd(ll a, ll b, ll& x, ll& y)
{ 
    ll g = a;
    if (b != 0) {
        Extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1, y = 0;
    }
    return g;
}

// ax = gcd(a, m)となるxの導出
// a,m が互いにその時、x は mod m での a のモジュラ逆数となる
ll ModInverse(ll a, ll m)
{
    ll x, y;
    Extgcd(a, m, x, y);
    return (x % m + m) % m;
}

// mod MOD での i! のモジュラ逆数テーブルの生成
// i は 0 ~ MAX_NUM-1
constexpr ll MOD = 1000000007;
constexpr ll MAX_NUM = 100000 * 2;

vector<ll> fact(MAX_NUM);
vector<ll> rfact(MAX_NUM);

void FactInit()
{
    fact[0] = rfact[0] = 1;
    for(int i = 1; i < MAX_NUM; i++) {
        fact[i] = fact[i - 1] * i % MOD;
        rfact[i] = rfact[i - 1] * ModInverse(i, MOD) % MOD;
    }
}

// C(n,k) (mod MOD)の導出
inline ll Combination(ll n, ll k)
{
    return (fact[n] * rfact[k] % MOD) * rfact[n - k] % MOD;
}

