long long BigMod(long long a, long long n, ll M) {
    if(!n) return 1%M;
    long long x = BigMod(a, n/2 ,M);
    x = (x*x)%M;
    if(n&1) x = (x*a)%M;
    return x%M;
}

void init(ll n)
{
    fact[0] = 1;
    for(ll i = 1; i <= n; i++) fact[i] = (fact[i-1]*i)%MOD;
    for(ll i = 0; i <= n; i++) inv[i] = BigMod(fact[i], MOD-2, MOD);
}

long long nCr(ll n, ll r)
{
    if(n < r || r < 0 || n < 0) return 0;
    return (fact[n] * ((inv[r]*inv[n-r])%MOD))%MOD;
}

