ll power(ll x, ll n) {
    ll ans = 1;
    while (n > 0) {
        if ((n & 1) == 1) {
            ans = ans * x % MOD;
        }
        x = x * x % MOD;
        n >>= 1;
    }
    return ans;
}

void init(ll n) {
    factrial[0] = 1;
    inverse[0] = 1;
    for (ll i = 1; i <= n; i++) {
        factrial[i] = (factrial[i - 1] * i) % MOD;
        inverse[i] = power(factrial[i], MOD - 2) % MOD;
    }
}

ll nCk(ll n, ll k) {
    if (n<0 || k<0 || n-k<0)return 0;
    return factrial[n] * inverse[k] % MOD * inverse[n - k] % MOD;
}

