  }
}

ll mod_pow(ll x, ll n) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) {
      res = res * x % MOD;
    }
    x = x * x % MOD;
    n >>= 1;
  }
  return res;
}

ll mod_inv(ll x) {
  return mod_pow(x, MOD - 2) % MOD;
}

ll nCr(ll n, ll r) {
  return (dp[n] * mod_inv(dp[r]) % MOD) * mod_inv(dp[n-r]) % MOD;
}

void solve() {
  init();
  int first = 0, second = 0;
  for (int i=0;i<=n_;i++) {
