inline int modPow(int n, int p)
{
    if (p <= 0) return 1;
    ll ret = sqr(modPow(n, p/2)) % MOD;
    if (p & 1) (ret *= n) %= MOD;
    return ret;
}

void preCalc()
{
    f[0] = finv[0] = 1;
    for (ll i = 1; i < MX; ++i) {
        f[i] = i * f[i-1]  % MOD;
        finv[i] = modPow(f[i], MOD-2);
    }
