lint minv(lint a) {
    lint inv = 1, rem = 1, pw = MOD - 2;
    while (pw > 1) {
        if (pw%2 == 1) {
            rem = (rem*a)%MOD;
        }
        a = (a*a)%MOD;
        pw /= 2;
    }
    return (a*rem)%MOD;
}

