ll mpow(ll a, ll n) {
	if (n == 0) return 1;
	if (n % 2 == 0) {
		ll d = mpow(a, n / 2);
		return d * d % MOD;
	}
	return a * mpow(a, n - 1) % MOD;
}
void inverse(ll N) {
	FACT[0] = 1;
	IFACT[0] = 1;
	for (int i = 1;i <= N;i++) {
		FACT[i] = FACT[i - 1] * i % MOD;
		IFACT[i] = invMod(FACT[i], MOD);
	}
}
ll combi(ll n, ll r) {
	if (n < 0 || r < 0 || r > n)return 0;
	if (r > n / 2)r = n - r;
	return FACT[n] * IFACT[n - r] % MOD*IFACT[r] % MOD;
}


