const ll mod = 1000000007;
struct mint {
    ll x;  // typedef long long ll;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}
    mint& operator+=(const mint a)
    {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a)
    {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a)
    {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const
    {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const
    {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const
    {
        mint res(*this);
        return res *= a;
    }
    mint pow(ll t) const
    {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const { return pow(mod - 2); }
    mint& operator/=(const mint a) { return (*this) *= a.inv(); }
    mint operator/(const mint a) const
    {
        mint res(*this);
        return res /= a;
    }
    friend ostream& operator<<(ostream& os, const mint& v)
    {
        os << v.x;
        return os;
    }
};
mint combination(ll n, ll r)
{
    if (n == 0 && r == 0) {
        return 1;
    }
    if (n <= 0 || r < 0) {
        return 0;
    }
    if (n < r) {
        return 0;
    }
    if (n - r < r) {
        return combination(n, n - r);
    }
    mint value = 1;
    for1 (i, r) {
        value *= n - i;
    }
    for1 (i, r) {
        value /= i + 1;
    }
    return value;
}

void solve()
{
    ll N;
    in(N);
    vll A(N + 1);
    vin(A, N + 1);
    vll pos(N + 2, -1);
    ll dup_start = -1;
    ll dup_end = -1;
    for1 (i, N + 1) {
        if (pos[A[i]] == -1) {
            pos[A[i]] = i;
        }
        else {
            dup_start = pos[A[i]];
            dup_end = i;
        }
    }
    ll dup_len = dup_end - dup_start - 1;
    // dump(dup_len, dup_end, dup_start);
    for2 (len, 1, N + 2) {
        if (len == 1) {
            print(N);
            continue;
        }
        mint ans = 0;
        // does not use dup
        ans += combination(N + 1 - 2, len);
        // use 1 dup
        ans += combination(N + 1 - 2 - dup_len, len - 1);
        for2 (i, 1, min(len + 1, dup_len + 1)) {
            mint ans1 = combination(dup_len, i) *
                        combination(N + 1 - 2 - dup_len, len - 1 - i) * 2;
            // dump(ans1);
            ans += ans1;
        }
        // use 2 dup
        for1 (i, min(len + 1, dup_len + 1)) {
            mint ans2 = combination(dup_len, i) *
                        combination(N + 1 - 2 - dup_len, len - 2 - i);
            // dump(ans2);
            ans += ans2;
        }
        print(ans);
    }
}

