constexpr ll MOD = ll(1e9 + 7ll);

class Factorial {
public:
	Factorial() = delete;
	static ll myPow(ll x, ll n, ll m) {
		if (n == 0)
			return 1LL;
		if (n % 2LL == 0)
			return myPow(x * x % m, n / 2LL, m);
		else
			return x * myPow(x, n - 1, m) % m;
}

	Factorial(ll N) : N(N) {
		// 1 ... N までの
		FAC.resize(N+1LL);
		DEFAC.resize(N+1LL);

		FAC[0] = FAC[1] = 1LL;
		FOR(i, N)
			(FAC[i + 1] = FAC[i] * (i + 1ll)) %= MOD;

		DEFAC[N] = myPow(FAC[N], MOD - 2, MOD);
		FOR(_i, N) {
			auto i = N - _i;
			(DEFAC[i - 1] = DEFAC[i] * i) %= MOD;
		}
	}
	ll getComb(ll N, ll B) {
		if (N < B) {
			throw "[Factorial]::getComb  nCb  b is larger than b.";
		}
		return (FAC[N] * DEFAC[N - B])%MOD * (DEFAC[B]) % MOD;
	}
	vector<ll> FAC;
	vector<ll> DEFAC;
	ll N;
};

