ll mod=1e9+7;

ll modinv(ll a){
  ll b=mod,u=1,v=0;
  while(b){
    ll t=a/b;
    a-=t*b; swap(a,b);
    u-=t*v; swap(u,v);
  }
  u%=mod;
  if(u<0) u+=mod;
  return u;
}

ll fac[300010];

void modfac(){
  fac[0]=1;
  for(ll i=1;i<300010;i++){
    fac[i]=(fac[i-1]*i)%mod;
  }
}

ll modcomb(ll n,ll k){
  if(n<k) return 0;
  else return ((fac[n]*modinv(fac[k]))%mod*modinv(fac[n-k]))%mod;
}

