struct Double {
  int front;
  int back;
};


int combination(int n, int r, std::map<std::pair<int, int>, int>* m) {
  if (r > n)
    return 0;
  r = (r <= n / 2) ? r : n - r;
  if (r == 0)
    return 1;
  if (r == 1)
    return n;
  if ((*m)[{n, r}] > 0)
    return (*m)[{n, r}];
  (*m)[{n, r}] =  combination(n-1, r-1, m) + combination(n-1, r, m);
  return (*m)[{n, r}];
}

Double doubleValueIndex(std::vector<int> as) {
  std::vector<int> check(as.size(), -1);
  for (int i = 0; i < (int)as.size(); ++i) {
    if (check[as[i]] >= 0)
      return {check[as[i]], i};
    check[as[i]] = i;
  }
  return {-1, -1};
}

