void COMinit()
{
    long long now = 1;
    fact[0] = 1;
    factinv[0] = modinv(0);
    for (long long i = 1; i < 110003; i++)
    {
        now *= i;
        now %= modd;
        fact[i] = now;
        factinv[i] = modinv(now);
    }
