long long binpow(long long a, long long b)
{
    bp[0] = 1;
    bp[1] = a;
    for (int i = 2; i < 40; i++)
    {
        bp[i] = (bp[i - 1] * bp[i - 1]) % p;
        //cout << bp[i] << endl;
    }

    int d = 1;
    long long res = 1;

    while (b)
    {
        if (b & 1)
        {
            res = (res * bp[d]) % p;
        }
        d++;
        b = b >> 1;
    }
    return res;
}

void make_ftable(int n)
{
    f[0] = 1;
    fi[0] = 1;
    f[1] = 1;
    fi[1] = 1;
    for (int i = 2; i <= n; i++)
    {
        f[i] = i * f[i - 1] % p;
        fi[i] = binpow(f[i], p - 2) % p;
    }
}

long long C(long long n, long long r)
{
    if (n < 0 || r < 0 || r > n)
    {
        return 0LL;
    }
    return (f[n] * ((fi[r] * fi[n - r]) % p)) % p;
}

