const ll MOD = 1e9 + 7;
// return a^b in O(log b)
ll mypow(ll a, ll b){
    if (b == 0)
        return 1;
    ll tmp = mypow(a, b / 2);
    if (b % 2)
        return (((tmp * tmp) % MOD) * a) % MOD;
    else
        return (tmp * tmp) % MOD;
}

// return nCk O(n + klogMOD)
long long comb(int n, int k){
    long long res = 1;
    k = std::min(n - k, k);
    for (int i = n - k + 1; i <= n; i++)
        res = (res * i) % MOD;
    for (int i = 1; i <= k; i++)
        res = (res * mypow(static_cast<long long>(i), static_cast<long long>(MOD - 2))) % MOD;
    return res;
}

