class ModWorld
{
    class IlligalStatementException{};
    vector<int> fac, rfac;
    inline ll sqr(ll n) const { return n*n; }

public:
    const int MOD;

    explicit ModWorld(int mod): MOD(mod) {}

    void calcFact(const int max) noexcept {
        fac.resize(max+1); rfac.resize(max+1);
        fac[0] = rfac[0] = 1;
        for (ll i = 1; i <= max; ++i) {
            fac[i] = i * fac[i-1] % MOD;
            rfac[i] = inv(fac[i]);
        }
    }
    inline int pow(int n, int p) const noexcept {
        if (p <= 0) return 1;
        const ll t = sqr(pow(n, p/2)) % MOD;
        return (p&1)? mul(t, n) : t;
    }
    inline int fact(int n) const noexcept {
        if (n < 0) return 0;
        return fac[n];
    }
    inline int nCr(int n, int r) const noexcept {
        if (r < 0 || n < r) return 0;
        return mul(fac[n], mul(rfac[r], rfac[n-r]));
    }
    inline int nPr(int n, int r) const noexcept {
        if (r < 0 || n < r) return 0;
        return mul(fac[n], rfac[n-r]);
    }
    inline int inv(int n)      const noexcept { return pow(n, MOD-2); }
    inline int add(ll a, ll b) const noexcept { return (a+b) % MOD; }
    inline int sub(ll a, ll b) const noexcept { return (a-b+MOD) % MOD; }
    inline int mul(ll a, ll b) const noexcept { return a * b % MOD; }
    inline int div(ll a, ll b) const noexcept { return a * inv(b) % MOD; }
};

