	}
}

int cmb(int n, int k) {
	if (n == 0 || k == 0) {
		return 0;
	}
	else if (n < k) {
		return 0;
	}
	else {
		int cnt = kaijou(n) / (kaijou(k)*kaijou(n - k));
		return cnt;
	}
}

