    vector <long> vnMinusMinusCombi(n-1,1);  //(n-2)Ci
    for(long i = 1; i < n+1; i++){
        vnCombi[i] = vnCombi[i - 1] * (n - i + 1);
        vnCombi[i] %= nPrime;
        vnCombi[i] *= Inverse(i);
        vnCombi[i] %= nPrime;
        if(i < n){
            vnMinusCombi[i] = vnMinusCombi[i - 1] * (n - i);
            vnMinusCombi[i] %= nPrime;
            vnMinusCombi[i] *= Inverse(i);
            vnMinusCombi[i] %= nPrime;
        }
        if(i < n-1){
            vnMinusMinusCombi[i] = vnMinusMinusCombi[i - 1] * (n - i - 1);
            vnMinusMinusCombi[i] %= nPrime;
            vnMinusMinusCombi[i] *= Inverse(i);
            vnMinusMinusCombi[i] %= nPrime;
        }
        if(i < k+1){
            vkCombi[i] = vkCombi[i - 1] * (k - i + 1);
            vkCombi[i] %= nPrime;
            vkCombi[i] *= Inverse(i);
            vkCombi[i] %= nPrime;
        }
    }

    for(int i = 1; i <= n; i++){
