ll kurikaeshi(ll a,ll b) {
	ll ans = 1;
	while (b) {
		if (b % 2) {
			ans *= a;
		}
		a *= a;
		b /= 2;
		a %= 1000000007;
		ans %= 1000000007;
	}
	return ans;
}

ll warizan(ll a,ll b) {
	// a÷bを行います
	ll ans = a;
	ans *= kurikaeshi(b, 1000000005);
	ans %= 1000000007;
	return ans;
}

