int64_t exp_mod(int a, int b, int p) {
  int64_t ans = 1;
  int64_t cur = a;
  while (b > 0) {
    if (b % 2 == 1)
      ans = (ans * cur) % p;
    cur = (cur * cur) % p;
    b /= 2;
  }
  return ans;
}

