    vi used(N, -1);

    REP(i, N+1) {
        cin >> a; a--;
        if (used[a] >= 0) {
            l = used[a];
            r = i;
        } else {
            used[a] = i;
        }
    }

//    cout << l << " -- " << r << endl;

    vector<vector<ll> > memo(N+2, vector<ll>(N+2, -1));
    REP(i, N+2) {
        memo[i][0] = 1;
        memo[0][i] = 1;
    }

    for (int k = 1; k <= N+1; k++) {
        cout << comb(N+1, k, memo) - comb(N+1-(r+1)+l, k-1, memo) << endl;
    }

    return 0;
}

