int64_t pw(int64_t x,int64_t y){
  int64_t z;
  if(y==0) return 1;
  else{
    z=pw(x*x%mod,y/2);
    if(y%2==1) z=z*x%mod;
    return z;
  }
}
int64_t comb(int64_t n,int64_t r){
  int64_t x=1,i,ans;
  if(n<r) return 0;
  for(i=1;i<=r;i++){
    x=x*(n-i+1)%mod;
    x=x*pw(i,mod-2)%mod;
  }
  return x;
}
