const ll mod=1000000007;

ll modinv(ll a){
  ll b=mod,q;
  ll x0=1,x1=0;
  while(b>1LL){
    q=a/b;
    x0-=x1*q;
    swap(x0,x1);
    a=a%b;swap(a,b);
    while(x1<0LL)x1+=mod;
    x1%=mod;
  }
  return x1;
}

