  for(int k=1; k<=n+1; k++) {
    ll ans = 0;
    ans += comb(n-1, k);
    if(k >= 2) (ans += comb(n-1, k-2)) %= mod;
    if(k >= 1) {
      (ans += comb(n-1, k-1) * 2 + mod - comb(p1+n-p2, k-1)) %= mod;
    }
    cout << ans << endk;
  }
  return 0;
}

