long long M = 1000000007;

int calc_index(int *a, int n){
  int t[n];
  copy(a, a + n, t);
  sort(t, t + n);
  int x;
  FOR(i, 1, n){
    if(t[i - 1] == t[i]){
      x = t[i];
      break;
    }
  }

  int flg = 1;
  int result = n - 1;
  rep(i, n){
    if(a[i] == x){
      result += i * flg;
      flg *= -1;
    }
  }
  return result;
}

long facts[100001];
void c_fact(){
  facts[0] = 1;
  long result = 1;
  FOR(i, 1, 100001){
    result *= i;
    if(result > M){
      result %= M;
    }

    facts[i] = result;
  }
}

long fact(long a){
  return facts[a];
}

long long powmod(long long a, long long b){
  if(b == 0) return 1;
  if(b & 1) return (powmod(a, b - 1) % M) * a % M;
  else{
    long long d = powmod(a, b / 2);
    return d * d % M;
  }
}

long c(long a, long b){
  if(b > a) return 0;
  return fact(a) * (powmod((fact(b) * fact(a - b)), M - 2) % M) % M;
}

