ll pow_m(ll x, ll n) {
    ll ans = 1;
    ll xx = x % MOD;
    for (ll m = n; m != 0; m >>= 1) {
        if (m & 1) {
            ans = (ans * xx) % MOD;
        }
        xx = (xx * xx) % MOD;
    }
    return ans;
}

vector<ll> fact_memo(1e5 + 10, -1);
ll fact_m(ll n) {
    if (fact_memo[n] != -1) {
        return fact_memo[n];
    }
    if(n < 0){
        return 0;
    }
    if(n <= 1){
        return fact_memo[n] = 1;
    }
    return fact_memo[n] = (n * fact_m(n - 1)) % MOD;
}

ll inverse_m(ll n) { return pow_m(n, MOD - 2); }

ll comb_m(ll n, ll r) {
    if(n < r){
        return 0;
    }
    ll ans = 1;
    ans *= fact_m(n);
    ans %= MOD;
    ans *= inverse_m(fact_m(n - r));
    ans %= MOD;
    ans *= inverse_m(fact_m(r));
    ans %= MOD;
    return ans;
}

