typedef long long ll;

const ll Q = 1000000007;

ll fact_list[100005];

ll pow_q (ll x, ll y){
    if ( y == 0 ) return 1;
    ll ans = 1;
    ll z = x;
    ll s = 0;
    while ( y >> s > 0){
        if ( y >> s & 1) ans *= z;
        ans %= Q;
        ++s;
        z *= z;
        z %= Q;
    }
    return ans;
}

void set_fact(){
    fact_list[0] = 1;
    for ( ll i = 1; i < 100005; i++ )
        fact_list[i] = (i * fact_list[i-1]) % Q;
}

ll combi_q(ll x, ll y){
    if ( y < 0 || x < y ) return 0;
    else return ( fact_list[x] * pow_q( ( fact_list[y] * fact_list[x-y] ) % Q , Q - 2) ) % Q;
}

int main(int argc, const char * argv[]) {

    cin.tie(0);
    ios::sync_with_stdio(false);

    set_fact();

    ll n;
