    for ( auto x: mp ){
        if ( x.second.size() > 1 ){
            l = x.second[0];
            r = x.second[1];
        }
    }

    for ( ll i = 1; i < n + 2; i++ ){
        ll ans = 0;
        ans += combi_q( n - 1, i);
        ans += 2 * combi_q( n - 1, i - 1 ) - combi_q( n - r + l, i - 1 );
        ans += combi_q( n - 1, i - 2);
        cout << ans % Q << endl;
    }

    return 0;
}

