class combination_mod
{
private:
	std::vector<long long>factorial_mod;
	long long divisor;
public:
	combination_mod(long long div, long long sup_n) :divisor(div), factorial_mod(std::vector<long long>(sup_n + 1))
	{
		factorial_mod[0] = 1;
		for (long long i = 1; i <= sup_n; i++)
		{
			factorial_mod[i] = factorial_mod[i - 1] * i % divisor;
		}
	}
	long long operator()(long long n, long long r)
	{
		long long numerator = factorial_mod[n];
		long long denominator = factorial_mod[r] * factorial_mod[n - r] % divisor;
		long long index = divisor - 2, power = 1;
		while (index > 0)
		{
			if ((index & 1) == 1)
			{
				power *= denominator;
				power %= divisor;
			}
			denominator *= denominator;
			denominator %= divisor;
			index >>= 1;
		}
		return numerator * power % divisor;
	}
};
int main()
{
	int n;
	std::cin >> n;
	std::vector<int>a(n + 1);
	int head, foot;
