		if (already[a[i] - 1])
		{
			head = static_cast<int>(std::find(a.begin(), a.end(), a[i]) - a.begin());
			foot = n - i;
		}
		already[a[i] - 1] = true;
	}
	combination_mod cm(1000000007, 100000);
	for (int i = 0; i < n + 1; i++)
	{
		std::cout << cm(n + 1, i + 1) - (head + foot >= i ? cm(head + foot, i) : 0) << std::endl;
	}
	return 0;
}

