int gcdExtended(int a, int b, int *x, int *y) { //From http://www.geeksforgeeks.org/multiplicative-inverse-under-modulo-m/
    if (a == 0)
    {
        *x = 0, *y = 1;
        return b;
    }

    int x1, y1; // To store results of recursive call
    int gcd = gcdExtended(b%a, a, &x1, &y1);

    // Update x and y using results of recursive
    // call
    *x = y1 - (b/a) * x1;
    *y = x1;

    return gcd;
}

int modinv(int a) {
	int x,y;
	gcdExtended(a, MOD,&x,&y);
	return (x%MOD+MOD)%MOD;
}

void genfacts() {
	ll num = 1;
	facts[0] = 1;
	factinvs[0] = 1;
	for(int i = 1; i <= 100003; i++) {
		num*= i;
		num = num%MOD;
		facts[i] = num;
		factinvs[i] = modinv(num);
	}
}

ll binom (int n, int k) {
	ll a = facts[n];
	ll b = factinvs[n-k];
	ll c = factinvs[k];
	return ((a*b)%MOD*c)%MOD;
}

