			d = i-wasat[x];
			break;
		} else {
			wasat[x] = i;
		}
	}
	for(int i = 1; i <= n+1; i++) {
		cout << (binom(n+1,i)-binom(n-d,i-1)+MOD)%MOD << "\n";
	}
	return 0;
}

