struct factorials{
    lint sz;std::vector<mint>fact,finv;
    factorials(lint n):sz(n),fact(n),finv(n){
        fact.at(0)=1;
        for(lint i=1;i<n;i++)fact.at(i)=fact.at(i-1)*i;
        finv.at(n-1)=mint{1}/fact.at(n-1);
        for(lint i=n-1;i>=1;i--)finv.at(i-1)=finv.at(i)*i;
    }
    mint operator()(lint x)const{return fact.at(x);}
    mint inv(lint x)const{return finv.at(x);}
    mint binom(lint n,lint k){assert(0<=n&&n<sz);return k<0||n<k?0:fact.at(n)*finv.at(k)*finv.at(n-k);}
