const long long waru = 1000000007;

long long cmbtbl0[1000000] = {};
long long cmbtbl1[1000000] = {};


long long cmb(const int p, const int q, int s) {
  if(s == 0 && cmbtbl0[q] != 0)
    return cmbtbl0[q];
  else if (s==1 && cmbtbl1[q] != 0)
    return cmbtbl1[q];  

  if (p<1 || q<1 || p<q) return 0;

  long long ans = 1;
  for(int i=0; i<q; i++) {
    ans *= (p-i);
    ans /= (i+1);
  }
  if(s==0)
    cmbtbl0[q] = ans;
  if(s==1)
    cmbtbl1[q] = ans;

  return ans;
}

