        cin >> a;
        if (!z[a]) {
            z[a] = i;
        } else {
            l = z[a];
            r = i;
        }
    }
    calc_fd(1ll * n);

    for (int k = 1; k <= n + 1; k++) {
        cout << calc(n, k, l, r) << endl;
    }
    return 0;
}

