template <ll MOD>
class ModLL {
private:
    ll d_;

private:
    void normalize() { d_ = (MOD + d_ % MOD) % MOD; }

public:
    ModLL() {}
    ModLL(ll d) : d_(d % MOD) {}

    ll get() const { return d_; }

    operator ll() { return d_; }

    ModLL& operator=(const ModLL& rhs)
    {
        d_ = rhs.d_;
        normalize();
    }

    ModLL& operator+=(const ModLL& rhs)
    {
        d_ += rhs.d_;
        normalize();
        return *this;
    }

    ModLL& operator-=(const ModLL& rhs)
    {
        d_ -= rhs.d_;
        normalize();
        return *this;
    }

    ModLL& operator*=(const ModLL& rhs)
    {
        d_ *= rhs.d_;
        normalize();
        return *this;
    }

    // assume that rhs isn't divided by MOD and MOD is prime.
    ModLL& operator/=(const ModLL& rhs);
};

template <ll MOD>
ModLL<MOD> pow(ModLL<MOD> a, ModLL<MOD> b)
{
    if (b == 0) return 1;
    if (b == 1) return a;
    if (b % 2 == 0) {
        auto r = pow<MOD>(a, b / 2);
        r *= r;
        return r;
    }
    auto r = pow<MOD>(a, b / 2);
    r *= r;
    r *= a;
    return r;
}

template <ll MOD>
ModLL<MOD>& ModLL<MOD>::operator/=(const ModLL<MOD>& rhs)
{
    /*
       // literally divide
    d_ /= rhs.d_;
    normalize();
    return *this;
    */
    *this *= pow<MOD>(rhs, MOD - 2);
    return *this;
}

