    if( x < 1 ) return 1;
    for( ll i = 1; i <= x; i++){
        ret = mul(ret,i);
    }
    return ret;
}

ll Combi(ll x, ll y){
    if( x < y ) return 0;
    return Div(fact(x), fact(x-y)*fact(y) % MOD);
}

