vector<ll> fac,finv,inv;
void COMinit(int MAX) {
  fac.resize(MAX , 0);
  finv.resize(MAX , 0);
  inv.resize(MAX , 0);
  fac[0] = fac[1] = finv[0] = finv[1] = inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}
// nCk combination 
inline long long COM(int n,int k){
  if(n < k || k < 0) return 0;
  else return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
// nPk permutation
inline long long PER(int n,int k){
  if (n < k || k < 0) return 0;
  else return (fac[n] * finv[n - k]) % MOD;
}
// nHk homogeneous polynomial
inline long long HGP(int n,int k){
  if(n == 0 && k == 0) return 1; //問題依存?
  else if(n < 1 || k < 0) return 0;
  else return fac[n + k - 1] * (finv[k] * finv[n - 1] % MOD) % MOD;
}

void solve(){
  ini(N);
  COMinit(N + 10);
  vi cnt(N + 1);
  vi a(N + 1); in(a);
  each(x,a) cnt[x]++;
  int idxl = 0,idxr = 0;
  rep1(i,N) {
    if(cnt[i] == 2){
      rep(l,N+1)
        if(a[l] == i){
          idxl = l; break;
        }
      repr(r,N+1)
        if(a[r] == i){
          idxr = r; break;
        }
    }
  }
  trc(idxl , idxr);
  int A = idxl , B = N - idxr;
  rep1(k , N + 1){
    ll ans = COM(N+1,k) ;
    ans -= COM(A + B , k - 1);
    out( (ans%MOD+MOD)%MOD );
  }

}

