  ll b=mod,q,s,t;
  ll x0=1,y0=0,x1=0,y1=1;
  while(b>1LL){
    q=a/b;
    s=x1;t=y1;
    x1=x0-x1*q;y1=y0-y1*q;
    x0=s;y0=t;
    a=a%b;swap(a,b);
  }
  while(x1<0LL)x1+=mod;
  return x1;
}

