const long long waru = 1000000007;

ll beki(ll x, ll y){
  if(y == 0)
    return 1;
  else if(y == 1)
    return x;
  else if(y % 2 == 0)
    return beki(x, y/2) * beki(x, y/2) % waru;
  else
    return x * (beki(x, y-1) % waru) % waru;
}

ll kaijo(ll x, ll y){
  if(x <= 1) return 1;
  else return beki(x,y) * kaijo(x-1, y) % waru;
}

ll kumiawase(ll x, ll y){
  if(x==y) return 1;
  else if(x== 0 || x<y || y<0) return 0;
  else  return (((kaijo(x,1) % waru) * (kaijo(x-y, waru-2) % waru)) % waru) * (kaijo(y, waru-2) % waru) % waru;
}


