void calc(vector<vector<long long int> > &v) {
  for (int i = 0; i < v.size(); i++) {
    v[i][0] = 1;
    v[i][i] = 1;
  }
  for (int k = 1; k < v.size(); k++) {
    for (int j = 1; j < k; j++) {
      v[k][j] = (v[k - 1][j - 1] + v[k - 1][j]);
    }
  }
}

long long comb(int n, int k) {
  vector<vector<long long int> > v(n + 1, vector<long long int>(n + 1, 0));
  calc(v);
