ll modinv(ll a){
  ll b=mod,q;
  ll x0=1,y0=0,x1=0,y1=1;
  while(b>1LL){
    q=a/b;
    x0-=x1*q;y0-=y1*q;
    swap(x0,x1);swap(y0,y1);
    a=a%b;swap(a,b);
  }
  while(x1<0LL)x1+=mod;
  x1%=mod;
  return x1;
}

