ll mpow(ll a, ll b) {
	ll res = 1;
	a %= mod;
	while (b) {
		if (b & 1) res = res * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return res;
}

#define N 100010
int fac[N], finv[N];
void factorization() {
	fac[0] = finv[0] = 1;
	rep(i,1,N)fac[i] = (ll)fac[i - 1] * i % mod;
	finv[N - 1] = mpow(fac[N - 1], mod - 2);
	for (int i = N - 2; i; --i) finv[i] = (ll)finv[i + 1] * (i + 1) % mod;
}
int nCr(int n, int m){
	return (ll)((ll)fac[n] * finv[m] % mod)* finv[n - m] % mod;
}

