    a.resize(n + 1);
    rep(i, n + 1) cin >> a[i];

    // 1種類の数字だけ重複がある
    combination comb(1e6);

    // 2項ある数を求める
    map<int, int> mp;
    int left = -1, right = -1;
    rep(i, n + 1) {
        if (mp.count(a[i])) {
            left = mp[a[i]];
            right = i;
            break;
        }
        mp[a[i]] = i;
    }
    // cout << left << " " << right << endl;


    for (int i = 1; i <= n + 1; i++) {
        mint ans = comb(n + 1, i);
        if (i == 1) {
            ans -= 1;
        } else if (i != n + 1) {
            // 重複を取り除く
            mint tmp = comb(left + n - right, i - 1);
            ans -= tmp;
        }
        cout << ans << endl;
    }
}

