/*-------------------------------------------------*/
long long mod_inv(long long a, long long mod = MOD) {
  a %= mod;
  if (__gcd(a, mod) != 1) return -1;
  long long b = mod, x = 1, y = 0;
  while (b > 0) {
    long long tmp = a / b;
    a -= tmp * b;
    swap(a, b);
    x -= tmp * y;
    swap(x, y);
  }
  x %= mod;
  if (x < 0) x += mod;
  return x;
}

struct nCk {
  vector<long long> fact;

  nCk(int val = 10000000, long long mod = MOD) : mod(mod) {
    fact.resize(val + 1);
    fact[0] = 1;
    FOR(i, 1, val + 1) fact[i] = fact[i - 1] * i % mod;
    fact_inv.resize(val + 1);
    fact_inv[val] = mod_inv(fact[val], mod);
    for (int i = val; i > 0; --i) fact_inv[i - 1] = fact_inv[i] * i % mod;
  }

  long long query(int n, int k) {
    if (n < 0 || n < k || k < 0) return 0;
    return fact[n] * fact_inv[k] % mod * fact_inv[n - k] % mod;
  }

private:
  long long mod;
  vector<long long> fact_inv;
};

