int mark[M],t,k,n;
int P=1e9+7;
int F[M];
void Init(){
	F[0]=1;
	for(int i=1;i<=n;i++)F[i]=1LL*i*F[i-1]%P;
}
int fast(int x){
	int n=P-2;
	long long res=1,a=x;
	while(n){
		if(n&1)res=(res*a)%P;
		a=a*a%P;
		n>>=1;
	}
	return res;
}
int C(int n,int m){
	if(n<0)return 0;
	if(m==0)return 1;
	if(n<m)return 0; 
	return F[n]*1LL*fast(F[n-m])%P*fast(F[m])%P;
}
void Add(int &x,int y){
	x+=y;
	if(x>=P)x-=P;
	if(x<0)x+=P;
}
int solve(int m){
	int ans=0;
	Add(ans,C(n-2,m));//0
	Add(ans,C(n-2,m-1)*2%P);
	Add(ans,-C(t-1+n-k,m-1));
	if(m>=2)Add(ans,C(n-2,m-2));//2
	return ans;
}
