long long int power(long long int n, long long int p){
	if (p == 0)
		return 1;


	if (p % 2 == 0)
		return power(n, p/2) * power(n, p/2) % mod;
	else
		return n * power(n, p-1) % mod;
}
long long int inverse(long long int n){
	return power(n, mod-2) % mod;
}


