long long int my_pow(long long int a, long long int k) {
    if (k == 0) return 1;
    long long int res = my_pow(a, k / 2);
    res = res * res % MOD;
    if (k & 1) res = res * a % MOD;
    return res;
}

long long int comb(long long int n,long long int r){

    if(n < r){
        return 0;
    }

    if(r == 0){
        return 1;
    }

    return (factorial[n] * reciprocal[n-r] % MOD * reciprocal[r]) % MOD;

}

