ll mod_pow(ll x,ll n,ll mod){
    ll ret=1;
    while(n>0){
        if(n&1){
            ret=ret*x%mod;
        }
        x=x*x%mod;
        n>>=1;
    }
    return ret;
}
ll f[100010],fr[100010];
ll ncr(ll n,ll r){
    if(n<r){
        return 0;
    }
    return f[n]*fr[r]%MOD*fr[n-r]%MOD;
}
int main() {   
    ll n;
    cin>>n;
    ll a[100001],b[100001];
    for(int i=1;i<=n+1;i++){
        cin>>a[i];
        b[i-1]=a[i];
    }
    sort(b,b+n+1);
    ll s;
    for(int i=0;i<n;i++){
        if(b[i]==b[i+1]){
            s=b[i+1];
            break;
        }
    }
    ll l=-1;
    ll r=0;
    for(int i=1;i<=n+1;i++){
        if(a[i]==s){
            if(l==-1){
                l=i;
            }else{
                r=i;
                break;
            }
        }
    }
    f[0]=1;
    for(int i=1;i<=n+2;i++){
        f[i]=f[i-1]*i%MOD;
    }
    fr[n+2]=mod_pow(f[n+2],MOD-2,MOD);
    for(int i=n+1;i>=0;i--){
        fr[i]=fr[i+1]*(i+1)%MOD;
    }
    for(ll k=1;k<=n+1;k++){
        ll ans=ncr(n+1,k)-ncr(l+n-r,k-1);
        cout<<ans<<endl;
    }
    getchar();
    getchar();
}

