const u64 MAX_N = 100000;
u64 N, x, y;
u64 a[MAX_N+1], fact[MAX_N+2], inv[MAX_N+2];

u64 powMOD(u64 a, u64 b) {
    u64 x, ret;
    x = a;
    ret = 1;
    while(b) {
        if(b&1) {
            ret = ret * x % MOD;
        }
        x = x * x % MOD;
        b >>= 1;
    }
    return ret % MOD;
}

u64 C(u64 n, u64 m) {
    if(m == 0) {
        return 1;
    }
    return (fact[n] * inv[n-m] % MOD) * inv[m] % MOD;
}

u64 solve(u64 n) {
    u64 ans = C(N+1, n);
    if(n <= x+1 + N+1 - (y+1)) {
        ans -= C(x+1 + N+1 - (y+1) - 1, n - 1);
    }
    return ans;
}

pair<u64, u64> search() {
    int used[MAX_N];
    memset(used, -1, sizeof(used));
    REP(i, N+1) {
        if(used[a[i]-1] != -1) {
            return MP(used[a[i]-1], i);
        }
        used[a[i]-1] = i;
    }
}

int main() {
    IN(N);
    REP(i, N+1) IN(a[i]);
    auto xy = search();
