    REP(i, N+2) {
        fact[i+1] = (i+1) * fact[i] % MOD;
        inv[i+1] = powMOD(fact[i+1], MOD-2);
    }
    REP(i, N+1) {
        cout << solve(i+1) << endl;
    }
    return 0;
}

