int gyakugen(int a, int p = bigmod, int b = -1) {
    if (b < 0) b = p - 2;  //int gyakugen(int a, int p, int b = p - 2とできなかったため。)
    if (b == 0) return 1;
    else if (b % 2 == 0) {
        int d = gyakugen(a, p, b / 2);
        return mul(d, d);
    } else {
        return mul(a, gyakugen(a, p, b - 1));
    }
}

