//x,yがax+by=gcd(a,b)の解になる
ll extgcd(ll a, ll b, ll& x, ll& y) {
	ll d = a;
	if (b != 0) {
		d = extgcd(b, a%b, y, x);
		y -= (a / b)*x;
	}
	else {
		x = 1; y = 0;
	}
	return d;
}
//aの逆元を求める
ll mod_inverse(ll a) {
	ll x, y;
	extgcd(a, MOD, x, y);
	return (MOD + x % MOD) % MOD;
}
//y個からxを選ぶ
ll count(int x, int y) {
	if (x > y)return 0;
	ll res = p[y];
	(res *= mod_inverse(p[x])) %= MOD;
	(res *= mod_inverse(p[y - x])) %= MOD;
	return res;
}
