int C(int n, int m) {
    if (n < m || n <= 0) {
        return 0;
    }
    long long tmp = 1;
    long long tmp2 = 1;
    for (int i = 0; i < min(n-m, m); i++) {
        tmp *= n;
        n--;
        tmp2 *= i+1;
    }
    return (tmp/tmp2)%mod;
}

