long divmod=1000000007;
long memofuncC[1000000];

/*組み合わせ関数*/
long funcC(long n, long m){
if(m==0) return 1;
if(n==0) return 1;
if(n==m) return 1;
if(memofuncC[(n)*(n+1)/2+m]>=0) return memofuncC[(n)*(n+1)/2+m];
memofuncC[(n)*(n+1)/2+m] = (funcC(n-1,m-1)+funcC(n-1,m) ) % divmod;
return memofuncC[(n)*(n+1)/2+m];
}

int main(){
