if(k==1){printf("%ld\n",n);}
if(k==n+1){printf("%d\n",1);}
if(k>1 && k<n+1){
num = 0;
if(n+1-2>=k) num += funcC(n+1-2,k);  /*含まない*/
if(n+1-2>=k-2) num += funcC(n+1-2,k-2); /*両方含む*/
if(n+1-middle-2>=k-1) num += funcC(n+1-middle-2,k-1); /*片方とミドルなし*/
for(m=1;m<k;m++){
if(middle>=m && n+1-middle-2>=k-m-1) num += funcC(middle,m)*funcC(n+1-middle-2,k-m-1)*2 ; /*ミドルにm個でどちらか片方を選ぶ*/
}
