ll pow(int a, int b) {
	if (!b) {
		return 1;
	}
	else if (b % 2 == 0) {
		ll d = pow(a, b/2);
		return (d * d)%MOD;
	}
	else {
		return (a*pow(a, b-1))%MOD;
	}
}

ll factional(int a){
    if(fact[a] != -1) return ll(fact[a]);
    ll ret = 1;
    REP(i, a) ret = ret * (i+1) % MOD;
    fact[a] = ret;
    return ret;
}

ll inv(int a){
    if(fact_inv[a] != -1) return ll(fact_inv[a]);
    fact_inv[a] = pow(a, int(MOD-2));
    return ll(fact_inv[a]);
}

ll comb(int a, int b){
    if(a < b) return 0;
    ll ret = factional(a);
    REP(i, b) ret = ret * inv(i+1) % MOD;
    REP(i, a-b) ret = ret * inv(i+1) % MOD;
    return ret;
}

