ll nCr(int n, int r) {
	if(r == 0) return 1;
	ll a = 1, b= 1;
	rep(i, r) a = a * (n - i) % MOD;
	FOR(i, 1, r + 1) b = b * i % MOD;
	ll ans = 1, num = MOD - 2;
	while(num != 0) {
		if(num % 2) ans = ans * b % MOD;
		b = b * b % MOD;
		num /= 2;
	}
	return a * ans % MOD;
}

