/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
vl a;
ll memo[3][MAX_N];
mll cnt;

void solve(){
    a = vl(n + 1);
    pl pos = mp(-1, -1);
    rep(i, n + 1) {in1(a[i]); cnt[a[i]]++;}

    items(kv, cnt){
        ll hoge = 0;
        if (kv.e2 == 2) rep(i, n + 1){
            if (a[i] == kv.e1 && !hoge) {pos.e1 = i; hoge++;}
            else if (a[i] == kv.e1) {pos.e2 = i; break;}
        }
    }

    ll dx = n - 1 - (pos.e2 - pos.e1 - 1);
    rep(i, n + 1) memo[0][i] = combination(dx, i);
    rep(i, n + 1) memo[1][i] = combination(n - 1, i);
    rep(i, n + 1) memo[2][i] = combination(n, i);

    prl(n);
    For(i, 2, n + 1){
        answer = 0;
        // 2C1 + 2C3 + 2C2 + 1C2
        // when choosing 2 multiple number 
        answer += memo[1][i - 2];
        // when choosing 0 multiple number 
        answer += memo[1][i];
        // when choosing 1 multiple number
        answer += memo[1][i - 1] * 2;
        if (dx >= i - 1) answer -= memo[0][i - 1];
        prl(answer % MOD);
    }
    prl(1);
}

int main(void){
    in1(n);
    // assert(n <= 999);
    solve();

    return 0;
}

