int elePow(int a, int b) {
	int num = 1;
	while(b != 0) {
		if(b & 1) num = 1ll * num * a % MOD;
		b /= 2;
		a = 1ll * a * a % MOD;
	}
	return num;
}

int nCr(int n, int r) {
	if(r > n) return 0;
	if(r == 0) return 1;
	int a = fact[n], b = 1ll * fact[r] * fact[n - r] % MOD;
	int res = 1ll * a * elePow(b, MOD - 2) % MOD;
	return res;
}

