const ll MAXN = 200005;

// fac: n!のmod
// finv: 1/n!のmod
// inv: 1/nのmod
vll fac(MAXN), finv(MAXN), inv(MAXN);

void COMinit() {
  fac.at(0) = fac.at(1) = 1;
  finv.at(0) = finv.at(1) = 1;
  inv.at(1) = 1;
  rep(i, 2, MAXN) {
    fac.at(i) = fac.at(i-1) * i % MOD;
    inv.at(i) = MOD - inv.at(MOD%i) * (MOD / i) % MOD;
    finv.at(i) = finv.at(i-1) * inv.at(i) % MOD;
  }
}

ll COM(ll n, ll k) {
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac.at(n) * (finv.at(k) * finv.at(n-k) % MOD) % MOD;
}

int main() {
  ll n; cin >> n;
  COMinit();
  vll use(n, -1), a(n+1);;
  ll li, ri;
  REP(i, n+1) {
