long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}


void factorial(ll n){
    for(int i = 0;i <= n;i++){
        if(i == 0 || i == 1){
            fact[i] = 1;
        }else{
            fact[i] = (fact[i - 1] * i) % MOD;
        }
    }

    return;
}

