const ll mod = 1000000007LL;

// a - bをmodをとりつつ計算する.
ll submod(ll a, ll b) {
    return a > b ? (a - b) % mod : ((a - b) % mod + mod);
}

// x^nをmodをとりつつ求める
ll powmod(ll x, ll n) {
    if (n == 0LL) return 1LL;
    x %= mod;
    if (n % 2LL == 0) {
        return powmod((x * x) % mod, n / 2LL);
    }
    else {
        return (x * powmod((x * x) % mod, n / 2LL)) % mod;
    }
}

// xの逆元を求める.
ll modinv(ll x) {
    return powmod(x, mod - 2LL);
}

ll mfac[200000+1];

void initFac() {
    mfac[0] = mfac[1] = 1LL;
    for (int i = 2; i <= 200000; ++i) {
        mfac[i] = mfac[i - 1] * i % mod;
    }
}

// nPkを求める
ll perm(ll n, ll k) {
    if (k > n) throw "k must be less or equal than n";
    return mfac[n] * modinv(mfac[n - k]) % mod;
}

// nCkを求める
ll comb(ll n, ll k) {
    if (k > n) return 0LL;
    else return mfac[n] * modinv(mfac[k] * mfac[n - k]) % mod;
}

