        cout << 1 << endl;
        cout << 1 << endl;
    }
    else {
        cout << n << endl;
        for (ll k = 2; k <= n + 1; ++k) {
            ll ans = 0;
            ans += comb(n - 1LL, k);
            ans += comb(n - 1LL, k - 2LL);
            ans %= mod;
            ans += (2 * submod(comb(n - 1LL, k - 1LL), comb(n + 1LL - L, k - 1LL))) % mod;
            ans %= mod;
            ans += comb(n + 1LL - L, k - 1LL);
            ans %= mod;
            cout << ans << endl;
        }
    }
