    if (a[i] == a[second]) {
      first = i;
      break;
    }
  }
  for (int i=1;i<=n_+1;i++) {
    ll ans = (nCr(n_ + 1, i) - nCr(first+n_-second, i-1) + MOD) % MOD;
    cout << ans << endl;
  }
}

