long long m = 1000000007;

long long modpow(long long a, long long n){
    long long r = 1;

    while(n){
        if(n & 1){
            r = (r * a) % m;
        }
        a = (a * a) % m;
        n = n >> 1;
    }

    return r;
}

long long modinv(long a){
    return modpow(a, m-2);
}

