#define NUM 100010

unsigned long long calc_casen(int n, int r, int dup) {
  int i, j, nn;
  unsigned long long* a =
      (unsigned long long*)calloc(n, sizeof(unsigned long long));
  unsigned long long retv;
  nn = (dup) ? (n + r - 1) : n;
  if (nn - r < r) r = nn - r;
  if (r == 0) return 1;
  if (r == 1) return nn;
  for (i = 1; i < r; i++) a[i] = i + 2;
  for (i = 3; i <= nn - r + 1; i++) {
    a[0] = i;
    for (j = 1; j < r; j++) a[j] += a[j - 1];
  }
  retv = a[r - 1];
  free(a);
  return retv;
}

unsigned long long int calc_combi(int n, int r) {
  if (r > n) {
    return 0;
  } else {
    return calc_casen(n, r, 0);
  }
}

int main() {
  int i, j;
  int *x = (int*)malloc(sizeof(int)*NUM);
  int n;
  int temp;
  int between;
  unsigned long long int answer;

  for (i = 0; i < NUM; i++) {
    x[i] = -1;
  }

  scanf("%d", &n);
  for (i = 1; i <= n + 1; i++) {
    scanf(" %d", &temp);
    if (x[temp] == -1) {
      x[temp] = i;
    } else {
      between = i - x[temp] - 1;
      break;
    }
  }

  if (n == 1) {
    printf("1\n");
    printf("1\n");
  } else {
    printf("%d\n", n);
    for (i = 2; i <= n + 1; i++) {
      answer = calc_combi(n - 1, i) + 2 * calc_combi(n - 1, i - 1) - calc_combi(n - 1 - between, i - 1) + calc_combi(n - 1, i - 2);
      printf("%llu\n", answer);
      fflush(stdout);
    }
  }
  return 0;
}

