{
	return (a+mod-b)%mod;
}
long long binpow(long long a, long long p){
  bp[0] = 1;
  bp[1] = a;
  for(int i = 2; i < 40; ++i){
    bp[i] = (bp[i - 1] * bp[i - 1]) % mod;
  }
  int d = 1;
  long long res = 1;

  while(p){
    if(p & 1){
      res = (res * bp[d]) % mod;
    }
    d++;
    p = p >> 1;
  }

  return res;
}
long long fc[100001];
long long divi(long long a,long long b)
{
	return mul(a, binpow(b, mod-2));
}
void calcfc()
{
	int i;
	fc[0]=1;
	fc[1]=1;
	for(i=1;i<=100000;i++)
		fc[i+1]=fc[i]*(i+1)%mod;
}
long long cmb(int n,int r)
{
	return divi(fc[n],mul(fc[r],fc[n-r]));
}

