unsigned long long calc_casen(int n, int r, int dup) {
  int i, j, nn;
  unsigned long long* a =
      (unsigned long long*)calloc(n, sizeof(unsigned long long));
  unsigned long long retv;
  nn = (dup) ? (n + r - 1) : n;
