  for (i = 1; i < r; i++) a[i] = i + 2;
  for (i = 3; i <= nn - r + 1; i++) {
    a[0] = i;
    for (j = 1; j < r; j++) a[j] += a[j - 1];
  }
  retv = a[r - 1];
  free(a);
  return retv;
}

