unsigned long long calc_combi(int n, int r) {
  int i;
  unsigned long long int answer;
  unsigned long long int bunshi = 1;
  unsigned long long int bunbo = 1;
  unsigned long long int temp = 1;

  if (r > n) {
    return 0;
  }

  if (n-r > r){
    r = n - r;
  }
  if (r == 0) {
    return 1;
  } else {
    for (i = 1; i <= r; i++) {
      bunbo = (bunbo * i) % TEISUU;
