void solve(void){
    int n, c;
    scanf("%d\n", &n);
    c = n+1;

    int as[c], ac[c];
    rep (c, i) {
        scanf("%d ", &as[i]);
        ac[i] = as[i];
    }

    long long nck[c+1][c+1];
    rep (c+1 ,i){
        nck[i][0] = 1;
        nck[i][i] = 1;
    }
    for (int i = 1; i <= c; i++) {
        for (int j = 1; j < i; j++) {
            nck[i][j] = nck[i-1][j] + nck[i-1][j-1];
            nck[i][j] %= MOD;
        }
