long long modPow(int x, int n)
{
  if(n == 0) return (1);
  long long ret = modPow(x, n / 2);
  ret *= ret;
  ret %= mod;
  if(n % 2 == 1) {
    ret *= x;
    ret %= mod;
  }
  return (ret);
}

long long modInv(int p)
{
  return (modPow(p, mod - 2));
}

long long modCombination(int p, int q)
{
  if(q < 0 || p < q) return (0);
  return (fact[p] * rfact[q] % mod * rfact[p - q] % mod);
}

