int modPow(int x, int n)
{
  int ret;
  if(n == 0) return (1);
  ret = modPow(x, n / 2);
  ret = 1LL * ret * ret % mod;
  if(n % 2 == 1) {
    ret = 1LL * ret * x % mod;
  }
  return (ret);
}

int modInv(int p)
{
  return (modPow(p, mod - 2));
}

int modCombination(int p, int q)
{
  if(q < 0 || p < q) return (0);
  return (1LL * fact[p] * rfact[q] % mod * rfact[p - q] % mod);
}

