#define NUM 100010
#define TEISUU 1000000007

unsigned long long expo(unsigned long long x, unsigned long long n) {
  unsigned long long res = 1;

  while (n) {
    if (n & 1ULL) {
      res = (res * x) % TEISUU;
    }
    x = (x * x) % TEISUU;
    n >>= 1ULL;
  }

  return (res % TEISUU);
}

unsigned long long calc_combi(int n, int r) {
  int i;
  unsigned long long int bunshi = 1;
  unsigned long long int bunbo = 1;

  if (r > n) {
    return 0;
  }

  if (n - r > r) {
    r = n - r;
  }
  if (r == 0) {
    return 1;
  } else {
    for (i = 1; i <= r; i++) {
      bunbo = bunbo * i;
      bunshi = (bunshi * (n - r + i));
      if (bunbo >> 10) {
        bunbo = bunbo % TEISUU;
      }
      if (bunshi >> 10) {
        bunshi = bunshi % TEISUU;
      }
    }
    bunbo = expo(bunbo, TEISUU - 2);
    return (bunbo * bunshi) % TEISUU;
  }
}

