    fun comb(n: Int, k: Int, c: Long = 1): Long {
        if (k == 0) return 1
        if (k == 1) return n.toLong() % mod
        if (k == n) return 1

        if (n / 2 > k) {
            var a = comb(n - 1, k) % mod
            a += comb(n - 1, k - 1) % mod
            return a % mod
        } else {
            var a = comb(n - 1, n - k) % mod
            a += comb(n - 1, n - k - 1) % mod
            return a % mod
        }
    }
