const val MOD = 1000000007L

fun calcBinomials(n: Int, mod: Long): LongArray {
    // [nC0, nC1, ... nCn]
    if (n == 0) return LongArray(1) { 1L }
    val arr = LongArray(n + 1)
    arr[0] = 1L
    arr[1] = n.toLong()
    for (i in 2..n) {
        arr[i] = (((arr[i - 1] * (n - i + 1)) % mod) * (i.modInv(mod))) % mod
    }
    return arr
}

fun solve(n: Int, a: IntArray) {
    fun getLeftRight(): Pair<Int, Int> {
        val dict = mutableMapOf<Int, Int>()
        for ((i, num) in a.withIndex()) {
            if (dict[num] != null) {
                return dict[num]!! to n - i
            } else {
                dict[num] = i
            }
        }
        return 0 to 0
    }
    val (left, right) = getLeftRight()
    val restBinomial = calcBinomials(left + right, MOD)
    val allBinomial = calcBinomials(n + 1, MOD)
    allBinomial
        .drop(1)
        .mapIndexed{ index, value -> value - restBinomial.getOrElse(index){ 0L } }
        .joinToString(separator="\n")
        .let{ println(it) }
    return
}

fun Long.modPow(x: Long, mod: Long): Long {
    // this ^ x % mod
    tailrec fun binModPow(a: Long, exp: Long): Long = when (exp) {
        // a ^ (2^(exp)) % mod
        0L -> a % mod
        else -> binModPow(a * a % mod, exp - 1)
    }
    return (0..63).asSequence()
        .map { (x shr it) and 1 }
        .withIndex()
        .filter { it.value > 0 }
        .map { binModPow(this, it.index.toLong()) }
        .reduce { a, b -> a * b % mod }
}

// 1 / x % mod (x ⊥ mod)
fun Long.modInv(mod: Long): Long = this.modPow(mod - 2, mod)
fun Int.modInv(mod: Long) = toLong().modInv(mod)

fun binomialMod(n: Int, k: Int, mod: Long): Long = when (k) {
    // nCk % mod
    0, n -> 1L
    else -> {
        val numer = (n downTo n - k + 1)
            .map { it.toLong() }
            .reduce { a, b -> (a * b) % mod }
        val denom = (1..k)
            .map { it.toLong() }
            .reduce { a, b -> (a * b) % mod }
        (numer * denom.modInv(mod)) % mod
    }
}

