fun solve(n: Int, a: IntArray) {
    fun calcModInvs(num: Int, mod: Long): LongArray {
        val invs = LongArray(num + 1)
        invs[1] = 1L
        for (i in 2L..num.toLong()) {
            invs[i.toInt()] = Math.floorMod((-(mod / i) * invs[(mod % i).toInt()]), mod)
        }
        return invs
    }
    val invs = calcModInvs(n + 2, MOD)
    fun calcBinomials(num: Int, mod: Long): LongArray {
