            arr[i] = (((arr[i - 1] * (num - i + 1)) % mod) * invs[i]) % mod
        }
        return arr
    }
    val dup = a.sum() - n * (n + 1) / 2
    val rest = a.indexOfFirst { it == dup } + n - a.indexOfLast { it == dup }
    val restBinomial = calcBinomials(rest, MOD)
    val allBinomial = calcBinomials(n + 1, MOD)
    for (i in 0..rest) { allBinomial[i + 1] -= restBinomial[i] }
    allBinomial
        .drop(1)
        .joinToString(separator = "\n")
