val pw = PrintWriter(System.out)
val MOD: Long = (1e+9 + 7).toLong()

class ModCombWithMod(val n: Int, val mod: Long) {
	val factorials = Array(n+1) { 0L }.apply {
		this[0] = 1L
		this[1] = 1L
	}
	val inverses = Array(n+1) { 0L }.apply {
		this[0] = 1L
		this[1] = 1L
	}
	val factorialInverses = Array(n+1) { 0L }.apply {
		this[0] = 1L
		this[1] = 1L
	}

	init {
		for(i in 2 .. n) {
			factorials[i] = (factorials[i-1] * i.toLong() % mod)
			inverses[i] = (mod - inverses[mod.toInt() % i] * (mod / i.toLong()) % mod)
			factorialInverses[i] = (factorialInverses[i-1] * inverses[i] % mod)
		}

	}

	fun comb(n: Int, k: Int): Long = 
		if(k < 0 || k > n) 0L
		else 
			factorials[n] % mod * (factorialInverses[k] * factorialInverses[n-k] % mod) % mod
}

fun main(args: Array<String>) {
	val n = readInt()	
	val aList = readListOfInt()

	val comb = ModCombWithMod(n+2, MOD)

	var aGroup = aList.groupBy { it } 
	val target = aGroup.filter { it.value.size == 2 }.keys.first()
	val tl = aList.indexOf(target) + 1
	val tr = aList.lastIndexOf(target) + 1

	val ansArr = Array(n+1) { 0L }
	val size = n + 1
	for(k in 1 .. size) {
		val a1 = comb.comb(size, k)
		val a2 = comb.comb(tl-1 + size - tr, k-1)
		ansArr[k-1] = (a1 - a2) % MOD 
	}
	ansArr.forEach { println(it) }

	pw.flush()
}


