        int s=-1,t=-1;
        for(int i=0;i<=n;i++){
            a[i]=fsc.nextInt()-1;
            if(rev[a[i]]<0) rev[a[i]]=i;
            else{
                s=rev[a[i]];
                t=i;
            }
        }
        fsc.close();
        comb=new long[n+2][n+2];
        long[] ans=new long[n+1];
        for(int k=1;k<=n+1;k++){
            System.out.println(comb(n+1, k)-comb(n-t+s, k-1));
        }
    }
    static long[][] comb;
    public static long modinv(long a){
        long b=MOD, u=1, v=0;
        long tmp;
        while(b>=1){
            long t=a/b;
            a-=t*b;
            tmp=a; a=b; b=tmp;
            u-=t*v;
            tmp=u; u=v; v=tmp;
        }
        u%=MOD;
        return u>=0?u:u+MOD;
    }
    public static long comb(long n, long r){
        if(n<r) return 0;
        if(comb[(int)n][(int)r]>0) return comb[(int)n][(int)r];
        r=Math.min(r, n-r);
        long res=1;
        for(int d=1;d<=r;d++){
            res*=n;
            res%=MOD;
            n--;
            res*=modinv(d);
            res%=MOD;
        }
        return comb[(int)n][(int)r]=res;
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.util.*;
public class Main {
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int numOfNumber = scanner.nextInt() + 1;
        int[] numbers = new int[numOfNumber];
        for (int i = 0; i < numOfNumber; i++) {
            numbers[i] = scanner.nextInt();
        }
        HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();
        for (int i = 0; i < numOfNumber; i++) {
            if (map.containsKey(numbers[i]) == false) {
                map.put(numbers[i], 1);
            }
            else {
                map.put(numbers[i], map.get(numbers[i]) + 1);
            }
        }
        int dup = 0;
        for (int key : map.keySet()) {
            if (map.get(key) > 1) {
                dup = key;
                break;
            }
        }
        int minIndex = -1;
        int maxIndex = -1;
        for (int i = 0; i < numOfNumber; i++) {
            if (numbers[i] == dup) {
                if (minIndex >= 0) {
                    maxIndex = i;
                }
                else {
                    minIndex = i;
                }
            }
        }
        int d = maxIndex - minIndex - 1;
        int[][] dp = new int[numOfNumber + 1][numOfNumber + 1];
        for (int i = 0; i < dp.length; i++) {
            for (int j = 0; j < dp.length; j++) {

                if (j == 0 || i == j) {
                    dp[i][j] = 1;
                }
                else if (i > 0) {
                    dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1];
                }
            }
        }
        for (int k = 1; k <= numOfNumber; k++) {
            int cof1 = dp[numOfNumber][k];
            int cof2 = numOfNumber - d - 2 >= 0 ? dp[numOfNumber - d - 2][k - 1] : 0;
            System.out.println(cof1 - cof2);
        }
    }
}

import java.util.*;

public class Main {
    static final long DIV = 1000000007;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] pos = new int[n];
        int[] dpos = new int[2];
        Arrays.fill(pos, -1);
        for(int i=0; i<n+1; i++){
            int a = sc.nextInt() - 1;
            if(pos[a]<0){
                pos[a] = i;
            }else{
                dpos[0] = pos[a];
                dpos[1] = i;
            }
        }
        sc.close();

        long nleft = dpos[0];
        long nright = n - dpos[1];
        long[] fact = new long[n+1];
        long[] ifact = new long[n+1];

        fact[0] = 1;
        ifact[0] = 1;
        for(int i=1; i<n+1; i++){
            fact[i] = (fact[i-1] * (i+1)) % DIV;
            ifact[i] = inverseElement(fact[i], DIV);
        }
        long[] lcomb = new long[(int)nleft+1];
        long[] rcomb = new long[(int)nright+1];
        for(int i=0; i<nleft+1; i++){
            lcomb[i] = comb(nleft, i, fact, ifact);
        }
        for(int i=0; i<nright+1; i++){
            rcomb[i] = comb(nright, i, fact, ifact);
        }


        for(int i=0; i<n+1; i++){
            long ans = comb(n+1, i+1, fact, ifact);
            for(int j=0; j<i+1; j++){
                if(j > nleft || (i-j) > nright) continue;
                ans -= lcomb[j] * rcomb[i-j];
                if(ans < 0) ans = (ans + (DIV*DIV))%DIV;
            }
            System.out.println(ans);
        }
    }

    static long comb(long n, long k, long[] fact, long[] ifact){
        if(n <= 0 || k <= 0 || n-k <= 0) return 1;
        return (((fact[(int)n-1] * ifact[(int)n-(int)k-1])%DIV) * ifact[(int)k-1])%DIV;
    }

    public static long inverseElement(long a, long n){
        long b = n, u=1, v=0;
        while(b > 0) {
            long t = a/b;
            a -= t*b;
            u -= t*v;
            //swap
            t = a;
            a = b;
            b = t;
            t = u;
            u = v;
            v = t;
        }
        u = u % n;
        if(u < 0) u += n;
        return u;
    }
}

