public class Main{
	static Scanner s=new Scanner(System.in);

	void solve(){
		int n=gInt();
		int[]a=INTS(n+1).map(i->i-1).toArray();
		int doubled=0;
		{
			boolean[]f=new boolean[n];
			for(int i:a) {
				if(f[i]) {
					doubled=i;
					break;
				}
				f[i]=true;
			}
		}
		int l=0,c=0,r=0;
		{
			int i=0;
			for(;i<n+1;++i) {
				if(a[i]!=doubled)
					++l;
				else
					break;
			}
			for(++i;i<n+1;++i) {
				if(a[i]!=doubled)
					++c;
				else
					break;
			}
			for(++i;i<n+1;++i) {
				if(a[i]!=doubled)
					++r;
				else
					break;
			}
		}
		System.err.println(l+" "+c+" "+r);
		for(int i=1;i<=n+1;++i) {
			System.out.println(f(i,l,c,r));
		}
	}
	private long f(int i,int l,int c,int r){
		if(i==1)return l+c+r+1;

		long res=0;
		//- - -
		res+=ncr(l+c+r,i);
		res%=MOD;
		//-*- -
		//- -*-
		res+=ncr(l+c+r,i-1)*2;
		//-*
		//   *-
		res-=ncr(l,i-1);
		res-=ncr(r,i-1);
		res%=MOD;
		//-*-*-
		res+=ncr(l+c+r,i-2);
		res%=MOD;
		return res;
	}
	private static final int MOD=1000000007;
	private long ncr(int n,int r){
		if(n<r)
			return 0;
		long res=1;
		int a=Math.min(n-r,r);
		int b=Math.max(n-r,r);
		for(int i=1;i<=a;++i) {
			res*=b+i;
			res/=i;
			res%=MOD;
		}
		return res;
	}

	public static void main(String[] $){
		new Main().solve();
	}

