		int firstPosition = 0;
		int secondPosition = 0;
		for(int i = 0; i < n + 1; i++){
			if(hasOne[a[i]]){
				hasTwo[a[i]] = true;
				firstPosition = position[a[i]];
				secondPosition = i;
			}else{
				position[a[i]] = i;
				hasOne[a[i]] = true;
			}
		}

		int x = firstPosition + (n + 1 - secondPosition - 1);

		long comb[] = new long[n + 2];
		comb[0] = 1;
		for(int i = 1; i <= n + 1; i++){
			comb[i] = 1;
			if(i >= (n + 1) / 2 + 1){
				comb[i] = comb[(n + 1) - i];
			}else{
				comb[i] *= comb[i - 1] * (n + 1 - i + 1) / i;
				comb[i] = comb[i] % 1000000007;
			}
		}

		long combX[] = new long[x + 1];
		combX[0] = 1;
		for(int i = 1; i <= x; i++){
			combX[i] = 1;
			if(i >= x / 2 + 1){
				combX[i] = combX[x - i];
			}else{
				combX[i] *= comb[i - 1] * (x - i + 1) / i;
				combX[i] = combX[i] % 1000000007;
			}
		}

		long[] ans = new long[n + 2];
		for(int i = 1; i <= n + 1; i++){
			if(i - 1 <= x){
				ans[i] = comb[i] - combX[i - 1];
				if(ans[i] < 0){
