    static class TaskD {
        private static long d = (long) 1000000007;
        private static long[] memo;

        private static long ncr(int n, int r) {
            return r == 0 ? 1 : memo[n] / memo[r];
        }

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int[] count = new int[n + 1];
            int twiceI1 = 0;
            int twiceI2 = 0;
            for (int i = 0; i < n + 1; i++) {
                int cn = in.nextInt();
                if (count[cn] > 0) {
                    twiceI1 = count[cn];
                    twiceI2 = i;
                    break;
                }
                count[cn] = i + 1;
            }

            memo = new long[n + 1];
            long cn = 1;
            memo[1] = 1;
            for (long i = 2; i <= n; i++) {
                cn *= i;
                if (cn >= d)
                    cn -= d;
                memo[(int) i] = cn;
            }

            out.println(n);
            for (int i = 2; i <= n; i++) {
                long ans = ncr(n - 1, i);
                ans += 2 * ncr(n - 1, i - 1);
                ans -= ncr(n - 1 - (twiceI2 - twiceI1), i - 1);
                ans += ncr(n - 1, i - 2);
                ans -= ans >= d ? d : 0;
                out.println(ans);
            }
            out.println(1);

        }

    }

    static class FastScanner {
        private InputStream in;
        private byte[] buffer = new byte[1024];
        private int bufPointer;
        private int bufLength;

