			a[i] = sc.nextInt();
			count[a[i]]++;
			if(count[a[i]] == 2) {
				tar = a[i];
				r = i;
			}
		}

		for(int i = 0; i < n + 1; i++) {
			if(a[i] == tar) {
				l = i;
				break;
			}
		}

		// n+1までの階乗の計算
		long[] fact = new long[n + 2];
		fact[0] = 1L;
