        main.solve();
    }
    public void solve() {
        COMinit();
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        HashMap<Integer, List<Integer>> map = new HashMap<>();
        int n = scan.nextInt();
        int[] a = new int[n+1];
        for (int i = 1; i <= n; i++) {
            a[i] = scan.nextInt();
            if (!map.containsKey(a[i])) {
                map.put(a[i], new ArrayList<>());
            }
            map.get(a[i]).add(i);
        }
        int left = 0;
        int right = 0;
        for (int x : map.keySet()) {
            List<Integer> list = map.get(x);
            if (list.size() == 2) {
                left = list.get(0) - 1;
                right = n + 1 - list.get(1);
            }
        }
        for (int i = 1; i <= n + 1; i++) {
            System.out.println((COM(n + 1, i) - COM(left + right, i - 1) + MOD) % MOD);
        }
    }
    void COMinit() {
        this.fac = new long[MAX_LEN];
        this.finv = new long[MAX_LEN];
        this.inv = new long[MAX_LEN];
        this.fac[0] = this.fac[1] = 1;
        this.finv[0] = this.finv[1] = 1;
        this.inv[1] = 1;
        for (int i = 2; i < MAX_LEN; i++) {
            fac[i] = fac[i-1] * i % MOD;
            inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
            finv[i] = finv[i-1] * inv[i] % MOD;
        }
    }
    long COM(int n, int k) {
        if (n < k) {
            return 0;
        };
        if (n <0 || k < 0) {
            return 0;
        }
        return fac[n] * (finv[k] * finv[n - k]%MOD)%MOD;
    }
}

