        	if (n < 0 || k < 0)		return 0;
        	return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;		
        }			

        public void solve() {
        	int N = ni();
        	int[] A = new int[N+1];
        	Map<Integer, Integer> map = new HashMap<>();
        	int l = 0, r = 0, a;
        	for (int i = 0; i < N+1; i++) {
				a = ni();
				if(map.containsKey(a)) {
					l = map.get(a);
					r = i;
				} else {
					map.put(a, i);
				}
			}
        	COMinit();
        	int cnt = l + N - r;
//        	prn("l = " + l + " r = " + r + "  cnt = " + cnt);
        	for (int i = 1; i <= N+1; i++) {
        		if(i == 1) {
    				prn(N);
        		} else {
        			prn(COM(N+1, i) - COM(cnt, i - 1));
        		}
        	}
        }
