                as[i] = sc.nextInt();
                if (pos[as[i] - 1] != -1) {
                    left = pos[as[i] - 1];
                    right = i;
                }
                else {
                    pos[as[i] - 1] = i;
                }
            }
            createPerms();
        }

        void solve() {
            long ans, minus;
            int tmp;
            for (int i = 1; i <= n + 1; i++) {
                minus = 0;
                tmp = left + n  - right;
                ans = (perm[n+1] * permInv[i] % MOD) * permInv[n+1 - i] % MOD;
                if (tmp >= i - 1)
                    minus = ((perm[tmp] * permInv[i - 1] % MOD) * permInv[tmp - i + 1]
                            + MOD) % MOD;
                ans = (ans - minus) % MOD;
                System.out.println(ans);
            }
        }

        void createPerms() {
            perm[0] = permInv[0] = 1;
            for (int i = 1; i < perm.length; i++) {
                perm[i] = i * perm[i-1] % MOD;
                permInv[i] = calcInv(perm[i]);
            }
        }

        long calcInv(long l) {
            long ret = 1L;
            long x = l, y = MOD - 2;
            while (y > 0) {
                if (y % 2 == 1)
                    ret = ret * x % MOD;
                x = x * x % MOD;
                y = y >> 1;
            }
            return ret;
        }
    }
}

