public void solve() {
	int num = ni();
	int a[] = ni(num + 1);
	int cnt[] = new int[num];
	for(int i = 0; i <= num; i ++) {
		a[i] --;
		cnt[a[i]] ++;
	}
	int dup = 0;
	for(int i = 0; i < num; i ++) {
		if(cnt[i] > 1) dup = i;
	}
	int index1 = -1;
	int index2 = -1;
	for(int i = 0; i <= num; i ++) {
		if(a[i] == dup) {
			if(index1 < 0) index1 = i;
			index2 = i;
		}
	}
	long ans[] = new long[num + 1];
	// errprtln(index1 + (num - index2));
	for(int i = 0; i <= num; i ++) {
		ans[i] = C(num + 1, i + 1);
		ans[i] -= C(index1 + (num - index2), i);
		ans[i] = mod(ans[i]);
	}
	for(int i = 0; i <= num; i ++) {
		prtln(ans[i]);
	}
}


