			fac[i] = (i*fac[i-1])%MOD;
		}

		pw.println(N);
		for (int k = 2; k <= N+1; k++) {
			long total = choose(N+1,k); //(N+1)C(k).
			long bad = choose(N-1-z,k-1); //(N-1-z)C(k-1).
			long ans = (total-bad+MOD)%MOD;
			pw.println(ans);
		}

		pw.close();
	}

	public static long choose(int n, int k) {
		if (n < k) return 0;
		long num = fac[n];
		long den = (fac[k]*fac[n-k])%MOD;
		long denInv = power(den,MOD-2,MOD);
		long ans = (num*denInv)%MOD;
		return ans;
	}


