      xInv[i] = modPow(x[i], inv, m);
    }

    long nCk, lrCk;
    StringBuffer sb = new StringBuffer();
    for(int i=0;i<n+1;i++){
        nCk = x[n+1] * xInv[i+1] % m * xInv[n-i] % m;

