        if(b > a / 2){
            b = a - b;
        }
        if(c[b] != 0){
            return c[b];
        }
        if(b == 0) return 1;
        for(int i = 1 ; i <=b; i++){
            ans = ans * (a - i + 1) / i;
        }

        c[b] = ans % 1000000007;
        return c[b];
    }

