    Set<Integer> set = new HashSet<>();

    for(int i=0;i<n+1;i++){
      if(set.contains(a[i])){
        for(int j=0;j<i;j++){
          if(a[i]==a[j]){
            deplLeft = j;
            deplRight = i;
          }
        }
      }else{
        set.add(a[i]);
      }
    }

    fact = new long[n+2];

    fact[0] = 1;
    for(int i=1;i<n+2;i++){
      fact[i] = fact[i-1] * i % m;
    }

    StringBuffer sb = new StringBuffer();
    long b,c;
    for(int i=0;i<n+1;i++){
      b = nck(n+1, i+1);

      if(deplLeft+n-deplRight-i>=0){
        c = nck(deplLeft+n-deplRight, i);
      } else {
        c = 0;
      }
      // System.out.println(b);
