		int firstPosition = 0;
		int secondPosition = 0;
		for(int i = 0; i < n + 1; i++){
			if(hasOne[a[i]]){
				hasTwo[a[i]] = true;
				firstPosition = position[a[i]];
				secondPosition = i;
			}else{
				position[a[i]] = i;
				hasOne[a[i]] = true;
			}
		}

		int x = firstPosition + (n + 1 - secondPosition - 1);

