				combX[i] = 1;
				if(i >= x / 2 + 1){
					combX[i] = combX[x - i];
				}else{
					for(int j = 1; j <= i; j++){
						combX[i] *= (long)(x - j + 1);
						combX[i] /= (long)j;
						combX[i] = combX[i] % 1000000007;
