public class Main {
	private static final long MOD = 1_000_000_000 + 7;

	// 反復二乗法を用いる
	public static long myPow(long a) {
		long ans = 1L;
		long x = a;
		long b = 1_000_000_000 + 5L;

		for(int i = 0; i < 32; i++) {
			if((b & (1L << i)) != 0L) {
				ans = (ans * x) % MOD;
			}
			x = (x * x) % MOD;
		}

		return ans % MOD;
	}

	public static long nck(int n, int k, long[] fact) {
		if(n < k) {
			return 0;
		}
		return (((fact[n] * myPow(fact[n - k])) % MOD) * myPow(fact[k])) % MOD;
	}

