class Combination {
    static final int MOD = 1000000007;
    long[] fac;
    long[] finv;
    long[] inv;

    public Combination (int size) {
        fac = new long [size];
        finv = new long [size];
        inv = new long [size];
        fac[0] = 1;
        fac[1] = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;
        for (int i = 2; i < size; i++) {
            fac[i] = fac[i - 1] * i % MOD;
            inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
            finv[i] = finv[i - 1] * inv[i] % MOD;
        }
    }


    public long getComb(int n, int k) {
        if (n < k || n < 0 || k < 0) {
            return 0;
        }
        return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
    }

}

import java.util.*;
public class Main {
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int numOfNumber = scanner.nextInt() + 1;
        int[] numbers = new int[numOfNumber];
        for (int i = 0; i < numOfNumber; i++) {
            numbers[i] = scanner.nextInt();
        }
        HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();
        for (int i = 0; i < numOfNumber; i++) {
            if (map.containsKey(numbers[i]) == false) {
                map.put(numbers[i], 1);
            }
            else {
                map.put(numbers[i], map.get(numbers[i]) + 1);
            }
        }
        int dup = 0;
        for (int key : map.keySet()) {
            if (map.get(key) > 1) {
                dup = key;
                break;
            }
        }
        int minIndex = -1;
        int maxIndex = -1;
        for (int i = 0; i < numOfNumber; i++) {
            if (numbers[i] == dup) {
                if (minIndex >= 0) {
                    maxIndex = i;
                }
                else {
                    minIndex = i;
                }
            }
        }
        int d = maxIndex - minIndex - 1;
        int[][] dp = new int[numOfNumber + 1][(numOfNumber + 1) / 2 + 1];
        for (int i = 0; i < dp.length; i++) {
            for (int j = 0; j < dp[0].length; j++) {

                if (j == 0 || i == j) {
                    dp[i][j] = 1;
                }
                else if (i > 0) {
                    dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1];
                    dp[i][j] %= 1000000007;
                }
            }
        }
        for (int k = 1; k <= numOfNumber; k++) {
            int cof1 = k > (numOfNumber + 1) / 2 ? dp[numOfNumber][numOfNumber - k] : dp[numOfNumber][k];
            int cof2 = numOfNumber - d - 2 >= 0 && k - 1 <= numOfNumber - d - 2 ? (k - 1 > (numOfNumber - d - 2 + 1) / 2 ? dp[numOfNumber - d - 2][numOfNumber - d - 2 - k + 1] : dp[numOfNumber - d - 2][k - 1]) : 0;
            System.out.println(cof1 - cof2);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.InputMismatchException;
import java.util.Map;
import java.util.Map.Entry;
import java.util.StringTokenizer;

public class Main {

	public static void main(String[] args) throws IOException {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			long[] a = in.nextLongArray(n+1);
			long sum = 0;

			Map<Long, Integer> map = new HashMap<>();
			for (int i = 0; i < n+1; i++) {
				map.merge(a[i], 1, Integer::sum);
			}

			long b = -1;
			for (Entry<Long, Integer> e : map.entrySet()) {
				if (e.getValue() == 2) {
					b = e.getKey();
					break;
				}
			}

			int left = INF, right = -INF;
			for (int i = 0; i < n+1; i++) {
				if (a[i] == b) {
					left = Math.min(left, i);
					right = Math.max(right, i);
				}
			}

			int adj = left + n-right;

			for (int r = 1; r <= n+1; r++) {
				sum = 0;
				sum += comb(n+1, r);
				if (r == 1) {
					sum--;
				} else if (adj >= r-1) {
					sum -= comb(adj, r-1);
				}
				out.println(sum);
			}

		}

		/**
		 * 二項係数
		 * 前提 n < modP
		 * nCr = n!/(r!*(n-r)!)である。この時分子分母にMODが来る場合は以下のように使用する
		 * */
		public static long comb(int n, int r) {
			return fact[n] * factInv[r] % MOD * factInv[n - r] % MOD;
		}

		/**
		 * 階乗数の逆元
		 *
		 * */
		public static int MAXN = 200000;
		public static long MOD = 1000000007;

		static long[] fact = factorialArray(MAXN, MOD);
		static long[] factInv = factorialInverseArray(MAXN, MOD,
				inverseArray(MAXN, MOD));

		// 階乗の mod P テーブル
		public static long[] factorialArray(int maxN, long mod) {
			long[] fact = new long[maxN + 1];
			fact[0] = 1 % mod;
			for (int i = 1; i <= maxN; i++) {
				fact[i] = fact[i - 1] * i % mod;
			}
			return fact;
		}

		// 数 i に対する mod P での逆元テーブル
		public static long[] inverseArray(int maxN, long modP) {
			long[] inv = new long[maxN + 1];
			inv[1] = 1;
			for (int i = 2; i <= maxN; i++) {
				inv[i] = modP - (modP / i) * inv[(int) (modP % i)] % modP;
			}
			return inv;
		}

		// 階乗の逆元テーブル
		public static long[] factorialInverseArray(int maxN, long modP,
				long[] inverseArray) {
			long[] factInv = new long[maxN + 1];
			factInv[0] = 1;
			for (int i = 1; i <= maxN; i++) {
				factInv[i] = factInv[i - 1] * inverseArray[i] % modP;
			}
			return factInv;
		}

	}

	static class InputReader {
		BufferedReader in;
		StringTokenizer tok;

		public String nextString() {
			while (!tok.hasMoreTokens()) {
				try {
					tok = new StringTokenizer(in.readLine(), " ");
				} catch (IOException e) {
					throw new InputMismatchException();
				}
			}
			return tok.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(nextString());
		}

		public long nextLong() {
			return Long.parseLong(nextString());
		}

		public double nextDouble() {
			return Double.parseDouble(nextString());
		}

		public int[] nextIntArray(int n) {
			int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public long[] nextLongArray(int n) {
			long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public InputReader(InputStream inputStream) {
			in = new BufferedReader(new InputStreamReader(inputStream));
			tok = new StringTokenizer("");
		}

	}

}

