public class Main {

	public static void main(String[] args) throws NumberFormatException, IOException {
		// TODO 自動生成されたメソッド・スタブ
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		int n = Integer.parseInt(br.readLine());

		int mod = 1000000007;
		int[] input = new int[n+1];
		int[] numCount = new int[n+1];
		int sameNumber = -1;
		Arrays.fill(numCount, 0);

		//Date from = new Date();

		long[] factTable = new long[100001];
		long[] invTable = new long[100001];

		initFactTable(factTable, invTable, 100000, mod);

		//Date to = new Date();

		//System.out.println("init takes "+(to.getTime()-from.getTime())+"ms");

		String[] tmpArray = br.readLine().split(" ");
		for(int i = 0; i < n + 1; i++){
			input[i] = Integer.parseInt(tmpArray[i]);
			numCount[input[i]]++;

			if(numCount[input[i]] == 2){
				sameNumber = input[i];
				//System.out.println("Same number is "+input[i]);
			}
		}

		//同じ数字の間に何個の数字があるか
		int between = 0;
		int first = -1;
		for(int i = 0; i < n+1 ;i++){
			if(first == -1 && input[i] == sameNumber){
				first = i;
			}
			else if(input[i] == sameNumber){
				between = i - first - 1;
				//System.out.println("between is "+between );
				break;
			}
		}

		//Date from = new Date();

		for(int k = 1; k <= n + 1; k++ ){
			long result = 0;

			if(n - 1 >= k){
				result += combinationWithMod(n - 1, k, mod, factTable, invTable);
			}
			if(k >= 2){
				result += combinationWithMod(n - 1, k - 2, mod, factTable, invTable);
			}
			if(n >= k){
				result += combinationWithMod(n - 1, k - 1, mod, factTable, invTable)*2;
			}
			if(n - between >= k){
				result -= combinationWithMod(n - 1 - between, k - 1, mod, factTable, invTable);
			}
			System.out.println(result%mod);
		}

		//Date to = new Date();

		//System.out.println("time "+(to.getTime()- from.getTime())+"ms");
	}

	static void initFactTable(long[] factTable, long[] invTable, int n, int mod){
		//factTable = new long[n+1];
		//invTable = new long[n+1];

		factTable[0] = 1;
		invTable[n] = binaryPowWithMod(factorialWithMod(n, mod), mod - 2, mod);
		for(int i = 1; i <= n ; i++){
			factTable[i] = factTable[i - 1]*i%mod;
			invTable[n - i] = invTable[n - i + 1]*(n - i + 1)%mod;
			//invTable[i] = binaryPowWithMod(factorialWithMod(i, mod), mod - 2, mod);
			//System.out.println(i + " fact " + factTable[i] + " inv "+invTable[i]);
		}

		//デバッグ用
		/*
		for(int i = 0; i <= n ; i++){
			System.out.println(i + " fact " + factTable[i] + " inv "+invTable[i]);
		}
		*/
	}

	static long combinationWithMod(int n,int p, int mod, long[] factTable, long[] invTable){
		long result = 1;

		result *= factTable[n];
		//p!で割ったのと同じ扱いになる？	
		long div1 = invTable[p];

		//(n-p)!で割ったのと同じ扱いになる？
		long div2 = invTable[n - p];

		result *= div1;
		result %= mod;

		result *= div2;
		result %= mod;

		return result;
	}

	static long combinationWithMod(int n,int p, int mod){
		long result = 1;

		result *= factorialWithMod(n, mod);
		//p!で割ったのと同じ扱いになる？	
		long div1 = binaryPowWithMod(factorialWithMod(p, mod), mod - 2, mod);

		//(n-p)!で割ったのと同じ扱いになる？
		long div2 = binaryPowWithMod(factorialWithMod(n - p, mod), mod - 2, mod);

		result *= div1;
		result %= mod;

		result *= div2;
		result %= mod;

		return result;
	}

	static long binaryPowWithMod(long base, long pow, int mod){
		long result = 1;

		while(pow>0){
			if(pow % 2 == 0){
				base = (base*base)%mod;
				pow /= 2;
			}
			else{
				result *= base;
				result %= mod;
				pow--;
			}
		}

		return result;
	}

	static long factorialWithMod(int n, int mod){
		long result = 1;
		for(int i = 2; i <= n ;i++){
			result *= i;
			result %= mod;
		}

		return result;
	}

}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Scanner;

public class Main {
    private long fac[];
    private long finv[];
    private long inv[];
    private static int MAX_LEN = 510000;
    private static int MOD = 1000000007;
    public static void main(String[] args) {
        Main main = new Main();
        main.solve();
    }
    public void solve() {
        COMinit();
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        HashMap<Integer, List<Integer>> map = new HashMap<>();
        int n = scan.nextInt();
        int[] a = new int[n+1];
        for (int i = 1; i <= n; i++) {
            a[i] = scan.nextInt();
            if (!map.containsKey(a[i])) {
                map.put(a[i], new ArrayList<>());
            }
            map.get(a[i]).add(i);
        }
        int left = 0;
        int right = 0;
        for (int x : map.keySet()) {
            List<Integer> list = map.get(x);
            if (list.size() == 2) {
                left = list.get(0) - 1;
                right = n + 1 - list.get(1);
            }
        }
        for (int i = 1; i <= n + 1; i++) {
            System.out.println(COM(n + 1, i) - COM(left + right, i - 1));
        }
    }
    void COMinit() {
        this.fac = new long[MAX_LEN];
        this.finv = new long[MAX_LEN];
        this.inv = new long[MAX_LEN];
        this.fac[0] = this.fac[1] = 1;
        this.finv[0] = this.finv[1] = 1;
        this.inv[1] = 1;
        for (int i = 2; i < MAX_LEN; i++) {
            fac[i] = fac[i-1] * i % MOD;
            inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
            finv[i] = finv[i-1] * inv[i] % MOD;
        }
    }
    long COM(int n, int k) {
        if (n < k) {
            return 0;
        };
        if (n <0 || k < 0) {
            return 0;
        }
        return fac[n] * (finv[k] * finv[n - k]%MOD)%MOD;
    }
}

import java.io.*;
