        {
            long bn = dp[N + 1] * RepPow(dp[N + 1 - k], INF - 2) % INF;
            long bk = RepPow(dp[k], INF - 2) % INF;
            long b = bn * bk;
            long c = 0;
            if (k - 1 <= m)
            {
                long cn = dp[m] * RepPow(dp[m - (k - 1)], INF - 2) % INF;
                long ck = RepPow(dp[k - 1], INF - 2) % INF;
                c = cn * ck;
            }
            Console.WriteLine((b % INF) - (c % INF));
        }
