    public class ABC066D_11
    {
        static int modVal = 1000000007;

        public static void Main(string[] args)
        {

            // データ数の入力
            int N = int.Parse(Console.ReadLine());

            // データの入力
            List<int> numList = Console.ReadLine().Split(' ').Select(int.Parse).ToList();

            // 重複データの確認
            int duplicateLeft = 0;
            int duplicateRight = 0;
            for(int i = 1; i <= N; i++)
            {
                if(numList.Count(val => val == i) > 1)
                {
                    duplicateLeft = numList.FindIndex(val => val == i);
                    duplicateRight = numList.FindLastIndex(val => val == i);
                }
            }

            for(int i = 1; i <= N + 1; i++)
            {
                // パターン数
                long patternNum;

                if(i > N)
                {
                    patternNum = 1;
                }
                else if(i == 1)
                {
                    patternNum = N;
                }
                else
                {
                    patternNum = GetCombinationNum(N + 1, i);
                    patternNum -= GetCombinationNum(duplicateLeft - 1 + N - duplicateRight + 1, i - 1);
                    patternNum = (patternNum + modVal) % modVal;
                }

                Console.WriteLine(patternNum);
            }

        }

        static long GetCombinationNum(int n, int r)
        {
            double patternNum = 1;
            for(int i = n; i > n - r; i--)
            {
                patternNum = patternNum * i;
            }

            for(int i = 2; i <= r; i++)
            {
                patternNum = patternNum / i;
            }

            return (long)(patternNum % modVal);
        }

        public class MathMod
        {

            // 階乗計算に使う素数(階乗計算の上限数) 10^9+7
            static int modVal = 1000000007;

            // 階乗計算を行う数
            private static int FactorialMax = 12000;


            // 階乗の剰余
            private static int[] factorialMod = new int[FactorialMax + 1];

            // 階乗の逆元
            private static int[] factorialInverse = new int[FactorialMax + 1];


            static MathMod()
            {

                // 階乗の剰余・逆元を計算
                factorialMod[0] = 1;
                factorialInverse[0] = 1;
                for(long i = 1; i <= FactorialMax; i++)
                {
                    factorialMod[i] = (int)((factorialMod[i - 1] * i) % modVal);
                    factorialInverse[i] = Pow(factorialMod[i], modVal - 2);
                }

            }

            /// <summary>累乗を求める</summary>
            public static int Pow(int x, int y)
            {
                long remaining = y;
                long p = x;

                long ret = 1;

                while( remaining > 0 )
                {
                    if( remaining % 2 == 0 )
                    {
                        p = (p * p) % modVal;
                        remaining /= 2;
                    }
                    else
                    {
                        ret = (ret * p) % modVal;
                        remaining -= 1;
                    }
                }

                return (int)ret;
            }


            /// <summary>階乗を求める</summary>
            public static double Factorial(int n)
            {
                if(n < 0 || n > FactorialMax)
                {
                    throw new ArgumentOutOfRangeException();
                }

                return factorialMod[n];
            }


            /// <summary>組み合わせ数を求める</summary>
            /// <param name="n">全体集合の要素数</param>
            /// <param name="r">取り出す要素数</param>
            /// <returns>組み合わせ数</returns>
            public static double Combination(int n, int r)
            {
                if(n <= 0 || n > FactorialMax)
                {
                    throw new ArgumentOutOfRangeException();
                }
                if(r <= 0 || r > FactorialMax)
                {
                    throw new ArgumentOutOfRangeException();
                }
                if(n < r)
                {
                    throw new ArgumentOutOfRangeException();
                }

                return (long)factorialMod[n] * factorialInverse[r] % modVal * factorialInverse[n - r] % modVal;
            }

        }

    }

}

