namespace AtCoder.Beginner066
{
    public class ABC066D_11
    {
        static int modVal = 1000000007;

        public static void Main(string[] args)
        {

            // データ数の入力
            int N = int.Parse(Console.ReadLine());

            // データの入力
            List<int> numList = Console.ReadLine().Split(' ').Select(int.Parse).ToList();

            // 重複データの確認
            int duoLeft = 0;
            int duoRight = 0;
            for(int i = 1; i <= N; i++)
            {
                if(numList.Count( val => val == i ) > 1 )
                {
                    duoLeft = numList.FindIndex(val => val == i);
                    duoRight = numList.FindLastIndex(val => val == i);
                }
            }

            for( int i = 1; i <= N + 1; i++ )
            {
                // パターン数
                long patternNum;

                if( i > N )
                {
                    patternNum = 1;
                }
                else if(i == 1)
                {
                    patternNum = N;
                }
                else
                {
                    patternNum = GetCombinationNum(N + 1, i);
                    patternNum -= GetCombinationNum(duoLeft - 1 + N - duoRight + 1, i - 1);
                    patternNum = (patternNum + modVal) % modVal;
                }

            }

        }

        static long GetCombinationNum(int n, int r)
        {
            double patternNum = 1;
            for(int i = n; i > n - r; i--)
            {
                patternNum = patternNum * i;
            }

            for(int i = 2; i <= r; i++)
            {
                patternNum = patternNum / i;
            }

            return (long)(patternNum % modVal);
        }

    }
}

