        static void Solve()
        {
            var n = Sarray()[0];
            var ai = Sarray();
            var dct = new Dictionary<long, long>();
            var lIdx = 0L;
            var rIdx = 0L;
            for (var i = 0; i < n + 1; ++i)
            {
                if (dct.ContainsKey(ai[i]))
                {
                    lIdx = dct[ai[i]];
                    rIdx = i;
                    break;
                }
                dct[ai[i]] = i;
            }
            var lNum = lIdx;
            var rNum = n + 1 - (rIdx + 1);
            var cmb = new Combination(n + 10, Mod);
            for (var k = 1; k <= n + 1; ++k)
            {
                var ans = cmb.nCk((int)n + 1, k);
                var dd = cmb.nCk((int)(lNum + rNum), k - 1);
                WriteLine((ans - dd + Mod) % Mod);
            }
        }
        public class Combination
        {
            readonly long mod;
            readonly long[] fac, finv, inv;
            public Combination(long n, long mod = 1000000007)
            {
                long max = n + 1;
                this.mod = mod;
                fac = new long[max];
                finv = new long[max];
                inv = new long[max];
                fac[0] = fac[1] = 1;
                finv[0] = finv[1] = 1;
                inv[1] = 1;
                for (int i = 2; i < max; ++i)
                {
                    fac[i] = fac[i - 1] * i % mod;
                    inv[i] = mod - inv[mod % i] * (mod / i) % mod;
                    finv[i] = finv[i - 1] * inv[i] % mod;
                }
            }
            public long nCk(int n, int k)
            {
                if (n < k) return 0;
                if (n < 0 | k < 0) return 0;
                return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
            }
        }


