    class Solver
    {
        private long N;
        private long[] A;

        public void Solve()
        {
            @in(out N);
            @in(out A);

            int l = -1;
            int r = -1;
            Dictionary<long, int> index = new Dictionary<long, int>();
            for (int i = 0; i < N + 1; i++)
            {
                if (index.ContainsKey(A[i]))
                {
