                    r = i;
                    break;
                }

                index.Add(A[i], i);
            }

            int outside = l + (int) N - r + 1;

            Console.WriteLine(N);
            for (int i = 2; i <= N + 1; i++)
            {
                Modular a = Modular.Ncr((int) N + 1, i);
                if (i == 2)
                {
                    a -= outside - 1;
                }
                else if (i == 3)
                {
                    a -= l * (N - r + 1);
                }
                else
                {
                    a -= Modular.Ncr(outside, i);
                }

                Console.WriteLine((int) a);
            }
        }
