                {
                    duplicateLeft = used[nums[i]] - 1;
                    duplicateRight = i;
                    break;
                }
                used[nums[i]] = i + 1;
            }

            // パターン数の出力
            for(int i = 1; i <= N + 1; i++)
            {
                long patternNum = 
                    (MathMod.Combination(N + 1, i) -
                     MathMod.Combination(duplicateLeft - 1 + N - duplicateRight + 1, i - 1) +
                     modVal) % modVal;

                Console.WriteLine(patternNum);
            }

        }

        static long GetCombinationNum(int n, int r)
        {
            double patternNum = 1;
            for(int i = n; i > n - r; i--)
            {
                patternNum = patternNum * i;
