            for(int i = 2; i <= r; i++)
            {
                patternNum = patternNum / i;
            }

            return (long)(patternNum % modVal);
        }

        public class MathMod
        {

            // 階乗計算に使う素数(階乗計算の上限数) 10^9+7
            static int modVal = 1000000007;

            // 階乗計算を行う数
            private static int FactorialMax = 100002;


            // 階乗の剰余
            private static int[] factorialMod = new int[FactorialMax + 1];

            // 階乗の逆元
            private static int[] factorialInverse = new int[FactorialMax + 1];


            static MathMod()
            {

                // 階乗の剰余・逆元を計算
                factorialMod[0] = 1;
                factorialInverse[0] = 1;
                for(long i = 1; i <= FactorialMax; i++)
                {
                    factorialMod[i] = (int)((factorialMod[i - 1] * i) % modVal);
                    factorialInverse[i] = Pow(factorialMod[i], modVal - 2);
                }

            }

            /// <summary>累乗を求める</summary>
            public static int Pow(int x, int y)
            {
                long remaining = y;
                long p = x;

                long ret = 1;

                while( remaining > 0 )
                {
                    if( remaining % 2 == 0 )
                    {
                        p = (p * p) % modVal;
                        remaining /= 2;
                    }
                    else
                    {
                        ret = (ret * p) % modVal;
                        remaining -= 1;
                    }
                }

                return (int)ret;
            }


            /// <summary>階乗を求める</summary>
            public static double Factorial(int n)
            {
                if(n < 0 || n > FactorialMax)
                {
                    throw new ArgumentOutOfRangeException();
                }

                return factorialMod[n];
            }


            /// <summary>組み合わせ数を求める</summary>
            /// <param name="n">全体集合の要素数</param>
            /// <param name="r">取り出す要素数</param>
            /// <returns>組み合わせ数</returns>
            public static int Combination(int n, int r)
            {
                if(n > FactorialMax || r > FactorialMax)
                {
                    throw new ArgumentOutOfRangeException();
                }

                if(n < r || n < 0 || r < 0)
                {
                    return 0;
                }

                return (int)((long)factorialMod[n] * factorialInverse[r] % modVal * factorialInverse[n - r] % modVal);
            }

        }

    }

}

