            {
                res[i] = mc.Combination(N - 1, i);
            }

            //aを1つ使うとき
            res[1] = (res[1] + 1) % mod;
            for (int i = 1; i <= N - 1; i++)
            {
                res[i + 1] = (res[i + 1] + mc.Combination(N - 1, i) * 2 % mod) % mod;
            }
            for (int i = 1; i <= s+u; i++)
            {
                res[i + 1] = (res[i + 1] - mc.Combination(s+u, i) + mod) % mod;
            }

            //aを2つ使うとき
            res[2] = (res[2] + 1) % mod;
            for (int i = 1; i <= N - 1; i++)
            {
                res[i + 2] = (res[i + 2] + mc.Combination(N - 1, i)) % mod;
            }

            for (int i = 1; i <= N + 1; i++) Console.WriteLine(res[i]);
        }

        class ModCombination
        {
            static long mod = 1000000007;
            static int max = 1000000;

            long[] fac = new long[max];
            long[] finv = new long[max];
            long[] inv = new long[max];

            /// <summary>
            /// fac,finv,invの事前計算
            /// n<maxをみたすO(max)
            /// </summary>
            public ModCombination()
            {

                fac[0] = fac[1] = 1;
                finv[0] = finv[1] = 1;
                inv[1] = 1;
                for (int i = 2; i < max; i++)
                {
                    fac[i] = fac[i - 1] * i % mod;
                    inv[i] = mod - inv[mod % i] * (mod / i) % mod;
                    finv[i] = finv[i - 1] * inv[i] % mod;
                }
            }

            /// <summary>
            /// O(1)
            /// </summary>
            public long Combination(int n, int m)
            {
                if (n < m) return 0;
                if (n < 0 || m < 0) return 0;
                return fac[n] * (finv[m] * finv[n - m] % mod) % mod;
            }
        }
    }
