class Program
{
    static long MOD = 1000000007;
    static long[] fact;

    // x^y (mod m)
    static long ModPow(long x, long y, long m)
    {
        long ans = 1;

        while (y > 0)
        {
            if (y % 2 == 1)
            {
                ans = ans * x % m;
                y--;
            }
            y /= 2;
            x = x * x % m;
        }

        return ans;
    }

    // C(n, k) (mod m)
    // mは素数
    static long ModComb(int n, int k, long m)
    {
        if (n < k)
        {
            return 0;
        }
        return fact[n] * ModPow(fact[k], m - 2, m) % m * ModPow(fact[n - k], m - 2, m) % m;
    }

    static void Main()
    {
        // 入力
        var n = int.Parse(Console.ReadLine());
        var a = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();

