            for (int i = 0; i < n + 1; i++)
            {
                f[i] = -1;
            }

            for (int i = 0; i < n + 1; i++)
            {
                if (f[a[i]] >= 0)
                {
                    first = f[a[i]];
                    second = i;
                    break;
                }
                f[a[i]] = i;
            }
            count = n - second + first;
        }

        // 階乗テーブルの生成
        fact = new long[n + 2];
        fact[0] = 1;
        for (int i = 1; i <= n + 1; i++)
        {
            fact[i] = fact[i - 1] * i % MOD;
        }

        for (int i = 1; i <= n + 1; i++)
        {
            double ans = (ModComb(n + 1, i, MOD) - ModComb(count, i - 1, MOD) + MOD) % MOD;
            Console.WriteLine(ans);
        }

        return;
    }
