class Simple {
    private int n;
    private int[] a;
    void Solve() {
        //input
        n = io.Int;
        a = new int[n + 1];
        for(int i = 0; i < a.Length; ++i)
            a[i] = io.Int;
        //cal
        var dic = new Dictionary <int, int>();
        foreach(var v in a) {
            if(!dic.ContainsKey(v))
                dic[v] = 0;
            dic[v]++;
        }
        var dup = dic.First(kp => kp.Value == 2).Key;
        var indexedA = a.Select((v, i) => new {value = v, index = i}).ToArray();
        var l = indexedA.First(v => v.value == dup).index;
        var r = indexedA.Last (v => v.value == dup).index;
        var C = GenerateCombinations(n + 1);
        for(int i = 0; i < a.Length; ++i) {
            var ans = C[n + 1, i + 1];
            var t = l + n - r;
            if(i <= t)
                ans = ((ans + mod) - C[t, i]) % mod;
            //ret
            WriteLine(ans);
        }
    }
    long mod = 1000000007; //10^9+7
    long[,] GenerateCombinations(int n) {
        var table = new long[n + 1, n + 1];
        for(int i = 0; i <= n; i++) for(int j = 0; j <= i; j++)                 
            table[i, j] = (j == 0 || j == i) ? 1L : (table[i - 1, j - 1] + table[i - 1, j]) % mod;            
        return table;
    }
    SimpleIO io = new SimpleIO();
    public static void Main(string[] args) => new Simple().Stream();
    private void Stream() {
        //var exStdIn = new System.IO.StreamReader("stdin.txt");
        //SetIn(exStdIn);
        Solve();
        io.Flush();
    }
}
