        var a = Array.ConvertAll(line, int.Parse);
        var b = Array.ConvertAll(line, int.Parse);
        var w = Array.BinarySearch(a, 19);
        Array.Sort(b);
        var ww = 0;
        for (int i = 0; i < n; i++)
            if (b[i] == b[i + 1]) { ww = b[i]; break; }
        var p = 0; var p2 = 0;
        for (int i = 0; i < n + 1; i++)
            if (a[i] == ww) { p = i; break; }
