        }

        decimal upper = 1;
        decimal lower = 1;
        decimal ans = 0;
        for (int i = 0; i < k; i++) {
            upper = upper * (n - i);
            lower = lower * (k - i);
        }
        ans = upper / lower;
        return Convert.ToInt32(((ans) % mod));
    }

