      var a = Console.ReadLine().Split(' ');
      decimal l = 0;
      decimal r = 0;
      for (int i = 0; i <= n - 1; i++)
      {
        for (int j = i + 1; j <= n; j++)
        {
          if (a[i] == a[j])
          {
            l = i;
            r = j;
            break;
          }
        }
      }
      for (decimal k = 1; k <= n+1; k++)
      {
        Console.WriteLine((Comb(n+1,k) - Comb(n + 1 - r + l - 1,k - 1)) % (10^9 + 7));
      }
    }

    public static decimal Comb(decimal n, decimal r)
    {
      var key = n.ToString() + "," + r.ToString();
      if (Memo.ContainsKey(key)) return Memo[key];
      if (r == 0) return 1;
      if (n == r) return 1;
      if (n < r) return 0;
      if (n == 0) return 1;
      Memo.Add(key, Comb(n - 1, r) + Comb(n - 1, r - 1));
      return Memo[key];
    }
  }
