class Program
{

    static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var a = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
        var f = new int[n + 1];
        int first = 0, second = 0;

        for (int i = 0; i < n + 1; i++)
        {
            f[i] = -1;
        }

        for (int i = 0; i < n + 1; i++)
        {
            if (f[a[i]] >= 0)
            {
                first = f[a[i]];
                second = i;
                break;
            }
            f[a[i]] = i;
        }

        var Fact = new double[n + 2];
        Fact[0] = 1;
        Fact[1] = 1;
        for (int i = 2; i < n + 2; i++)
        {
            Fact[i] = Fact[i - 1] * i;
        }

        int count = n - second + first;
        for (int i = 1; i <= n + 1; i++)
        {
            double ans = Fact[n + 1] / Fact[i] / Fact[n + 1 - i];
            if (count >= i - 1) ans -= Fact[count] / Fact[i - 1] / Fact[count - i + 1];
            Console.WriteLine(ans);
        }
    }
