public class ModCombination {
	private ModInt[] _fact, _rfact, _inv;
	private ModInt[] _mm;

	public ModCombination(int sz) : this(sz, long.MaxValue) {}
	public ModCombination(int sz, long modulo){
		_fact = new ModInt[sz+1];
		_rfact = new ModInt[sz+1];
		_inv = new ModInt[sz+1];

		_mm = new ModInt[]{new ModInt(0,modulo), new ModInt(1,modulo)};

		_fact[0] = _rfact[sz] = _inv[0] = _mm[1];
		for(int i = 1; i <= sz; i++) _fact[i] = _fact[i - 1] * i;
		_rfact[sz] /= _fact[sz];
		for(int i = sz - 1; i >= 0; i--) _rfact[i] = _rfact[i + 1] * (i + 1);
		for(int i = 1; i <= sz; i++) _inv[i] = _rfact[i] * _fact[i - 1];
	}

	public ModInt P(int n, int r) {
		if(r < 0 || n < r) return _mm[0];
		return _fact[n] * _rfact[n - r];
	}

	public ModInt C(int n, int r) {
		if(r < 0 || n < r) return _mm[0];
		return _fact[n] * _rfact[r] * _rfact[n - r];
	}

	public ModInt H(int n, int r) {
		if(n < 0 || r < 0) return _mm[0];
		return r == 0 ? _mm[1] : C(n + r - 1, r);
	}

	public ModInt B(int n, int k) {
		if(n == 0) return _mm[1];
		k = k<n ? k : n;
		ModInt ret = _mm[0];
		long mo = _mm[0].Modulo;
		ModInt[] pref = new ModInt[k + 1];
		pref[0] = _mm[1];
		for(int i = 1; i <= k; i++) {
			if((i & 1)==1) pref[i] = pref[i - 1] - _rfact[i];
			else pref[i] = pref[i - 1] + _rfact[i];
		}
		for(int i = 1; i <= k; i++) ret += (new ModInt(i, mo)).Pow(n) * _rfact[i] * pref[k - i];

		return ret;
	}

	public ModInt S(int n, int k) {
		ModInt ret = _mm[0];
		long mo = _mm[0].Modulo;
		for(int i = 0; i <= k; i++) {
			var add = (new ModInt(i, mo)).Pow(n) * this.C(k, i);
			if(((k - i) & 1)==1) ret -= add;
			else ret += add;
		}
		return ret * _rfact[k];
	}

	public static ModInt[][] PartitionTable(int n, int k, long modulo=long.MaxValue) {
		ModInt[][] dp = new ModInt[n + 1][];
		for(int i=0;i<=n;i++) dp[i] = new ModInt[k + 1];
		dp[0][0] = new ModInt(1, modulo);
		for(int i = 0; i <= n; i++) {
			for(int j = 1; j <= k; j++) {
				if(i - j >= 0) dp[i][j] = dp[i][j - 1] + dp[i - j][j];
				else dp[i][j] = dp[i][j - 1];
			}
		}
		return dp;
	}


}


public struct ModInt {
	public long Value;
	public long Modulo;

	public ModInt(long value) : this(value, long.MaxValue) {}
	public ModInt(long value, long modulo) {
		this.Modulo = modulo;
		this.Value = value >= 0 ? value % modulo : (modulo - (-value) % modulo) % modulo;
	}

    public static implicit operator ModInt(long v) { return new ModInt(v, 1000000007L); }
	public static ModInt operator-(ModInt a) { return new ModInt(-1*a.Value, a.Modulo); }
	public static ModInt operator+(ModInt a, ModInt b) { return new ModInt(a.Value + b.Value, a.Modulo); }
	public static ModInt operator-(ModInt a, ModInt b) { return new ModInt(a.Value - b.Value, a.Modulo); }
	public static ModInt operator*(ModInt a, ModInt b) { return new ModInt(a.Value * b.Value, a.Modulo); }
	public static ModInt operator/(ModInt a, ModInt b) { return a * b.Inverse(); }
	public static bool operator==(ModInt a, ModInt b) { return a.Equals(b); }
	public static bool operator!=(ModInt a, ModInt b) { return !a.Equals(b); }

	public ModInt Inverse() {
		long a = this.Value, b = this.Modulo, u = 1, v = 0, t, s;
		while(b > 0) {
			t = a / b;
			s = a - t * b; a = b; b = s;
			s = u - t * v; u = v; v = s;
		}
		return new ModInt(u, this.Modulo);
	}

	public ModInt Pow(int n) {
		ModInt ret = new ModInt(1, this.Modulo);
		ModInt mul = new ModInt(this.Value, this.Modulo);
		while(n > 0) {
			if((n & 1)==1) ret *= mul;
			mul *= mul;
			n >>= 1;
		}
		return ret;
	}

    public override bool Equals(object obj) {
        if (!(obj is ModInt)) throw new ArgumentException("Object is not a ModInt");
        return Equals((ModInt)obj);   
    }
    public bool Equals(ModInt p) => (this.Value == p.Value);
    public override int GetHashCode() => (int)(this.Value ^ this.Modulo);
	public override string ToString() => this.Value.ToString();

}



