    private int n;
    private int[] a;
    void Solve() {
        //input
        n = io.Int;
        a = new int[n + 1];
        for(int i = 0; i < a.Length; ++i)
            a[i] = io.Int;
        //cal
        var dic = new Dictionary <int, int>();
        foreach(var v in a) {
            if(!dic.ContainsKey(v))
                dic[v] = 0;
            dic[v]++;
        }
        var dup = dic.First(kp => kp.Value == 2).Key;
        var indexedA = a.Select((v, i) => new {value = v, index = i}).ToArray();
        var l = indexedA.First(v => v.value == dup).index;
        var r = indexedA.Last(v => v.value == dup).index;
        var fc=new FastCombination();
        for(int i = 0; i < a.Length; ++i) {
            var ans = fc.Combination(n + 1, i + 1);
            var t = l + n - r;
            if(i <= t)
                ans = ((ans + fc.mod) - fc.Combination(t, i)) % fc.mod;
            //ret
            WriteLine(ans);
        }
    }   
