class FastCombination {
    private int size;
    private long[] fact, invFact;
    public long mod = (long)1e9 + 7;
    public FastCombination(int size = (int)1e5 + 10) => Init(size);
    public void Init(int size) {
        this.size = size;
        fact = new long[size];
        invFact = new long[size];
        fact[0] = 1;
        for(int i = 1; i < size; ++i)
            fact[i] = i * fact[i - 1] % mod;
        for(int i = 0; i < size; ++i)
            invFact[i] = Inverse(fact[i]);
    }
    public long Combination(long n, long r) {
        if(r == 0 || n == r) return 1;
        if(n == 0) return 0;
        if(n < 0 || r < 0 || n < r) throw new ArgumentException("n or r invalid");
        else return (fact[n] * invFact[r] % mod) * invFact[n - r] % mod;
    }
    public long Inverse(long a) {
        long absMod = Math.Abs(mod), b = mod, x = 1, u = 0;
        while(b > 0) {
            var q = a / b;
            var tmp = u;
            u = x - q * u;
            x = tmp;
            tmp = b;
            b = a - q * b;
            a = tmp;
        }
        return x < 0 ? absMod + x : x;
    }
}
