class CombP
  P = 10**9 + 7
  def initialize(n)
    @inv = Array.new(n, 0)
    self.inv(n)
    @fac = Array.new(n, 0)
    @facInv = Array.new(n, 0)
    self.fact(n)
  end
  def inv(n)
    @inv[1] = 1
    (2..n).each do |i|
      @inv[i] = P - ((P / i) * @inv[P % i]) % P
    end
  end
  def fact(n)
    @fac[0] = 1
    @facInv[0] = 1
    (1..n).each do |i|
      @fac[i] = (@fac[i-1] * i) % P
      @facInv[i] = (@facInv[i-1] * @inv[i]) % P
    end
  end
  def choose(n, k)
    if !(0 <= k && k <= n)
      return 0
    end
    return (((@fac[n] * @facInv[k]) % P) * @facInv[n - k]) % P
  end
end

