func c(n int64,k int64) int64 {
  if 2*k > n { return c(n,n-k) }
  var numer,denom int64 = 1,1
  for i:=k;i>0;i-- {
    if (n+i-k)%i == 0 {
      numer *= (n+i-k)/i
      numer %= mod
    } else {
      numer = (numer*(n+i-k))%mod
      denom = (denom*i)%mod
    }
  }
  return (numer*inv(denom))%mod
}
func inv(n int64) int64 {
  if n == int64(1) { return int64(1) }
  var k []int64 = make([]int64,maxsize)
  var t,a,b,ubound,i int64
  var y0,y1 int64
  a,b,t = mod,n,n
  for i=0;i<maxsize;i++ {
    k[i],t = a/b,a%b
    if t == 0 {
      ubound = i+1
      break
    }
    a,b = b,t
  }
  y0,y1 = 1,-k[0]
  for i=2;i<ubound;i++ {
    y0,y1 = y1,y0-k[i-1]*y1
  }
  for ;y1<0; { y1 += mod }
  y1 %= mod
  return y1
}

