func solve() {
	n := ri()
	as := make([]int, n+1)
	for i := 0; i < n+1; i++ {
		as[i] = ri()
	}
	c := NewComb(110000, mod)
	bucket := make([]int, n+1)
	for i := range as {
		bucket[as[i]]++
	}
	dupValue := -1
	for i := range bucket {
		if bucket[i] == 2 {
			dupValue = i
		}
	}
	dupIndexL, dupIndexR := -1, -1
	for i := range as {
		if as[i] != dupValue {
			continue
		}
		if dupIndexL == -1 {
			dupIndexL = i
		} else {
			dupIndexR = i
		}
	}
	l := dupIndexL
	r := n - dupIndexR
	for k := 1; k <= n+1; k++ {
		if k == 1 {
			all := n + 1
			dup := 1
			pln(ModSum(all, -dup, mod))
			continue
		}
		all := c.NCK(n+1, k)
		dup := c.NCK(l+r, k-1)
		pln(ModSum(all, -dup, mod))
	}
}

