func main() {
	n = ReadInt()
	A = ReadIntSlice(n + 1)

	dup := findDup()
	pos := []int{}
	for i := 0; i < len(A); i++ {
		if A[i] == dup {
			pos = append(pos, i)
		}
	}
	x := pos[1] - pos[0] - 1
	PrintDebug("x: %d\n", x)

	if n == 1 {
		fmt.Println(1)
		fmt.Println(1)
		return
	}

	cf := NewCombFactorial()
	for k := 1; k <= n+1; k++ {
		if k == 1 {
			fmt.Println(n)
			continue
		}

		if k == n+1 {
			fmt.Println(1)
			continue
		}

		two := cf.C(n-1, k-2)
		one := cf.C(n-1, k-1)
		nn := n - 1 - x
		comp := 0
		if nn >= k-1 {
			comp = cf.C(nn, k-1)
		}
		// ex := one - comp
		ex := NegativeMod(one-comp, MOD)

		ans := two + one
		ans %= MOD
		ans += ex
		ans %= MOD
		if k < n {
			zero := cf.C(n-1, k)
			ans %= MOD
			ans += zero
			ans %= MOD

			fmt.Println(ans)
			continue
		}

		// k==nのときは片方は選ばなければならない
		fmt.Println(ans)
	}
}

func findDup() int {
	memo := make(map[int]int)
	for _, a := range A {
		memo[a]++
	}

	for k, v := range memo {
		if v == 2 {
			return k
		}
	}
	return -1
}

// NegativeMod can calculate a right residual whether value is positive or negative.
func NegativeMod(val, m int) int {
	res := val % m
	if res < 0 {
		res += m
	}
	return res
}

// cf = NewCombFactorial()
// res := cf.C(n, r) 	// 組み合わせ
// res := cf.H(n, r) 	// 重複組合せ
// res := cf.P(n, r) 	// 順列
var cf *CombFactorial

const MAX_NUM = 100000 + 5

type CombFactorial struct {
	factorial, modFactorial [MAX_NUM + 5]int
}

func NewCombFactorial() *CombFactorial {
	cf := new(CombFactorial)
	cf.initCF()

	return cf
}
func (c *CombFactorial) modInv(a int) int {
	return c.modpow(a, MOD-2)
}
func (c *CombFactorial) modpow(a, e int) int {
	if e == 0 {
		return 1
	}

	if e%2 == 0 {
		halfE := e / 2
		half := c.modpow(a, halfE)
		return half * half % MOD
	}

	return a * c.modpow(a, e-1) % MOD
}
func (c *CombFactorial) initCF() {
	for i := 0; i <= MAX_NUM; i++ {
		if i == 0 {
			c.factorial[i] = 1
			c.modFactorial[i] = c.modInv(c.factorial[i])
			continue
		}

		num := i * c.factorial[i-1]
		num %= MOD
		c.factorial[i] = num
		c.modFactorial[i] = c.modInv(c.factorial[i])
	}
}
func (c *CombFactorial) C(n, r int) int {
	res := 1
	res *= c.factorial[n]
	res %= MOD
	res *= c.modFactorial[r]
	res %= MOD
	res *= c.modFactorial[n-r]
	res %= MOD

	return res
}
func (c *CombFactorial) P(n, r int) int {
	res := 1
	res *= c.factorial[n]
	res %= MOD
	res *= c.modFactorial[n-r]
	res %= MOD

	return res
}
func (c *CombFactorial) H(n, r int) int {
	return c.C(n-1+r, r)
}

