func expMod(n, e, m int) int {
	square := func(a int) int {
		return a * a
	}
	if e == 0 {
		return 1
	}
	if e&1 == 1 {
		return n * expMod(n, e-1, m) % m
	} else {
		return square(expMod(n, e/2, m)) % m
	}
}

func divModByPrime(n, d, p int) int {
	return n * expMod(d, p-2, p) % p
}

func combModByPrime(n, k, p int) int {
	if n < k*2 {
		k = n - k
	}
	v := 1
	for i := 0; i < k; i++ {
		v = v * (n - i) % p
	}
	for i := 1; i <= k; i++ {
		v = divModByPrime(v, i, p)
	}
	return v
}

