/* fact */
func fact(x int, factMem map[int]int) int {
    if x == 0 {
        return 1
    }
    value, ok := factMem[x]
    if ok {
        return value
    }
    factMem[x] = x * fact(x - 1, factMem) % MOD
    return factMem[x]
}

/* inverse */
func inverse(x int, factMem map[int]int, inverseMem map[int]int) int {
    value, ok := inverseMem[x]
    if ok {
        return value
    }
    inverseMem[x] = power(fact(x, factMem), MOD - 2, MOD)
    return inverseMem[x]
}

/* power */
func power(x, y, z int) int {
    if y == 0 {
        return 1
    }
    if y % 2 == 0 {
        return power(x * x % z, y / 2, z)
    } else {
        return x * power(x, y - 1, z) % z
    }
    return 0
}

/* comb */
func comb(x int, y int, factMem map[int]int, inverseMem map[int]int) int {
    if x < y || y < 0 {
        return 0
    }
    return fact(x, factMem) * inverse(y, factMem, inverseMem) % MOD * inverse(x - y, factMem, inverseMem) % MOD
}

