let ( *@ ) a b = a * b mod modulo
let ( -@ ) a b = (a - b + modulo) mod modulo
let rec mod_pow a n =
  if n <= 0 then 1
  else if n mod 2 = 1 then a *@ mod_pow a (n-1)
  else let h = mod_pow a (n/2) in h *@ h
let mod_inv a = mod_pow a (modulo-2)

