const MOD = 1e9.int + 7

proc C*(n, r:  int): int =
  if (n - r) < r    : return n.C(n - r)
  if r == 0         : return 1
  if r == n         : return n

  var
    numerator   = newSeq[int](r)
    denominator = newSeq[int](r)

  for k in 0..<r :
    numerator[k]   = n - r + k + 1
    denominator[k] = k + 1

  for p in 2..r :
    let pivot = denominator[p - 1]
    if pivot > 1 :
      let offset = (n - r) mod p
      for k in countup(p - 1, r - 1, p) :
        numerator[k - offset] = numerator[k - offset] div pivot
        denominator[k]        = denominator[k]        div pivot

  result = 1
  for k in 0..<r :
    if numerator[k] > 1 :
      result = result * numerator[k] mod MOD

# # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #
proc sameValueIndexes(a: seq[int]): tuple[l, r: int] =
  var
    countSeq = newSeq[int](1e5.int + 1)
    flag = false
  for v in a:
    countSeq[v].inc
  for i, v in countSeq:
    if v > 1:
      for j, u in a:
        if i == a[j]:
          if flag:
            result.r = j
          else:
            result.l = j
            flag = true
            continue

let
  n = input(int, 1)
  a = input(int, 0)
  (l, r) = a.sameValueIndexes
for k in 1..(n + 1):
  echo (n + 1).C(k) - (if l + n - r >= (k - 1): (l + n - r).C(k - 1) else: 0)

