def getWhereW(n, a):
    Idx = [-1] * n
    for i in range(n+1):
        if Idx[a[i]-1] == -1:
            Idx[a[i]-1] = i
        else:
            return Idx[a[i]-1], i

def combinations(n) -> List[int]:
    Result: List[int] = [1] * (n+1)
    for i in count(1):
        if i > n: break
        Result[i] = Result[i-1] * (n+1-i) // i
    return [res%mod for res in Result]


def main():
    with open(0) as f:
        n, *a = map(int, f.read().split())
    l, r = getWhereW(n, a)
