    Comb_1: List[int] = combinations(n+1)
    Comb_2: List[int] = combinations(n-r+l)
    for k in count(1):
        if k > n+1: break

        if k-1 <= n-r+l:
            ans = Comb_1[k] - Comb_2[k-1]
        else:
            ans = Comb_1[k]
        print(ans)

