    if k > n:
        return 0
    if k > n - k:
        k = n - k
    if k == 0:
        return 1
    if k == 1:
        return n
    if (n, k) in cache:
        return cache[n, k]
    res = comb(n - 1, k) + comb(n - 1, k - 1)
    cache[n, k] = res
    return res


