class ModWorld:
    def __init__(self, mod):
        self.mod = mod

    def prepare_factorial(self, N):
        self.f = [1]*(N+1) # f[n] := n!
        p = 1
        for i in range(1,N+1):
            p = (p*i) % self.mod
            self.f[i] = p

        self.finv = [None]*(N+1)
        for i, s in enumerate(self.f):
            self.finv[i] = self.modpow(s, -1)

    def modpow(self, x, k):
        x %= self.mod
        k %= self.mod-1 # a^(p-1) = 1
        retval = 1
        while k:
            if k&1: retval = retval*x % self.mod
            k>>=1
            x = x*x % self.mod

        return retval

    def modcomb(self, n, k):
        return self.f[n] * self.finv[n-k] * self.finv[k] % self.mod

