def exteuc(a, b):
    # ax + by = gcd(a, b)
    if b == 0:
        return 1, 0, a
    y, x, v = exteuc(b, a % b)
    y -= (a//b) * x
    return x, y, v


def modinv(a, mod):
    x, _, _ = exteuc(a, mod)
    return x % mod


def comb(n, k, mod, precalc_modinvs):
    if k > n//2:
        return comb(n, n - k, mod, precalc_modinvs)
    ret = 1
    for i in range(k):
        ret *= n - i
        ret *= precalc_modinvs[k - i]
        ret %= mod
    return ret


