def mod_pow(a, x, p):
    # return a^x mod p
    res = 1
    while x > 0:
        if(x & 1):
            res = (res * a) % p
        a = (a * a) % p;
        x >>= 1;
    return res


def mod_inverse(a, p):
    return mod_pow(a, p-2, p);


def mod_binomial(n, k, p):
    numerator = 1;
    for i in range(k):
        numerator = (numerator * (n - i)) % p;

    denominator = 1;
    for i in range(k):
        denominator = (denominator * (i + 1)) % p;

    res = mod_inverse(denominator, p);
    res = (res * numerator) % p;
    return res;


def get_same_indices(arr):
    mem = [-1 for _ in arr]
    for i in range(len(arr)):
        n = arr[i]
        if not mem[n] == -1:
            return (mem[n], i)
        mem[n] = i


def calc_comb(n, k, same_indices):
    mod = 1000000007
    total = mod_binomial(n + 1, k, mod)

    if k == 1:
        return n

    former_c = same_indices[0]
    former_dup = 0
    if not former_c == 0:
        if k > 1:
            former_dup += mod_binomial(former_c, k - 1, mod)
        if k > 2:
            former_dup += mod_binomial(former_c, k - 2, mod)

    latter_c = n - same_indices[1]
    latter_dup = 0
    if not latter_c == 0:
        if k > 1:
            latter_dup += mod_binomial(latter_c, k - 1, mod)
    return (total - former_dup - latter_dup) % mod


