def mod_pow(a, x, p):
    # return a^x mod p
    res = 1
    while x > 0:
        if(x & 1):
            res = (res * a) % p
        a = (a * a) % p;
        x >>= 1;
    return res


def mod_inverse(a, p):
    return mod_pow(a, p-2, p);


def mod_binomial(n, k, p):
    numerator = 1;
    for i in range(k):
        numerator = (numerator * (n - i)) % p;

    denominator = 1;
    for i in range(k):
        denominator = (denominator * (i + 1)) % p;

    res = mod_inverse(denominator, p);
    res = (res * numerator) % p;
    return res;


