#[doc = " a / b modulo m == a * modinv(b, m) % m"]
#[allow(dead_code)]
fn modinv(a_: u64, m_: u64) -> u64 {
    let m = m_ as i64;
    let mut a = a_ as i64;
    let mut b = m as i64;
    let mut u = 1;
    let mut v = 0;
    while b != 0 {
        let t = a / b;
        a -= t * b;
        std::mem::swap(&mut a, &mut b);
        u -= t * v;
        std::mem::swap(&mut u, &mut v);
    }
    u %= m;
    if u < 0 {
        u += m
    };
    u as u64
}
#[doc = " nC0 ... nCn mod m"]
#[allow(dead_code)]
fn comb_series(n: u64, m: u64) -> Vec<u64> {
    let mut ret = vec![];
    let mut comb = 1;
    for i in 0..n + 1 {
        ret.push(comb);
        comb = comb * (n - i) % m * modinv(i + 1, m) % m;
    }
    ret
}

