fn comb(n: i64, k: i64, fact: &[i64]) -> i64 {
    if n < 0 || k < 0 || n < k {
        return 0;
    }
    (((fact[n as usize] * pow(fact[k as usize], MOD - 2)) % MOD)
        * pow(fact[(n - k) as usize], MOD - 2))
        % MOD
}

