const MOD: i64 = 1_000_000_007;

fn fact(n: i64) -> i64 {
    let mut ret = 1;
    for i in 1..(n + 1) {
        ret *= i;
        ret %= MOD;
    }
    ret
}

#[test]
fn test_fact() {
    assert_eq!(fact(3), 6);
    assert_eq!(fact(5), 120)
}

fn pow(a: i64, mut b: i64) -> i64 {
    let mut base = a;
    let mut acc = 1;
    while b > 1 {
        if b % 2 == 1 {
            acc = acc * base % MOD;
        }
        b /= 2;
        base = base * base % MOD;
    }
    if b == 1 {
        acc = acc * base % MOD;
    }
    acc % MOD
}

#[test]
fn test_pow() {
    assert_eq!(pow(2, 5), 32);
}

fn comb(n: i64, k: i64) -> i64 {
    if n < 0 || k < 0 || n < k {
        return 0;
    }
    (((fact(n) * pow(fact(k), MOD - 2)) % MOD) * pow(fact(n - k), MOD - 2)) % MOD
}

#[test]
fn test_comb() {
    assert_eq!(comb(3, 2), 3);
    assert_eq!(comb(10, 4), 210);
}

fn main() {
    let n = scan!(i64);
    let vs = scan!(i64;;);
    let mut sorted = vs.clone();
    sorted.sort();

    let mut dup = 0;
    for (&v1, &v2) in sorted.iter().zip(sorted[1..].iter()) {
        if v1 == v2 {
            dup = v1;
            break;
        }
    }
    let l = vs.iter().position(|&x| x == dup).unwrap() as i64;
    let r = (vs.len() - vs.iter().rposition(|&x| x == dup).unwrap() - 1) as i64;
    for i in 1i64..(n + 2) {
        println!("{}", comb(n + 1, i) - comb(l + r, i - 1))
    }
}

