const MOD: i64 = 1_000_000_007;

fn pow(a: i64, mut b: i64) -> i64 {
    let mut base = a;
    let mut acc = 1;
    while b > 1 {
        if b % 2 == 1 {
            acc = acc * base % MOD;
        }
        b /= 2;
        base = base * base % MOD;
    }
    if b == 1 {
        acc = acc * base % MOD;
    }
    acc % MOD
}

#[test]
fn test_pow() {
    assert_eq!(pow(2, 5), 32);
}

fn comb(n: i64, k: i64, fact: &[i64]) -> i64 {
    if n < 0 || k < 0 || n < k {
        return 0;
    }
    if n == 0 || k == 0 {
        return 1;
    }

    (((fact[n as usize] * pow(fact[k as usize], MOD - 2)) % MOD)
        * pow(fact[(n - k) as usize], MOD - 2))
        % MOD
}

#[test]
fn test_comb() {
    let mut fact: Vec<_> = (0..100_002).collect();
    for i in 1..(fact.len() - 1) {
        fact[i + 1] *= fact[i];
        fact[i + 1] %= MOD;
    }
    assert_eq!(fact[3], 6);
    assert_eq!(comb(3, 2, &fact), 3);
    assert_eq!(comb(10, 4, &fact), 210);
    assert_eq!(comb(0, 3, &fact), 1);
    assert_eq!(comb(10, 0, &fact), 1);
}

