use proconio::input;
use proconio::marker::{Bytes, Chars};
use std::collections::*;

fn main() {
    input! {
        n:usize,
        a:[usize;n+1],
    }
    let a = a.iter().map(|&x| x - 1).collect::<Vec<_>>();
    let mut count = vec![0; n];
    for &x in a.iter() {
        count[x] += 1;
    }
    let duplicate = (0..n).find(|&x| count[x] == 2).unwrap();
    let dupls = (0..(n + 1))
        .filter(|&x| a[x] == duplicate)
        .collect::<Vec<_>>();
    let modulo = 1e9 as i64 + 7;
    let comb = CombinationMod::new(n + 1, modulo);
    let n = n as i64;
    let first = dupls[0] as i64;
    let last = n - dupls[1] as i64;
    for i in 1..=(n + 1) {
        let a = if i <= n - 1 { comb.query(n - 1, i) } else { 0 };
        let b = if i - 1 <= n - 1 {
            comb.query(n - 1, i - 1)
        } else {
            0
        };
        let c = b;
        let e = if i - 1 <= first + last {
            comb.query(first + last, i - 1)
        } else {
            0
        };
        let d = (b + c + modulo - e) % modulo;
        let f = if i >= 2 { comb.query(n - 1, i - 2) } else { 0 };
        let ans = (a + d + f) % modulo;
        println!("{}", ans);
    }
}

struct CombinationMod {
    fac: Vec<i64>,
    inv: Vec<i64>,
    inv_fac: Vec<i64>,
    modulo: i64,
}
impl CombinationMod {
    pub fn new(size: usize, modulo: i64) -> CombinationMod {
        let mut fac = vec![1; size + 1];
        let mut inv = vec![1; size + 1];
        let mut inv_fac = vec![1; size + 1];
        for i in 2..=size {
            fac[i] = fac[i - 1] * i as i64 % modulo;
            inv[i] = modulo - inv[modulo as usize % i] * (modulo / i as i64) % modulo;
            inv_fac[i] = inv_fac[i - 1] * inv[i] % modulo;
        }
        CombinationMod {
            fac: fac,
            inv: inv,
            inv_fac: inv_fac,
            modulo: modulo,
        }
    }
    fn query(&self, n: i64, r: i64) -> i64 {
        self.fac[n as usize] * self.inv_fac[r as usize] % self.modulo
            * self.inv_fac[(n - r) as usize]
            % self.modulo
    }
    fn inverse(&self, n: i64) -> i64 {
        self.inv[n as usize]
    }
}

