fn solve() {
    let n = get!(usize);
    let a = get!([usize]);

    let mut appeared = vec![false; n+1];
    let mut num = 0;
    for i in 0..n {
        if appeared[a[i]] {
            num = a[i];
        }
        appeared[a[i]] = true;
    }
    let mut left = 0;
    let mut right = 0;
    let mut already = false;
    for i in 0..n+1 {
        if a[i] == num {
            if already {
                right = n - i;
                break;
            } else {
                already = true;
                left = i;
            }
        }
    }
    println!("{}", n);
    if n == 1 {
        println!("1");
        return;
    }


    let comb = Comb::new(n+1);
    for i in 2..left+right+2 {
        println!("{}", ModInt::new(comb.compute(n+1,i))-ModInt::new(comb.compute(left+right, i-1)));
    }
    for i in left+right+2..n+2 {
        println!("{}", comb.compute(n+1, i));
    }
}

