    let mut al = 0;
    let mut am = 0;
    let mut ar = 0;
    for i in 0..a.len() {
        if pos[a[i]].is_none() {
            pos[a[i]] = Some(i);
        } else {
            ai = pos[a[i]].unwrap();
            aj = i;
            al = ai;
            am = aj - ai - 1;
            ar = a.len() - aj - 1;
            break;
        }
    }
    let comb = Combination::new(n + 10, M);

    for i in 1..n + 2 {
        let mut ans = 0;
        ans += comb.C(n - 1, i);
        ans %= M;

        if i >= 1 {
            ans += comb.C(al + am + ar, i - 1) * 2;
            ans %= M;

            ans += M - comb.C(al + ar, i - 1);
            ans %= M;
        }

        if i >= 2 {
            ans += comb.C(al + am + ar, i - 2);
            ans %= M;
        }
        println!("{}", ans);
    }
}

