    let mut l = 0;
    let mut r = 0;
    for i in 0..a.len() {
        if let Some(src) = indices[a[i]] {
            l = src;
            r = i;
            break;
        }
        indices[a[i]] = Some(i);
    }

    let mut comb_n1 = 1i64;
    let mut comb_rest = 1i64;
    for k in 1..n+2 {
        comb_n1 = (comb_n1 * (n+1-(k-1)) as i64) % M * modinv(k as i64, M);
        comb_n1 %= M;
        let mut ret = comb_n1;
        if k >= 2 && l+n-r >= k-1 {
            comb_rest = (comb_rest * (l+n-r-(k-2)) as i64) % M * modinv(k as i64 - 1,M);
            comb_rest %= M;
            ret = (ret - comb_rest) % M;
        } else if k == 1 {
            ret = (ret - 1) % M;
        }
        if ret < 0 {
            ret += M;
        }
        println!("{}", ret);
    }
}

#[doc = " a / b modulo m == a * modinv(b, m) % m"]
#[allow(dead_code)]
fn modinv(mut a: i64, m: i64) -> i64 {
    let mut b = m;
    let mut u = 1;
    let mut v = 0;
    while b != 0 {
        let t = a / b;
        a -= t * b;
        std::mem::swap(&mut a, &mut b);
        u -= t * v;
        std::mem::swap(&mut u, &mut v);
    }
    u %= m;
    if u < 0 {
        u += m
    };
    u
}

