const MOD: i64 = 1_000_000_007;

fn pow(a: i64, mut b: i64) -> i64 {
    let mut base = a;
    let mut acc = 1;
    while b > 1 {
        if b % 2 == 1 {
            acc = acc * base % MOD;
        }
        b /= 2;
        base = base * base % MOD;
    }
    if b == 1 {
        acc = acc * base % MOD;
    }
    acc % MOD
}

