fn main() {
    let mut scanner = Scanner::new(stdin());
    let n = scanner.read::<u64>().unwrap();
    let arr = scanner.read_vector::<u64>().unwrap();
    let mut counts = vec![vec![]; n as usize];
    let (mut former, mut latter) = (0, 0);
    for i in 0..((n + 1) as usize) {
        let index = (arr[i] - 1) as usize;
        counts[index].push(i);
        if counts[index].len() == 2 {
            former = counts[index][0] as u64;
            latter = counts[index][1] as u64;
            break;
        }
    }
    let num = former + n - latter;
    let mut all = 1;
    let mut dup = 1;
    for i in 1..((n + 2) as u64){
        all *= n + 1 - i + 1;
        all %= MOD;
        all *= power(i, MOD - 2, MOD);
        all %= MOD;
        if i > 1 && dup > 0 {
            dup *= num + 2 - i;
            dup %= MOD;
            dup *= power(i - 1, MOD - 2, MOD);
            dup %= MOD;
        }
        let ans = (all + MOD - dup) % MOD;
        println!("{}", ans);
    }
}

fn power(x: u64, mut k: u64, modulo: u64) -> u64 {
    let mut pows = vec![x];
    for i in 0..63 {
        let square = (pows[i] * pows[i]) % modulo;
        pows.push(square);
    }
    let mut pow = 1;
    for i in 0..64 {
        let flag = k & 1;
        k >>= 1;
        if flag == 1 {
            pow = (pow * pows[i]) % modulo;
        }
    }
    pow
}

